Object.assign(MOVIE_MENU_EDITIONS,{"Con Air (1997)":{"poster":"assets/menu-posters/con-air-1997.jpg","colour":"#b86427","servings":4,"tagline":"Put the bunny back in the box.","cue":"Serve dessert when Poe finally hands over the bunny.","menu":{"s":[{"n":"Jailbird peanuts","note":"Warm chilli honey peanuts in little paper bags","how":"Toss 300g honey-roasted peanuts with half a tsp chilli flakes and a pinch of smoked salt. Warm on a tray at 160C for 5 minutes, then cool for a few minutes. Divide between four small paper bags.","shop":["300g honey-roasted peanuts@Pantry","1 jar chilli flakes@Pantry","1 jar smoked salt@Pantry"]},{"n":"Vegas strip prawns","note":"Prawn cocktail in martini glasses with spicy cocktail sauce","how":"Poach 500g green prawns for 2 minutes, plunge into iced water and peel. Mix 100ml tomato sauce with 1 tbsp horseradish, lemon juice and a dash of hot sauce. Serve on shredded iceberg in martini glasses with lemon wedges.","shop":["500g green prawns@Seafood","0.5 iceberg lettuce@Produce","1 bottle tomato sauce@Pantry","1 jar horseradish@Pantry","2 lemons@Produce","1 bottle hot sauce@Pantry"]}],"m":[{"n":"Vegas buffet steak","note":"Garlic butter sirloin with a loaded baked potato","how":"Bake 4 large potatoes at 200C for an hour. Sear 4 sirloins hard and rest 5 minutes. Mash 60g butter with 2 garlic cloves and put a slice on each steak. Split the potatoes and load with sour cream and chives.","shop":["4 potatoes@Produce","4 sirloin steaks@Meat","60g butter@Dairy","2 garlic cloves@Produce","200g sour cream@Dairy","1 bunch chives@Produce"]}],"w":[{"n":"Bunny cake","note":"Vanilla cake shaped like a bunny, covered in coconut","how":"Cut a round sponge cake into a body and two ears. Beat 200g butter with 350g icing sugar and cover the cake. Press 100g shredded coconut all over. Tint a little coconut pink for the ears and put it in a box with a bow.","shop":["1 sponge cake@Bakery","200g butter@Dairy","350g icing sugar@Pantry","100g shredded coconut@Pantry","1 bottle pink food colouring@Pantry"]}],"d":[{"n":"Cyrus's bourbon","note":"Bourbon neat in a tumbler with water on the side","how":"Pour 45ml bourbon neat into each of four heavy tumblers. Put a jug of cool water on the table for anyone who wants a few drops. Sip it slowly while the rest of the cons argue.","shop":["180ml bourbon@Bottle shop"]}],"shopping":["300g honey-roasted peanuts@Pantry","1 jar chilli flakes@Pantry","1 jar smoked salt@Pantry","500g green prawns@Seafood","0.5 iceberg lettuce@Produce","1 bottle tomato sauce@Pantry","1 jar horseradish@Pantry","2 lemons@Produce","1 bottle hot sauce@Pantry","4 potatoes@Produce","4 sirloin steaks@Meat","260g butter@Dairy","2 garlic cloves@Produce","200g sour cream@Dairy","1 bunch chives@Produce","1 sponge cake@Bakery","350g icing sugar@Pantry","100g shredded coconut@Pantry","1 bottle pink food colouring@Pantry","180ml bourbon@Bottle shop"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Under Siege (1992)":{"poster":"assets/menu-posters/under-siege-1992.jpg","colour":"#25465a","servings":4,"tagline":"Just a cook.","cue":"Serve dinner when Casey Ryback reveals he's just a cook.","menu":{"s":[{"n":"Galley bread rolls","note":"Soft milk rolls brushed with butter and flaky salt","how":"Mix 500g bread flour, 7g yeast, 300ml warm milk, 50g butter, 2 tbsp sugar and 1 egg into a soft dough. Prove an hour, shape 12 rolls and prove 30 minutes more. Bake at 190C for 18 minutes and brush with butter and flaky salt.","shop":["500g bread flour@Pantry","7g dried yeast@Pantry","300ml full cream milk@Dairy","80g butter@Dairy","1 bag caster sugar@Pantry","1 egg@Dairy","1 box sea salt flakes@Pantry"]},{"n":"Birthday cake bites","note":"Little squares of sponge with jam and cream","how":"Cut a sponge cake into 16 small squares and split each in half. Whip 300ml cream to soft peaks. Fill each with a little raspberry jam and cream, put the tops back on and dust with icing sugar.","shop":["1 sponge cake@Bakery","300ml thickened cream@Dairy","1 jar raspberry jam@Pantry","50g icing sugar@Pantry"]}],"m":[{"n":"Ryback's bouillabaisse","note":"Saffron fish stew with rouille and toasted baguette","how":"Soften 1 fennel, 1 leek, 1 onion and 3 garlic cloves in oil with saffron, orange peel and 1 tin tomatoes. Add 1L fish stock and simmer 20 minutes. Add 500g fish, then 500g mussels and 300g prawns. Serve with rouille and toasted baguette.","shop":["1 fennel bulb@Produce","1 leek@Produce","1 onion@Produce","3 garlic cloves@Produce","1 packet saffron@Pantry","1 orange@Produce","1 tin crushed tomatoes@Pantry","1L fish stock@Pantry","500g firm white fish@Seafood","500g mussels@Seafood","300g green prawns@Seafood","1 baguette@Bakery","1 jar aioli@Pantry"]}],"w":[{"n":"Captain's birthday cake","note":"Vanilla layer cake piped Happy Birthday Captain in blue","how":"Beat 200g butter and 200g sugar, add 4 eggs and fold in 200g self-raising flour. Bake in two tins at 175C for 25 minutes. Beat 250g butter with 400g icing sugar, fill and cover the cake, then pipe the message in blue.","shop":["450g butter@Dairy","200g caster sugar@Pantry","4 eggs@Dairy","200g self-raising flour@Pantry","400g icing sugar@Pantry","1 bottle blue food colouring@Pantry"]}],"d":[{"n":"Navy galley coffee","note":"Strong black drip coffee in steel mugs","how":"Brew 70g ground coffee with 1L water in a drip machine so it comes out strong. Pour black into steel mugs, no milk, no sugar, and keep the pot going all night like a ship's galley.","shop":["70g ground coffee@Pantry"]}],"shopping":["500g bread flour@Pantry","7g dried yeast@Pantry","300ml full cream milk@Dairy","530g butter@Dairy","1 egg@Dairy","1 box sea salt flakes@Pantry","1 sponge cake@Bakery","300ml thickened cream@Dairy","1 jar raspberry jam@Pantry","450g icing sugar@Pantry","1 fennel bulb@Produce","1 leek@Produce","1 onion@Produce","3 garlic cloves@Produce","1 packet saffron@Pantry","1 orange@Produce","1 tin crushed tomatoes@Pantry","1L fish stock@Pantry","500g firm white fish@Seafood","500g mussels@Seafood","300g green prawns@Seafood","1 baguette@Bakery","1 jar aioli@Pantry","200g caster sugar@Pantry","4 eggs@Dairy","200g self-raising flour@Pantry","1 bottle blue food colouring@Pantry","70g ground coffee@Pantry"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Alien (1979)":{"poster":"assets/menu-posters/alien-1979.jpg","colour":"#4a6744","servings":4,"tagline":"In space, no one can hear you crunch.","cue":"Serve the mains at the crew dinner, before Kane starts feeling unwell.","menu":{"s":[{"n":"Nostromo crew noodles","note":"Cold sesame noodles with chilli oil and cucumber","how":"Cook 400g fresh wheat noodles, rinse cold and drain. Whisk 3 tbsp sesame paste, 2 tbsp soy, 1 tbsp black vinegar, 1 tbsp chilli oil and a crushed garlic clove. Toss through and top with cucumber matchsticks and spring onion.","shop":["400g fresh wheat noodles@Produce","1 jar sesame paste@Pantry","1 bottle soy sauce@Pantry","1 bottle black vinegar@Pantry","1 jar chilli oil@Pantry","1 garlic clove@Produce","1 Lebanese cucumber@Produce","1 bunch spring onions@Produce"]},{"n":"Freighter stores crackers","note":"Seeded crackers with lemon cream cheese and smoked oysters","how":"Whip 150g cream cheese with the zest of a lemon. Spread on 16 seeded crackers and top each with a smoked oyster from 2 drained tins. Finish with cracked pepper and snipped chives. Serve straight away.","shop":["150g cream cheese@Dairy","1 lemon@Produce","1 packet seeded crackers@Pantry","2 tins smoked oysters@Pantry","1 bunch chives@Produce"]}],"m":[{"n":"Nostromo crew dinner","note":"Pork and vegetable noodle stir-fry in bowls","how":"Slice 500g pork shoulder thin and toss with soy. Stir-fry in a smoking wok, then add a quarter cabbage, 2 carrots and 1 capsicum, all sliced, with grated ginger. Add 400g egg noodles, 3 tbsp oyster sauce and 2 tbsp soy, toss and serve in bowls.","shop":["500g pork shoulder@Meat","1 bottle soy sauce@Pantry","0.25 cabbage@Produce","2 carrots@Produce","1 red capsicum@Produce","1 knob ginger@Produce","400g fresh egg noodles@Produce","1 bottle oyster sauce@Pantry"]}],"w":[{"n":"Red velvet chestburster cake","note":"Red velvet dome that bursts with raspberry jam when cut","how":"Beat 125g butter and 250g sugar, add 2 eggs, then fold in 250g self-raising flour, 2 tbsp cocoa, 250ml buttermilk, 1 tsp vinegar and red colouring. Bake in a bowl at 170C for 50 minutes. Hollow, fill with raspberry jam and cover in cream cheese frosting.","shop":["125g butter@Dairy","250g caster sugar@Pantry","2 eggs@Dairy","250g self-raising flour@Pantry","1 tin cocoa@Pantry","250ml buttermilk@Dairy","1 bottle white vinegar@Pantry","1 bottle red food colouring@Pantry","1 jar raspberry jam@Pantry","250g cream cheese@Dairy","200g icing sugar@Pantry"]}],"d":[{"n":"Wake-up coffee","note":"Drip coffee with milk and sugar before the signal","how":"Brew 60g ground coffee with 1L water in a drip machine. Pour into four mugs and leave milk and sugar on the table for everyone. Drink it before anyone goes to check on a distress signal.","shop":["60g ground coffee@Pantry","200ml full cream milk@Dairy","1 bag caster sugar@Pantry"]}],"shopping":["400g fresh wheat noodles@Produce","1 jar sesame paste@Pantry","1 bottle soy sauce@Pantry","1 bottle black vinegar@Pantry","1 jar chilli oil@Pantry","1 garlic clove@Produce","1 Lebanese cucumber@Produce","1 bunch spring onions@Produce","400g cream cheese@Dairy","1 lemon@Produce","1 packet seeded crackers@Pantry","2 tins smoked oysters@Pantry","1 bunch chives@Produce","500g pork shoulder@Meat","0.25 cabbage@Produce","2 carrots@Produce","1 red capsicum@Produce","1 knob ginger@Produce","400g fresh egg noodles@Produce","1 bottle oyster sauce@Pantry","125g butter@Dairy","250g caster sugar@Pantry","2 eggs@Dairy","250g self-raising flour@Pantry","1 tin cocoa@Pantry","250ml buttermilk@Dairy","1 bottle white vinegar@Pantry","1 bottle red food colouring@Pantry","1 jar raspberry jam@Pantry","200g icing sugar@Pantry","60g ground coffee@Pantry","200ml full cream milk@Dairy"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Lethal Weapon 3 (1992)":{"poster":"assets/menu-posters/lethal-weapon-3-1992.jpg","colour":"#92352b","servings":4,"tagline":"Eight days left. Make every meal count.","cue":"Pour drinks during the retirement countdown.","menu":{"s":[{"n":"Hockey game hot dogs","note":"Griddled franks with mustard, relish and chopped onion","how":"Simmer 8 franks in water for 5 minutes, then griddle until blistered all over. Steam 8 hot dog buns until soft. Fill with franks and top with yellow mustard, sweet relish and a spoon of finely chopped onion.","shop":["8 hot dog franks@Meat","8 hot dog buns@Bakery","1 bottle yellow mustard@Pantry","1 jar sweet relish@Pantry","1 onion@Produce"]},{"n":"Building implosion popcorn","note":"Garlic parmesan popcorn piled high in a big bowl","how":"Heat 2 tbsp oil in a big pot with 3 kernels. When they pop, add 120g kernels, cover and shake until popping slows. Toss with 50g melted butter, 1 tsp garlic powder and 40g finely grated parmesan while still hot.","shop":["120g popcorn kernels@Pantry","1 bottle vegetable oil@Pantry","50g butter@Dairy","1 jar garlic powder@Pantry","40g parmesan@Deli"]}],"m":[{"n":"Trish's chicken and dumplings","note":"Creamy chicken stew with fluffy dumplings steamed on top","how":"Simmer 800g chicken thighs with 1 onion, 2 celery sticks, 2 carrots, thyme and 1.5L stock for 40 minutes. Shred the chicken back in. Mix 200g self-raising flour, 50g butter and 150ml milk, drop spoonfuls on top and steam covered for 15 minutes.","shop":["800g chicken thighs@Meat","1 brown onion@Produce","2 celery sticks@Produce","2 carrots@Produce","1 bunch thyme@Produce","1.5L chicken stock@Pantry","200g self-raising flour@Pantry","50g butter@Dairy","150ml full cream milk@Dairy"]}],"w":[{"n":"Retirement cake","note":"Lemon drizzle loaf soaked in lemon syrup while hot","how":"Beat 175g butter with 175g sugar, add 3 eggs, then fold in 175g self-raising flour and the zest of 2 lemons. Bake at 170C for 50 minutes. Mix the juice of 2 lemons with 100g sugar and pour over the hot loaf.","shop":["175g butter@Dairy","275g caster sugar@Pantry","3 eggs@Dairy","175g self-raising flour@Pantry","2 lemons@Produce"]}],"d":[{"n":"Retirement beer","note":"Eight lagers in a bucket of ice, one for every day","how":"Fill a bucket with a bag of ice and some cold water. Bury eight 355ml bottles of American lager for 30 minutes until icy. Crack them open and toast to how close everyone is to retirement.","shop":["8 355ml bottles American lager@Bottle shop","1 bag ice@Frozen"]}],"shopping":["8 hot dog franks@Meat","8 hot dog buns@Bakery","1 bottle yellow mustard@Pantry","1 jar sweet relish@Pantry","1 onion@Produce","120g popcorn kernels@Pantry","1 bottle vegetable oil@Pantry","275g butter@Dairy","1 jar garlic powder@Pantry","40g parmesan@Deli","800g chicken thighs@Meat","1 brown onion@Produce","2 celery sticks@Produce","2 carrots@Produce","1 bunch thyme@Produce","1.5L chicken stock@Pantry","375g self-raising flour@Pantry","150ml full cream milk@Dairy","275g caster sugar@Pantry","3 eggs@Dairy","2 lemons@Produce","8 355ml bottles American lager@Bottle shop","1 bag ice@Frozen"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Dragnet (1987)":{"poster":"assets/menu-posters/dragnet-1987.jpg","colour":"#183d58","servings":4,"tagline":"Just the facts. And the food.","cue":"Serve dinner when Friday and Streebek go undercover at the PAGAN ceremony.","menu":{"s":[{"n":"PAGAN ceremony snacks","note":"Stuffed mushrooms with cream cheese, garlic and parmesan","how":"Remove the stems from 20 button mushrooms. Mix 150g cream cheese with 2 crushed garlic cloves, 40g parmesan and 30g breadcrumbs. Fill the caps, scatter more crumbs on top and bake at 200C for 15 minutes until golden.","shop":["20 button mushrooms@Produce","150g cream cheese@Dairy","2 garlic cloves@Produce","40g parmesan@Deli","30g breadcrumbs@Pantry"]},{"n":"Precinct doughnuts","note":"Warm glazed doughnuts and a pot of plain drip coffee","how":"Warm 8 glazed doughnuts on a tray at 160C for 2 minutes until the glaze turns glossy again. Serve on a plain plate with paper napkins and a pot of drip coffee made from 60g grounds and 1L water.","shop":["8 glazed doughnuts@Bakery","60g ground coffee@Pantry"]}],"m":[{"n":"Mom's pot roast","note":"Braised beef chuck with carrots and potatoes","how":"Brown a 1.5kg chuck roast all over. Add 2 sliced onions, 4 carrots and 500ml stock, cover and braise at 160C for 3 hours. Add 800g halved potatoes for the last hour. Thicken the juices into gravy and serve.","shop":["1.5kg beef chuck roast@Meat","2 brown onions@Produce","4 carrots@Produce","500ml beef stock@Pantry","800g potatoes@Produce"]}],"w":[{"n":"Apple pie","note":"Double crust apple pie with cinnamon","how":"Toss 1kg sliced Granny Smiths with 120g sugar, 1 tsp cinnamon and 2 tbsp flour. Line a pie dish with 2 sheets sweet shortcrust, fill and cover with 2 more. Egg wash and bake at 190C for 50 minutes. Rest an hour before slicing.","shop":["1kg Granny Smith apples@Produce","120g caster sugar@Pantry","1 jar cinnamon@Pantry","1 bag plain flour@Pantry","4 sheets sweet shortcrust pastry@Frozen","1 egg@Dairy"]}],"d":[{"n":"Just the facts coffee","note":"Plain black drip coffee, refilled without comment","how":"Brew 60g ground coffee with 1L water in a drip machine. Pour black into plain mugs. When a cup gets low, refill it without saying anything. Just the coffee, nothing else.","shop":["60g ground coffee@Pantry"]}],"shopping":["20 button mushrooms@Produce","150g cream cheese@Dairy","2 garlic cloves@Produce","40g parmesan@Deli","30g breadcrumbs@Pantry","8 glazed doughnuts@Bakery","120g ground coffee@Pantry","1.5kg beef chuck roast@Meat","2 brown onions@Produce","4 carrots@Produce","500ml beef stock@Pantry","800g potatoes@Produce","1kg Granny Smith apples@Produce","120g caster sugar@Pantry","1 jar cinnamon@Pantry","1 bag plain flour@Pantry","4 sheets sweet shortcrust pastry@Frozen","1 egg@Dairy"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Back to the Future Part III (1990)":{"poster":"assets/menu-posters/back-to-the-future-part-iii-1990.jpg","colour":"#965127","servings":4,"tagline":"Great Scott, it's 1885.","cue":"Pour the drinks when Marty walks into the Palace Saloon and asks for water.","menu":{"s":[{"n":"Festival corn on the cob","note":"Charred corn rolled in butter, salt and smoked paprika","how":"Boil 4 corn cobs in salted water for 5 minutes, then char on a hot grill for about 6 minutes, turning. Roll each in melted butter, about 60g in total, and sprinkle with flaky salt and smoked paprika.","shop":["4 corn cobs@Produce","60g butter@Dairy","1 jar smoked paprika@Pantry","1 box sea salt flakes@Pantry"]},{"n":"Clara's apple slices","note":"Crisp apple slices with honey cinnamon yoghurt to dip","how":"Slice 3 crisp apples and toss in the juice of a lemon so they don't brown. Whip 250g Greek yoghurt with 2 tbsp honey and half a tsp cinnamon. Fan the apples around a bowl of the yoghurt for dipping.","shop":["3 apples@Produce","1 lemon@Produce","1 jar honey@Pantry","250g Greek yoghurt@Dairy","1 jar cinnamon@Pantry"]}],"m":[{"n":"Doc's blacksmith shop stew","note":"Beef braised in dark ale with onion and carrot","how":"Brown 1kg diced beef chuck in batches. Soften 2 onions and 3 carrots in the same pot. Add 375ml dark ale and 500ml stock, cover and braise at 150C for 3 hours until the beef falls apart. Serve with crusty bread.","shop":["1kg beef chuck@Meat","2 brown onions@Produce","3 carrots@Produce","375ml dark ale@Bottle shop","500ml beef stock@Pantry","1 crusty loaf@Bakery"]}],"w":[{"n":"Clara's festival apple pie","note":"Double crust apple pie with cinnamon and nutmeg","how":"Toss 1kg sliced Granny Smiths with 120g sugar, 1 tsp cinnamon, a grating of nutmeg and 2 tbsp flour. Line a pie dish with 2 sheets sweet shortcrust, fill and cover with 2 more. Egg wash, sprinkle with sugar and bake at 190C for 50 minutes.","shop":["1kg Granny Smith apples@Produce","120g caster sugar@Pantry","1 jar cinnamon@Pantry","1 jar nutmeg@Pantry","1 bag plain flour@Pantry","4 sheets sweet shortcrust pastry@Frozen","1 egg@Dairy"]}],"d":[{"n":"Wake-up juice","note":"Fiery lemon, ginger and chilli topped with ginger beer","how":"Blitz the juice of 3 lemons with a 5cm knob of grated ginger, 2 tbsp honey and a pinch of chopped red chilli, then strain. Divide between four glasses of ice and top each with about 150ml very cold ginger beer.","shop":["3 lemons@Produce","1 knob ginger@Produce","1 jar honey@Pantry","1 red chilli@Produce","600ml ginger beer@Drinks"]}],"shopping":["4 corn cobs@Produce","60g butter@Dairy","1 jar smoked paprika@Pantry","1 box sea salt flakes@Pantry","3 apples@Produce","1 lemon@Produce","1 jar honey@Pantry","250g Greek yoghurt@Dairy","1 jar cinnamon@Pantry","1kg beef chuck@Meat","2 brown onions@Produce","3 carrots@Produce","375ml dark ale@Bottle shop","500ml beef stock@Pantry","1 crusty loaf@Bakery","1kg Granny Smith apples@Produce","120g caster sugar@Pantry","1 jar nutmeg@Pantry","1 bag plain flour@Pantry","4 sheets sweet shortcrust pastry@Frozen","1 egg@Dairy","3 lemons@Produce","1 knob ginger@Produce","1 red chilli@Produce","600ml ginger beer@Drinks"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"E.T. the Extra-Terrestrial (1982)":{"poster":"assets/menu-posters/et-the-extra-terrestrial-1982.jpg","colour":"#253b78","servings":4,"tagline":"Phone home. Order in.","cue":"Lay out a trail of peanut butter chocolates when Elliott lures E.T. into the house.","menu":{"s":[{"n":"Peanut butter candy trail","note":"Homemade peanut butter buttons dipped in bright candy coating","how":"Beat 200g peanut butter with 100g icing sugar and 30g soft butter. Roll into small discs and chill 30 minutes. Dip in 250g melted coloured candy melts and set on baking paper. Lay them in a trail across the table.","shop":["200g peanut butter@Pantry","100g icing sugar@Pantry","30g butter@Dairy","250g candy melts@Pantry"]},{"n":"Alphabet crackers","note":"Cheddar crackers cut into little letters","how":"Pulse 150g grated cheddar, 60g cold butter and 100g flour with salt until it forms a dough, adding a splash of water. Roll thin and cut into letters with small cutters. Bake at 180C for 12 minutes until crisp.","shop":["150g cheddar@Dairy","60g butter@Dairy","100g plain flour@Pantry"]}],"m":[{"n":"Family pizza night","note":"Pepperoni pizza cut into squares for the whole family","how":"Stretch 500g pizza dough into 2 thin bases. Spread with pizza sauce and top with 250g mozzarella and 100g pepperoni. Bake on a steel or tray at the oven's highest heat for 7 to 8 minutes, then cut into squares.","shop":["500g pizza dough@Bakery","1 jar pizza sauce@Pantry","250g mozzarella@Dairy","100g pepperoni@Deli"]}],"w":[{"n":"Homemade peanut butter cups","note":"Milk chocolate cups with a soft peanut butter middle","how":"Melt 300g milk chocolate. Spoon a little into 12 cupcake liners and chill. Mix 150g peanut butter with 50g icing sugar and put a spoon on each. Cover with the rest of the chocolate and chill until set.","shop":["300g milk chocolate@Pantry","150g peanut butter@Pantry","50g icing sugar@Pantry"]}],"d":[{"n":"Root beer","note":"Root beer over ice, or as a float","how":"Pour four 375ml cans of root beer over ice into tall glasses. For a float, skip the ice and add a scoop of vanilla ice cream, then pour slowly so it foams up. Long spoons and straws.","shop":["4 375ml cans root beer@Drinks","500ml vanilla ice cream@Frozen"]}],"shopping":["350g peanut butter@Pantry","150g icing sugar@Pantry","90g butter@Dairy","250g candy melts@Pantry","150g cheddar@Dairy","100g plain flour@Pantry","500g pizza dough@Bakery","1 jar pizza sauce@Pantry","250g mozzarella@Dairy","100g pepperoni@Deli","300g milk chocolate@Pantry","4 375ml cans root beer@Drinks","500ml vanilla ice cream@Frozen"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Predator (1987)":{"poster":"assets/menu-posters/predator-1987.jpg","colour":"#31503c","servings":4,"tagline":"Get to the chopper. Then get to dinner.","cue":"Serve the snacks when Dutch and Dillon do that famous handshake.","menu":{"s":[{"n":"Mud-camo bean dip","note":"Black bean dip with feta, coriander and green chilli","how":"Blitz 2 drained tins black beans with 2 garlic cloves, 1 tsp cumin and the juice of 2 limes until smooth. Spread in a bowl and top with 80g crumbled feta, coriander and a sliced green chilli. Serve with corn chips.","shop":["2 tins black beans@Pantry","2 garlic cloves@Produce","1 jar ground cumin@Pantry","2 limes@Produce","80g feta@Deli","1 bunch coriander@Produce","1 green chilli@Produce","1 bag corn chips@Pantry"]},{"n":"Billy's plantain chips","note":"Thin crisp green plantain chips with lime salt","how":"Peel 3 green plantains and slice very thin on a mandoline. Fry at 175C in batches until crisp, about 2 minutes. Drain and toss straight away with flaky salt mixed with the zest of a lime.","shop":["3 green plantains@Produce","1L vegetable oil@Pantry","1 lime@Produce","1 box sea salt flakes@Pantry"]}],"m":[{"n":"Chopper pad steak","note":"Smoky paprika rump grilled hot, with sharp green chimichurri","how":"Rub 4 rump steaks with salt, pepper and 2 tsp smoked paprika. Grill over high heat for 4 minutes a side and rest. Chop a bunch of parsley with 2 garlic cloves and mix with 3 tbsp red wine vinegar, 100ml oil and chilli flakes. Spoon over.","shop":["4 rump steaks@Meat","1 jar smoked paprika@Pantry","1 bunch parsley@Produce","2 garlic cloves@Produce","1 bottle red wine vinegar@Pantry","1 bottle extra virgin olive oil@Pantry","1 jar chilli flakes@Pantry"]}],"w":[{"n":"Mud cake","note":"Dense chocolate mud cake with ganache dragged like mud","how":"Melt 250g dark chocolate and 250g butter. Whisk in 4 eggs and 300g sugar, then fold in 150g flour and 30g cocoa. Bake at 160C for 70 minutes. Melt 150g chocolate with 150ml cream, pour over and drag with a fork.","shop":["400g dark chocolate@Pantry","250g butter@Dairy","4 eggs@Dairy","300g caster sugar@Pantry","150g plain flour@Pantry","30g cocoa@Pantry","150ml thickened cream@Dairy"]}],"d":[{"n":"Base camp beer","note":"Ice-cold Mexican lager with a lime in the neck","how":"Bury eight 355ml bottles of Mexican lager in a cooler of ice for an hour. Push a lime wedge into the neck of each bottle and hand them out. Drink before anything in the trees moves.","shop":["8 355ml bottles Mexican lager@Bottle shop","2 limes@Produce"]}],"shopping":["2 tins black beans@Pantry","4 garlic cloves@Produce","1 jar ground cumin@Pantry","4 limes@Produce","80g feta@Deli","1 bunch coriander@Produce","1 green chilli@Produce","1 bag corn chips@Pantry","3 green plantains@Produce","1L vegetable oil@Pantry","1 lime@Produce","1 box sea salt flakes@Pantry","4 rump steaks@Meat","1 jar smoked paprika@Pantry","1 bunch parsley@Produce","1 bottle red wine vinegar@Pantry","1 bottle extra virgin olive oil@Pantry","1 jar chilli flakes@Pantry","400g dark chocolate@Pantry","250g butter@Dairy","4 eggs@Dairy","300g caster sugar@Pantry","150g plain flour@Pantry","30g cocoa@Pantry","150ml thickened cream@Dairy","8 355ml bottles Mexican lager@Bottle shop"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Blade Runner (1982)":{"poster":"assets/menu-posters/blade-runner-1982.jpg","colour":"#364e68","servings":4,"tagline":"Noodles in the rain.","cue":"Serve the noodles when Deckard sits down at the street noodle bar in the rain.","menu":{"s":[{"n":"Noodle bar gyoza","note":"Crisp-bottomed pork and cabbage gyoza with chilli dipping sauce","how":"Mix 400g pork mince with 2 cups finely shredded cabbage, salted and squeezed, plus soy and ginger. Fill 30 gyoza wrappers and pleat. Fry until crisp underneath, add water and steam with a lid for 4 minutes. Dip in soy, rice vinegar and chilli oil.","shop":["400g pork mince@Meat","0.25 cabbage@Produce","1 bottle soy sauce@Pantry","1 knob ginger@Produce","30 gyoza wrappers@Frozen","1 bottle rice vinegar@Pantry","1 jar chilli oil@Pantry"]},{"n":"Origami crackers","note":"Puffed rice paper triangles with shichimi and salt","how":"Cut 10 rice paper sheets into small triangles with scissors. Fry a few at a time at 180C for a few seconds until they puff and turn white. Drain and toss with flaky salt and a good shake of shichimi togarashi.","shop":["10 rice paper sheets@Pantry","1L vegetable oil@Pantry","1 box sea salt flakes@Pantry","1 jar shichimi togarashi@Pantry"]}],"m":[{"n":"Rain-soaked ramen","note":"Soy-braised pork belly ramen with jammy eggs and nori","how":"Braise 600g pork belly in 125ml soy, 125ml mirin, 125ml sake and 500ml water for 2 hours, then slice. Marinate 4 soft-boiled eggs in some of the liquid. Cook 4 serves ramen into 1.5L hot stock seasoned with soy. Top with pork, egg, nori and spring onion.","shop":["600g pork belly@Meat","1 bottle soy sauce@Pantry","125ml mirin@Pantry","125ml sake@Bottle shop","4 eggs@Dairy","400g ramen noodles@Pantry","1.5L chicken stock@Pantry","1 packet nori@Pantry","1 bunch spring onions@Produce"]}],"w":[{"n":"Origami cookies","note":"Thin sesame tuiles folded into shapes while hot","how":"Whisk 2 egg whites with 100g sugar, then stir in 50g flour, 50g melted butter and 2 tbsp sesame seeds. Spread thin circles on a lined tray and bake at 180C for 6 minutes. Fold or twist into shapes while still hot and soft.","shop":["2 eggs@Dairy","100g caster sugar@Pantry","50g plain flour@Pantry","50g butter@Dairy","1 jar sesame seeds@Pantry"]}],"d":[{"n":"Deckard's whisky","note":"Japanese whisky neat in a heavy glass, a drop of water","how":"Pour 45ml Japanese whisky into each of four heavy tumblers. Add a single drop of water from a teaspoon to open it up. Sip slowly while the rain comes down outside.","shop":["180ml Japanese whisky@Bottle shop"]}],"shopping":["400g pork mince@Meat","0.25 cabbage@Produce","1 bottle soy sauce@Pantry","1 knob ginger@Produce","30 gyoza wrappers@Frozen","1 bottle rice vinegar@Pantry","1 jar chilli oil@Pantry","10 rice paper sheets@Pantry","1L vegetable oil@Pantry","1 box sea salt flakes@Pantry","1 jar shichimi togarashi@Pantry","600g pork belly@Meat","125ml mirin@Pantry","125ml sake@Bottle shop","6 eggs@Dairy","400g ramen noodles@Pantry","1.5L chicken stock@Pantry","1 packet nori@Pantry","1 bunch spring onions@Produce","100g caster sugar@Pantry","50g plain flour@Pantry","50g butter@Dairy","1 jar sesame seeds@Pantry","180ml Japanese whisky@Bottle shop"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Spaceballs (1987)":{"poster":"assets/menu-posters/spaceballs-1987.jpg","colour":"#5b3f76","servings":4,"tagline":"May the schwartz be with your snacks.","cue":"Serve the pizza when Pizza the Hutt appears.","menu":{"s":[{"n":"Ludicrous speed pretzels","note":"Chocolate pretzel rods striped plaid with candy melts","how":"Melt 200g dark chocolate and dip 20 pretzel rods two-thirds of the way. Set on baking paper. Melt 100g coloured candy melts, pipe stripes across in two directions for a plaid pattern and let them set.","shop":["200g dark chocolate@Pantry","20 pretzel rods@Pantry","100g candy melts@Pantry"]},{"n":"Merchandising snack mix","note":"Honey butter mix of cereal, pretzels, peanuts and marshmallows","how":"Toss 150g cereal squares, 100g pretzels and 100g peanuts with 50g butter melted with 2 tbsp honey. Bake at 140C for 20 minutes, stirring once. Cool completely, then toss through 100g mini marshmallows.","shop":["150g cereal squares@Pantry","100g pretzels@Pantry","100g peanuts@Pantry","50g butter@Dairy","1 jar honey@Pantry","100g mini marshmallows@Pantry"]}],"m":[{"n":"Pizza the Hutt","note":"Molten deep pan four-cheese pepperoni pizza","how":"Press 600g pizza dough into an oiled deep tray and prove 30 minutes. Spread with a jar of pizza sauce and pile on 200g mozzarella, 100g provolone, 50g parmesan, 100g cheddar and 100g pepperoni. Bake at 220C for 20 minutes until molten.","shop":["600g pizza dough@Bakery","1 jar pizza sauce@Pantry","200g mozzarella@Dairy","100g provolone@Deli","50g parmesan@Deli","100g cheddar@Dairy","100g pepperoni@Deli"]}],"w":[{"n":"Yogurt parfait","note":"Honey vanilla yoghurt layered with granola and berries","how":"Whip 500g Greek yoghurt with 3 tbsp honey and a little vanilla. Layer in four tall glasses with 200g granola and 250g mixed berries, finishing with berries on top. Serve straight away so the granola stays crunchy.","shop":["500g Greek yoghurt@Dairy","1 jar honey@Pantry","1 bottle vanilla extract@Pantry","200g granola@Pantry","250g berries@Produce"]}],"d":[{"n":"Perri-Air","note":"Sparkling water poured from the can like it's precious","how":"Chill four 375ml cans of sparkling water. Fill four glasses with ice and a twist of lime. Open each can slowly, take a deep breath of it, then pour with great ceremony.","shop":["4 375ml cans sparkling water@Drinks","2 limes@Produce"]}],"shopping":["200g dark chocolate@Pantry","20 pretzel rods@Pantry","100g candy melts@Pantry","150g cereal squares@Pantry","100g pretzels@Pantry","100g peanuts@Pantry","50g butter@Dairy","1 jar honey@Pantry","100g mini marshmallows@Pantry","600g pizza dough@Bakery","1 jar pizza sauce@Pantry","200g mozzarella@Dairy","100g provolone@Deli","50g parmesan@Deli","100g cheddar@Dairy","100g pepperoni@Deli","500g Greek yoghurt@Dairy","1 bottle vanilla extract@Pantry","200g granola@Pantry","250g berries@Produce","4 375ml cans sparkling water@Drinks","2 limes@Produce"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Hitch (2005)":{"poster":"assets/menu-posters/hitch-2005.jpg","colour":"#8e394e","servings":4,"tagline":"Every dinner date needs a coach.","cue":"Serve the snacks when Hitch has his allergic reaction.","menu":{"s":[{"n":"Ellis Island crostini","note":"Garlic-rubbed ciabatta with tomato, basil and red onion","how":"Slice a ciabatta, grill until charred and rub with a cut garlic clove. Dice 4 ripe tomatoes and mix with torn basil, a little finely chopped red onion, 2 tbsp olive oil and salt. Spoon on just before serving.","shop":["1 ciabatta@Bakery","1 garlic clove@Produce","4 tomatoes@Produce","1 bunch basil@Produce","1 red onion@Produce","1 bottle extra virgin olive oil@Pantry"]},{"n":"Albert's meatball sliders","note":"Meatballs in tomato sugo with melted provolone on soft rolls","how":"Roll 500g pork and veal mince with breadcrumbs, egg and parmesan into 12 balls. Brown, then simmer in 700ml passata for 25 minutes. Put each in a slider bun with a slice of provolone and basil and grill until the cheese melts.","shop":["500g pork and veal mince@Meat","50g breadcrumbs@Pantry","1 egg@Dairy","30g parmesan@Deli","700ml passata@Pantry","12 slider buns@Bakery","150g provolone@Deli","1 bunch basil@Produce"]}],"m":[{"n":"Chicken piccata","note":"Thin chicken in lemon, caper and butter sauce over angel hair","how":"Pound 2 large chicken breasts thin, cut in half, flour and sear in oil. Add 125ml white wine, the juice of 2 lemons and 2 tbsp capers and reduce. Whisk in 60g butter. Toss with 400g cooked angel hair and serve the chicken on top.","shop":["2 chicken breasts@Meat","1 bag plain flour@Pantry","125ml white wine@Bottle shop","2 lemons@Produce","1 jar capers@Pantry","60g butter@Dairy","400g angel hair pasta@Pantry"]}],"w":[{"n":"Chocolate lava cake","note":"Molten-centred chocolate puddings turned out warm","how":"Melt 125g dark chocolate with 125g butter. Whisk 2 eggs and 2 yolks with 60g sugar until pale, combine and fold in 30g flour. Pour into 4 buttered moulds and bake at 200C for 10 minutes. Turn out and serve straight away.","shop":["125g dark chocolate@Pantry","140g butter@Dairy","4 eggs@Dairy","60g caster sugar@Pantry","30g plain flour@Pantry"]}],"d":[{"n":"Champagne","note":"Brut champagne in flutes, nothing else needed","how":"Chill a 750ml bottle of brut champagne to about 7C, three hours in the fridge or 30 minutes in an ice bucket. Open gently and pour into four flutes, slowly, so the foam settles before you top them up.","shop":["750ml champagne@Bottle shop"]}],"shopping":["1 ciabatta@Bakery","1 garlic clove@Produce","4 tomatoes@Produce","1 bunch basil@Produce","1 red onion@Produce","1 bottle extra virgin olive oil@Pantry","500g pork and veal mince@Meat","50g breadcrumbs@Pantry","1 egg@Dairy","30g parmesan@Deli","700ml passata@Pantry","12 slider buns@Bakery","150g provolone@Deli","2 chicken breasts@Meat","125ml white wine@Bottle shop","2 lemons@Produce","1 jar capers@Pantry","200g butter@Dairy","400g angel hair pasta@Pantry","125g dark chocolate@Pantry","4 eggs@Dairy","60g caster sugar@Pantry","30g plain flour@Pantry","750ml champagne@Bottle shop"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Oliver & Company (1988)":{"poster":"assets/menu-posters/oliver-and-company-1988.jpg","colour":"#3b6687","servings":4,"tagline":"Why should I worry? Dinner's ready.","cue":"Serve the hot dogs when Oliver and Dodger raid the hot dog cart.","menu":{"s":[{"n":"Hot dog cart sausages","note":"Sticky honey mustard cocktail franks on toothpicks","how":"Simmer 24 cocktail franks for 5 minutes and drain. Toss in a hot pan with 2 tbsp Dijon and 2 tbsp honey for 3 minutes until sticky and glazed. Spear each on a toothpick and serve while hot.","shop":["24 cocktail franks@Deli","1 jar Dijon mustard@Pantry","1 jar honey@Pantry"]},{"n":"Fish crackers","note":"Little fish-shaped cheddar crackers, crisp and salty, for snacking","how":"Pulse 150g grated cheddar, 60g cold butter and 100g flour with a pinch of salt until it forms a dough, adding a splash of water. Roll thin, cut into little fish shapes and bake at 180C for 12 minutes until crisp.","shop":["150g cheddar@Dairy","60g butter@Dairy","100g plain flour@Pantry"]}],"m":[{"n":"Louie's hot dogs with everything","note":"Griddled franks with mustard, onion, relish and sauerkraut","how":"Simmer 8 franks for 5 minutes, then griddle until blistered. Warm 250g sauerkraut in a small pan. Steam 8 buns and fill with franks, mustard, chopped onion, sweet relish and the sauerkraut.","shop":["8 hot dog franks@Meat","8 hot dog buns@Bakery","1 bottle yellow mustard@Pantry","1 onion@Produce","1 jar sweet relish@Pantry","1 jar sauerkraut@Pantry"]}],"w":[{"n":"Kitten cookies","note":"Cat-shaped shortbread iced orange with whiskers","how":"Beat 250g butter with 100g icing sugar and mix in 350g flour. Roll to 6mm, cut into cat shapes and bake at 160C for 18 minutes. Ice with 200g icing sugar tinted orange and pipe on little whiskers in white.","shop":["250g butter@Dairy","300g icing sugar@Pantry","350g plain flour@Pantry","1 bottle orange food colouring@Pantry"]}],"d":[{"n":"Milk","note":"Cold milk, or warm with honey and cinnamon","how":"Pour 1L full cream milk into four glasses ice cold, or warm it gently in a pot with 2 tbsp honey and a pinch of cinnamon until steaming. Don't boil it. Serve in mugs with a dusting of cinnamon on top.","shop":["1L full cream milk@Dairy","1 jar honey@Pantry","1 jar cinnamon@Pantry"]}],"shopping":["24 cocktail franks@Deli","1 jar Dijon mustard@Pantry","1 jar honey@Pantry","150g cheddar@Dairy","310g butter@Dairy","450g plain flour@Pantry","8 hot dog franks@Meat","8 hot dog buns@Bakery","1 bottle yellow mustard@Pantry","1 onion@Produce","1 jar sweet relish@Pantry","1 jar sauerkraut@Pantry","300g icing sugar@Pantry","1 bottle orange food colouring@Pantry","1L full cream milk@Dairy","1 jar cinnamon@Pantry"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Coming to America (1988)":{"poster":"assets/menu-posters/coming-to-america-1988.jpg","colour":"#90253d","servings":4,"tagline":"A prince walks into a burger joint in Queens.","cue":"Serve the burgers when the Big Mick comes out at McDowell's.","menu":{"s":[{"n":"Golden fries","note":"Thin golden fries, salted straight out of the oil","how":"Cut 1kg russets into thin fries and soak in cold water for 30 minutes, then dry well. Fry at 140C for 5 minutes, rest, then fry at 190C until golden and crisp. Salt straight away and serve hot.","shop":["1kg russet potatoes@Produce","2L vegetable oil@Pantry","1 box fine salt@Pantry"]},{"n":"Rose petal sugar crisps","note":"Thin rosewater sugar cookies with crushed rose petals","how":"Beat 125g butter with 100g sugar and 1 tsp rose water, then mix in 200g flour. Roll thin, cut into rounds and press crushed dried rose petals on top. Bake at 170C for 9 minutes until just crisp at the edges.","shop":["125g butter@Dairy","100g caster sugar@Pantry","1 bottle rose water@Pantry","200g plain flour@Pantry","1 packet dried rose petals@Pantry"]}],"m":[{"n":"Big Mick burger","note":"Double smashed patties with special sauce on a three-piece bun","how":"Mix 100g mayo, 2 tbsp relish, 1 tsp mustard, paprika and a dash of vinegar. Smash 8 thin patties from 800g mince, add cheese. Build each in a three-piece sesame bun with sauce, shredded iceberg, diced onion and pickles.","shop":["1 jar mayonnaise@Pantry","1 jar sweet relish@Pantry","1 bottle yellow mustard@Pantry","800g beef mince@Meat","8 slices American cheese@Dairy","6 sesame burger buns@Bakery","0.5 iceberg lettuce@Produce","1 brown onion@Produce","1 jar dill pickles@Pantry"]}],"w":[{"n":"Apple turnovers","note":"Flaky puff turnovers with buttery cinnamon apple","how":"Cook 3 diced apples with 30g butter, 3 tbsp sugar and 1 tsp cinnamon for 8 minutes, then cool. Cut 2 sheets puff pastry into quarters, fill, fold into triangles and crimp. Egg wash and bake at 200C for 20 minutes.","shop":["3 apples@Produce","30g butter@Dairy","50g caster sugar@Pantry","1 jar cinnamon@Pantry","2 sheets puff pastry@Frozen","1 egg@Dairy"]}],"d":[{"n":"Vanilla thick shake","note":"Thick vanilla shakes blended with plenty of ice cream","how":"For each shake, blend 3 scoops vanilla ice cream with 150ml cold milk until thick and smooth. Pour into a chilled tall glass and serve with a wide straw. Make four, one after the other, so they stay thick.","shop":["1.5L vanilla ice cream@Frozen","600ml full cream milk@Dairy"]}],"shopping":["1kg russet potatoes@Produce","2L vegetable oil@Pantry","1 box fine salt@Pantry","155g butter@Dairy","150g caster sugar@Pantry","1 bottle rose water@Pantry","200g plain flour@Pantry","1 packet dried rose petals@Pantry","1 jar mayonnaise@Pantry","1 jar sweet relish@Pantry","1 bottle yellow mustard@Pantry","800g beef mince@Meat","8 slices American cheese@Dairy","6 sesame burger buns@Bakery","0.5 iceberg lettuce@Produce","1 brown onion@Produce","1 jar dill pickles@Pantry","3 apples@Produce","1 jar cinnamon@Pantry","2 sheets puff pastry@Frozen","1 egg@Dairy","1.5L vanilla ice cream@Frozen","600ml full cream milk@Dairy"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Wall Street (1987)":{"poster":"assets/menu-posters/wall-street-1987.jpg","colour":"#806637","servings":4,"tagline":"Lunch is for wimps. Dinner is not.","cue":"Serve dinner when Gekko gives the \"greed is good\" speech.","menu":{"s":[{"n":"Steak tartare","note":"Hand-chopped eye fillet with capers and shallot on toasted brioche","how":"Finely chop 300g well-chilled eye fillet by hand. Mix with 1 diced shallot, 1 tbsp capers, 4 chopped cornichons, 1 tsp Dijon, a dash of Worcestershire and 1 yolk. Season well and serve with toasted brioche slices.","shop":["300g eye fillet@Meat","1 shallot@Produce","1 jar capers@Pantry","1 jar cornichons@Pantry","1 jar Dijon mustard@Pantry","1 bottle Worcestershire sauce@Pantry","1 egg@Dairy","1 brioche loaf@Bakery"]},{"n":"Prawn cocktail","note":"Iced prawns on crisp iceberg with Marie Rose and lemon","how":"Poach 500g green prawns in salted water for 2 minutes, plunge into iced water and peel. Mix 4 tbsp mayo, 2 tbsp tomato sauce and a squeeze of lemon. Serve on shredded iceberg in glasses with a dusting of paprika and lemon wedges.","shop":["500g green prawns@Seafood","0.5 iceberg lettuce@Produce","1 jar mayonnaise@Pantry","1 bottle tomato sauce@Pantry","2 lemons@Produce","1 jar sweet paprika@Pantry"]}],"m":[{"n":"Raider's rib eye","note":"Butter-basted rib eye with a brandy peppercorn sauce","how":"Dry-brine 4 rib eyes overnight. Sear hard, then baste with 60g butter and rosemary and rest 8 minutes. In the pan, crush 1 tbsp peppercorns, flame 60ml brandy, add 125ml stock and 200ml cream and reduce until it coats a spoon.","shop":["4 rib eye steaks@Meat","60g butter@Dairy","1 bunch rosemary@Produce","1 jar black peppercorns@Pantry","60ml brandy@Bottle shop","125ml beef stock@Pantry","200ml thickened cream@Dairy"]}],"w":[{"n":"Cheesecake","note":"Baked New York cheesecake with a sour cream top","how":"Mix 250g crushed biscuits with 100g melted butter and press into a tin. Beat 750g cream cheese with 200g sugar, 3 eggs and lemon zest. Bake in a water bath at 150C for 60 minutes. Spread 300g sour cream on top and bake 10 minutes more. Chill overnight.","shop":["250g digestive biscuits@Pantry","100g butter@Dairy","750g cream cheese@Dairy","200g caster sugar@Pantry","3 eggs@Dairy","1 lemon@Produce","300g sour cream@Dairy"]}],"d":[{"n":"Old fashioned","note":"Bourbon, sugar and bitters over a big cube, orange twist","how":"For each drink, stir 60ml bourbon, 10ml sugar syrup and 2 dashes aromatic bitters over ice for 30 seconds. Strain over one big ice cube in a short glass and twist a strip of orange peel over the top. Makes four.","shop":["240ml bourbon@Bottle shop","1 bottle aromatic bitters@Bottle shop","1 orange@Produce","1 bag caster sugar@Pantry"]}],"shopping":["300g eye fillet@Meat","1 shallot@Produce","1 jar capers@Pantry","1 jar cornichons@Pantry","1 jar Dijon mustard@Pantry","1 bottle Worcestershire sauce@Pantry","1 egg@Dairy","1 brioche loaf@Bakery","500g green prawns@Seafood","0.5 iceberg lettuce@Produce","1 jar mayonnaise@Pantry","1 bottle tomato sauce@Pantry","2 lemons@Produce","1 jar sweet paprika@Pantry","4 rib eye steaks@Meat","160g butter@Dairy","1 bunch rosemary@Produce","1 jar black peppercorns@Pantry","60ml brandy@Bottle shop","125ml beef stock@Pantry","200ml thickened cream@Dairy","250g digestive biscuits@Pantry","750g cream cheese@Dairy","200g caster sugar@Pantry","3 eggs@Dairy","1 lemon@Produce","300g sour cream@Dairy","240ml bourbon@Bottle shop","1 bottle aromatic bitters@Bottle shop","1 orange@Produce"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Ghost (1990)":{"poster":"assets/menu-posters/ghost-1990.jpg","colour":"#635076","servings":4,"tagline":"Ditto.","cue":"Serve dessert when the pottery wheel scene starts.","menu":{"s":[{"n":"Subway pretzels","note":"Warm soft pretzels with butter, coarse salt and yellow mustard","how":"Brush 4 soft pretzels with 30g melted butter and sprinkle with coarse salt. Warm on a tray at 200C for 5 minutes until glossy. Cut in halves for sharing and serve with a squeeze bottle of yellow mustard.","shop":["4 soft pretzels@Bakery","30g butter@Dairy","1 box rock salt@Pantry","1 bottle yellow mustard@Pantry"]},{"n":"Tribeca loft crostini","note":"Garlic-rubbed toasts with ripe tomato and basil","how":"Grill 16 baguette slices until charred at the edges and rub each with a cut garlic clove. Dice 4 ripe tomatoes and dress with torn basil, salt and 2 tbsp good olive oil. Spoon on just before serving so the toasts stay crisp.","shop":["1 baguette@Bakery","1 garlic clove@Produce","4 tomatoes@Produce","1 bunch basil@Produce","1 bottle extra virgin olive oil@Pantry"]}],"m":[{"n":"Sam's Tribeca loft pasta","note":"Rigatoni with sausage, fennel, white wine and cream","how":"Brown 4 Italian sausages, skins off and crumbled. Add 1 sliced fennel bulb and 2 garlic cloves and cook 8 minutes. Deglaze with 125ml white wine, add 150ml cream, and toss with 500g cooked rigatoni and 60g grated parmesan.","shop":["4 Italian sausages@Meat","1 fennel bulb@Produce","2 garlic cloves@Produce","125ml white wine@Bottle shop","150ml thickened cream@Dairy","500g rigatoni@Pantry","60g parmesan@Deli"]}],"w":[{"n":"Pottery wheel pie","note":"Rustic hand-folded apple galette with cinnamon sugar","how":"Roll a sheet of shortcrust pastry into a rough circle. Toss 4 sliced apples with 60g sugar and 1 tsp cinnamon and pile in the middle. Fold the edges up by hand, pleating as you go, and bake at 200C for 40 minutes until golden.","shop":["1 sheet shortcrust pastry@Frozen","4 apples@Produce","60g caster sugar@Pantry","1 jar cinnamon@Pantry"]}],"d":[{"n":"Red wine","note":"Pinot noir, slightly cool, in big glasses","how":"Put a 750ml bottle of pinot noir in the fridge for 20 minutes to bring it to about 14C. Open it 20 minutes before pouring to let it breathe. Serve in big glasses, about 150ml each, with the rest for top-ups.","shop":["750ml pinot noir@Bottle shop"]}],"shopping":["4 soft pretzels@Bakery","30g butter@Dairy","1 box rock salt@Pantry","1 bottle yellow mustard@Pantry","1 baguette@Bakery","1 garlic clove@Produce","4 tomatoes@Produce","1 bunch basil@Produce","1 bottle extra virgin olive oil@Pantry","4 Italian sausages@Meat","1 fennel bulb@Produce","2 garlic cloves@Produce","125ml white wine@Bottle shop","150ml thickened cream@Dairy","500g rigatoni@Pantry","60g parmesan@Deli","1 sheet shortcrust pastry@Frozen","4 apples@Produce","60g caster sugar@Pantry","1 jar cinnamon@Pantry","750ml pinot noir@Bottle shop"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Brewster's Millions (1985)":{"poster":"assets/menu-posters/brewsters-millions-1985.jpg","colour":"#30634d","servings":4,"tagline":"Spend thirty million in thirty days. Start with dinner.","cue":"Order the most expensive thing on the menu when Monty books his hotel suite.","menu":{"s":[{"n":"Prawn cocktail for the whole hotel","note":"Iced prawns on crisp iceberg with Marie Rose and paprika","how":"Poach 500g green prawns in salted water with lemon and a bay leaf for 2 minutes, then plunge into iced water and peel. Mix 4 tbsp mayo with 2 tbsp tomato sauce and a squeeze of lemon. Serve on shredded iceberg in glasses, dusted with paprika.","shop":["500g green prawns@Seafood","1 lemon@Produce","1 jar mayonnaise@Pantry","1 bottle tomato sauce@Pantry","0.5 iceberg lettuce@Produce","1 jar smoked paprika@Pantry"]},{"n":"Caviar blini","note":"Warm blini with crème fraîche, salmon roe and chives","how":"Warm 16 buckwheat blini on a tray at 180C for 5 minutes. Top each with a teaspoon of crème fraîche, about 150ml in total, then half a teaspoon of salmon roe and a few snipped chives. Serve straight away while they are still warm.","shop":["16 buckwheat blini@Bakery","150ml crème fraîche@Dairy","100g salmon roe@Seafood","1 bunch chives@Produce"]}],"m":[{"n":"Surf and turf","note":"Eye fillet and grilled lobster tail with béarnaise","how":"Reduce 60ml white wine vinegar with tarragon to 2 tbsp, whisk with 3 yolks over a low heat and drizzle in 200g warm clarified butter. Sear 4 eye fillet steaks to medium rare and rest. Split 2 lobster tails, brush with garlic butter and grill for 6 minutes.","shop":["60ml white wine vinegar@Pantry","1 bunch tarragon@Produce","3 eggs@Dairy","250g butter@Dairy","4 eye fillet steaks@Meat","2 lobster tails@Seafood","2 garlic cloves@Produce"]}],"w":[{"n":"Rare stamp shortbread","note":"Buttery shortbread cut like stamps, with a piped design","how":"Beat 250g butter with 100g icing sugar, then mix in 250g plain flour and 60g rice flour. Roll to 6mm, cut into rectangles with a pinking cutter and bake at 160C for 20 minutes. Cool and pipe a little stamp design on each with icing.","shop":["250g butter@Dairy","200g icing sugar@Pantry","250g plain flour@Pantry","60g rice flour@Pantry"]}],"d":[{"n":"Champagne for everyone","note":"The good brut bubbles, poured for every guest","how":"Chill a 750ml bottle of brut champagne in an ice bucket with water and ice for 30 minutes. Open with a gentle hiss, not a pop, and pour slowly into four flutes, topping up as the foam settles.","shop":["750ml champagne@Bottle shop"]}],"shopping":["500g green prawns@Seafood","1 lemon@Produce","1 jar mayonnaise@Pantry","1 bottle tomato sauce@Pantry","0.5 iceberg lettuce@Produce","1 jar smoked paprika@Pantry","16 buckwheat blini@Bakery","150ml crème fraîche@Dairy","100g salmon roe@Seafood","1 bunch chives@Produce","60ml white wine vinegar@Pantry","1 bunch tarragon@Produce","3 eggs@Dairy","500g butter@Dairy","4 eye fillet steaks@Meat","2 lobster tails@Seafood","2 garlic cloves@Produce","200g icing sugar@Pantry","250g plain flour@Pantry","60g rice flour@Pantry","750ml champagne@Bottle shop"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Splash (1984)":{"poster":"assets/menu-posters/splash-1984.jpg","colour":"#237d82","servings":4,"tagline":"Fresh from the ocean. Mostly.","cue":"Serve the lobster when Madison eats it whole at the restaurant.","menu":{"s":[{"n":"Oysters natural","note":"Fresh oysters on ice with lemon and shallot mignonette","how":"Finely dice 2 shallots and mix with 80ml red wine vinegar and plenty of cracked pepper. Rest 20 minutes. Lay 24 freshly shucked oysters on crushed ice, with lemon wedges and the mignonette in a small bowl with a spoon.","shop":["24 freshly shucked oysters@Seafood","2 shallots@Produce","80ml red wine vinegar@Pantry","2 lemons@Produce"]},{"n":"Fish and chip cones","note":"Beer-battered flathead and chips in paper cones with tartare","how":"Whisk 150g flour, 50g cornflour and 300ml cold lager to a batter. Cut 600g potatoes into chips and fry twice. Dip 500g flathead strips in batter and fry at 180C for 3 minutes. Serve in paper cones with tartare and lemon.","shop":["150g plain flour@Pantry","50g cornflour@Pantry","375ml lager@Bottle shop","600g potatoes@Produce","500g flathead fillets@Seafood","1 jar tartare sauce@Pantry","1 lemon@Produce","2L vegetable oil@Pantry"]}],"m":[{"n":"Whole lobster","note":"Boiled lobster, split and grilled with garlic butter","how":"Cook 2 raw lobsters, about 800g each, in boiling salted water for 8 minutes per 500g. Split lengthways, crack the claws and brush the flesh with 100g butter melted with 3 garlic cloves. Grill flesh-side up for 2 minutes. Serve with drawn butter and lemon.","shop":["2 whole lobsters@Seafood","200g butter@Dairy","3 garlic cloves@Produce","2 lemons@Produce"]}],"w":[{"n":"Ocean blue jelly cups","note":"Blue jelly over coconut panna cotta with gummy fish on top","how":"Bloom 3 gelatine leaves and stir into 400ml warm coconut milk with 60g sugar. Set in four glasses for 2 hours. Steep 10 butterfly pea flowers in 400ml hot water with 60g sugar, add 3 more gelatine leaves, cool and pour over. Set, then add gummy fish.","shop":["6 gelatine leaves@Pantry","400ml coconut milk@Pantry","120g caster sugar@Pantry","1 packet dried butterfly pea flowers@Pantry","1 bag gummy fish@Pantry"]}],"d":[{"n":"Blue lagoon","note":"Vodka, blue curaçao and lemonade over ice with lemon","how":"For each drink, fill a tall glass with ice and add 30ml vodka and 20ml blue curaçao. Top with about 150ml lemonade and stir gently. Garnish with a lemon wheel. Makes four, so mix them one at a time.","shop":["120ml vodka@Bottle shop","80ml blue curaçao@Bottle shop","600ml lemonade@Drinks","1 lemon@Produce"]}],"shopping":["24 freshly shucked oysters@Seafood","2 shallots@Produce","80ml red wine vinegar@Pantry","4 lemons@Produce","150g plain flour@Pantry","50g cornflour@Pantry","375ml lager@Bottle shop","600g potatoes@Produce","500g flathead fillets@Seafood","1 jar tartare sauce@Pantry","2 lemon@Produce","2L vegetable oil@Pantry","2 whole lobsters@Seafood","200g butter@Dairy","3 garlic cloves@Produce","6 gelatine leaves@Pantry","400ml coconut milk@Pantry","120g caster sugar@Pantry","1 packet dried butterfly pea flowers@Pantry","1 bag gummy fish@Pantry","120ml vodka@Bottle shop","80ml blue curaçao@Bottle shop","600ml lemonade@Drinks"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Big (1988)":{"poster":"assets/menu-posters/big-1988.jpg","colour":"#9c292c","servings":4,"tagline":"Grown-up food for a kid at heart.","cue":"Serve the snacks when Josh eats baby corn like a tiny corn cob at the company party.","menu":{"s":[{"n":"Baby corn","note":"Charred baby corn with butter, chilli and lime salt","how":"Blanch 400g baby corn in salted boiling water for 2 minutes and drain well. Char on a hot griddle for 3 minutes with 30g butter, then sprinkle with chilli flakes, lime zest and salt. Serve with lime wedges and eat it like a cob.","shop":["400g baby corn@Produce","30g butter@Dairy","2 limes@Produce","1 jar chilli flakes@Pantry"]},{"n":"Caviar on crackers","note":"Crème fraîche, salmon roe and chives on water crackers","how":"Spread 20 water crackers with a teaspoon of crème fraîche each, about 200ml in total. Top each with half a teaspoon of salmon roe and a few snipped chives. Assemble just before serving so the crackers stay crisp and Josh can spit one out.","shop":["1 packet water crackers@Pantry","200ml crème fraîche@Dairy","100g salmon roe@Seafood","1 bunch chives@Produce"]}],"m":[{"n":"Street cart hot dog","note":"Griddled franks with mustard, sauerkraut and red onion sauce","how":"Simmer 8 franks in water with half an onion for 5 minutes, then griddle until blistered. Soften 2 sliced onions in oil for 15 minutes, add 2 tbsp tomato paste and a splash of vinegar. Steam 8 buns, fill and top with mustard and sauerkraut.","shop":["8 hot dog franks@Meat","8 hot dog buns@Bakery","1 bottle yellow mustard@Pantry","3 brown onions@Produce","1 jar sauerkraut@Pantry","1 tube tomato paste@Pantry"]}],"w":[{"n":"Giant choc chip cookie","note":"One huge soft cookie with piano keys piped on top","how":"Brown 150g butter and cool. Beat with 200g brown sugar and 1 egg, then mix in 250g flour, half a tsp bicarb and 200g choc chips. Press into a pizza tray and bake at 180C for 18 minutes. Cool and pipe white icing piano keys across it.","shop":["150g butter@Dairy","200g brown sugar@Pantry","1 egg@Dairy","250g plain flour@Pantry","200g choc chips@Pantry","200g icing sugar@Pantry"]}],"d":[{"n":"Root beer float","note":"Root beer poured slowly over two scoops of vanilla ice cream","how":"Chill four tall glasses in the freezer for 20 minutes. Add two scoops of vanilla ice cream to each, then pour 375ml root beer slowly down the side so it foams up. Serve with long spoons and straws.","shop":["4 375ml cans root beer@Drinks","1L vanilla ice cream@Frozen"]}],"shopping":["400g baby corn@Produce","180g butter@Dairy","2 limes@Produce","1 jar chilli flakes@Pantry","1 packet water crackers@Pantry","200ml crème fraîche@Dairy","100g salmon roe@Seafood","1 bunch chives@Produce","8 hot dog franks@Meat","8 hot dog buns@Bakery","1 bottle yellow mustard@Pantry","3 brown onions@Produce","1 jar sauerkraut@Pantry","1 tube tomato paste@Pantry","200g brown sugar@Pantry","1 egg@Dairy","250g plain flour@Pantry","200g choc chips@Pantry","200g icing sugar@Pantry","4 375ml cans root beer@Drinks","1L vanilla ice cream@Frozen"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"C.H.U.D. (1984)":{"poster":"assets/menu-posters/c-h-u-d-1984.jpg","colour":"#486234","servings":4,"tagline":"Don't go down the drain.","cue":"Serve the soup when the Reverend's soup kitchen opens.","menu":{"s":[{"n":"Sewer slime dip","note":"Extra green guacamole with lime, coriander and spinach, with corn chips.","how":"Blitz a handful of baby spinach with the juice of 2 limes until smooth. Mash 3 avocados with the spinach, a handful of chopped coriander, 1 chopped jalapeño and salt until slimy green. Serve with 300g corn chips.","shop":["50g baby spinach@Produce","2 limes@Produce","3 avocados@Produce","1 bunch coriander@Produce","1 jalapeño@Produce","300g corn chips@Pantry"]},{"n":"Manhole cover mini pizzas","note":"Mini pizzas with a pepperoni grate across the top.","how":"Roll 500g pizza dough thin and cut 12 rounds. Spread with pizza sauce, using 150ml, and top with 150g grated mozzarella. Slice 80g pepperoni into thin strips and lay them in a crosshatch like a manhole grate. Bake at 230C for 8 minutes.","shop":["500g pizza dough@Bakery","150ml pizza sauce@Pantry","150g mozzarella@Dairy","80g pepperoni@Deli"]}],"m":[{"n":"The Reverend's soup kitchen stew","note":"Hearty beef and vegetable stew with crusty bread.","how":"Brown 1kg diced beef chuck in batches. Add 2 chopped brown onions, 3 carrots, 2 celery sticks and 2 tbsp tomato paste and cook 5 minutes, then 1 litre beef stock. Cover and braise at 160C for 2.5 hours, adding 600g potatoes in chunks for the last hour. Serve with a loaf of Italian bread.","shop":["1kg beef chuck@Meat","2 brown onions@Produce","3 carrots@Produce","2 celery sticks@Produce","2 tbsp tomato paste@Pantry","1L beef stock@Pantry","600g potatoes@Produce","1 loaf Italian bread@Bakery"]}],"w":[{"n":"Sewer mud cake","note":"Dense chocolate mud cake under dragged dark ganache.","how":"Melt 200g dark chocolate with 200g butter. Whisk in 300g caster sugar and 4 eggs, then fold in 150g plain flour and 30g cocoa. Bake in a lined 22cm tin at 160C for 70 minutes and cool. Melt 150g dark chocolate with 150ml cream, pour over and drag with a fork like sewer muck.","shop":["350g dark chocolate@Pantry","200g butter@Dairy","300g caster sugar@Pantry","4 eggs@Dairy","150g plain flour@Pantry","30g cocoa@Pantry","150ml thickened cream@Dairy"]}],"d":[{"n":"Glowing green cordial","note":"Lime cordial and tonic that glows under a black light.","how":"Pour 40ml lime cordial into each of four tall glasses over ice and top with tonic water, about 250ml each. Tonic glows blue-white under a black light, so switch the lights off.","shop":["160ml lime cordial@Drinks","1L tonic water@Drinks","1kg ice@Frozen"]}],"shopping":["50g baby spinach@Produce","2 limes@Produce","3 avocados@Produce","1 bunch coriander@Produce","1 jalapeño@Produce","300g corn chips@Pantry","500g pizza dough@Bakery","150ml pizza sauce@Pantry","150g mozzarella@Dairy","80g pepperoni@Deli","1kg beef chuck@Meat","2 brown onions@Produce","3 carrots@Produce","2 celery sticks@Produce","2 tbsp tomato paste@Pantry","1L beef stock@Pantry","600g potatoes@Produce","1 loaf Italian bread@Bakery","350g dark chocolate@Pantry","200g butter@Dairy","300g caster sugar@Pantry","4 eggs@Dairy","150g plain flour@Pantry","30g cocoa@Pantry","150ml thickened cream@Dairy","160ml lime cordial@Drinks","1L tonic water@Drinks","1kg ice@Frozen"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Money Train (1995)":{"poster":"assets/menu-posters/money-train-1995.jpg","colour":"#cf6024","servings":4,"tagline":"Last train of the night. Snacks for the platform.","cue":"Pour drinks when the money train pulls into the station.","menu":{"s":[{"n":"Honey roasted nuts","note":"Mixed nuts roasted in honey, sugar and cinnamon.","how":"Toss 300g mixed nuts with 2 tbsp honey, 1 tbsp caster sugar, 1/2 tsp ground cinnamon and a pinch of salt. Spread on a lined tray and roast at 170C for 15 minutes, stirring halfway. Keep stirring as they cool so they don't clump.","shop":["300g mixed nuts@Pantry","2 tbsp honey@Pantry","1 tbsp caster sugar@Pantry","1/2 tsp ground cinnamon@Pantry"]},{"n":"Gold token cookies","note":"Shortbread rounds with a cut-out middle, brushed with edible gold.","how":"Beat 200g soft butter with 100g icing sugar and mix in 300g plain flour to a dough. Roll 5mm thick, cut rounds the size of a subway token and cut a small hole from the middle of each. Bake at 160C for 15 minutes and cool. Brush with edible gold dust mixed with a drop of water.","shop":["200g butter@Dairy","100g icing sugar@Pantry","300g plain flour@Pantry","1 jar edible gold dust@Pantry"]}],"m":[{"n":"Arroz con pollo","note":"Chicken thighs on saffron-gold rice with sofrito, olives and capers.","how":"Brown 800g chicken thighs and set aside. Fry 1 onion, 1 capsicum, 3 garlic cloves and a handful of coriander until soft, add 1 tsp ground annatto, 300g long grain rice, 60g green olives, 1 tbsp capers and 650ml chicken stock. Sit the chicken on top, cover and cook on low for 25 minutes until the rice is tender.","shop":["800g chicken thighs@Meat","1 brown onion@Produce","1 capsicum@Produce","3 garlic cloves@Produce","1 bunch coriander@Produce","1 tsp ground annatto@Pantry","300g long grain rice@Pantry","60g green olives@Deli","1 tbsp capers@Pantry","650ml chicken stock@Pantry"]}],"w":[{"n":"Crumb cake","note":"Butter cake buried under a thick cinnamon crumble.","how":"Rub 100g plain flour, 100g brown sugar, 1 tsp cinnamon and 80g cold butter into big crumbs. Beat 125g butter with 125g caster sugar, add 2 eggs and fold in 200g self-raising flour with 100ml milk. Spread in a lined 20cm tin, cover with the crumble and bake at 180C for 40 minutes.","shop":["100g plain flour@Pantry","100g brown sugar@Pantry","1 tsp ground cinnamon@Pantry","205g butter@Dairy","125g caster sugar@Pantry","2 eggs@Dairy","200g self-raising flour@Pantry","100ml full cream milk@Dairy"]}],"d":[{"n":"Tallboy in a paper bag","note":"Cold tallboy lagers, each wrapped in a brown paper bag.","how":"Chill four 700ml tallboy cans of lager for at least 3 hours. Slide each into a brown paper bag, fold the top down around the can and hand them out on the subway platform.","shop":["4 lager tallboys@Bottle shop","4 brown paper bags@Pantry"]}],"shopping":["300g mixed nuts@Pantry","2 tbsp honey@Pantry","1/2 tsp ground cinnamon@Pantry","405g butter@Dairy","100g icing sugar@Pantry","400g plain flour@Pantry","1 jar edible gold dust@Pantry","800g chicken thighs@Meat","1 brown onion@Produce","1 capsicum@Produce","3 garlic cloves@Produce","1 bunch coriander@Produce","1 tsp ground annatto@Pantry","300g long grain rice@Pantry","60g green olives@Deli","1 tbsp capers@Pantry","650ml chicken stock@Pantry","100g brown sugar@Pantry","1 tsp ground cinnamon@Pantry","140g caster sugar@Pantry","2 eggs@Dairy","200g self-raising flour@Pantry","100ml full cream milk@Dairy","4 lager tallboys@Bottle shop","4 brown paper bags@Pantry"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Inside Man (2006)":{"poster":"assets/menu-posters/inside-man-2006.jpg","colour":"#82652d","servings":4,"tagline":"The perfect heist needs a perfect lunch.","cue":"Serve the pizza when the hostages get their delivery.","menu":{"s":[{"n":"Hostage pizza bites","note":"Mini pizzas with tomato, mozzarella and pepperoni.","how":"Roll 500g pizza dough thin and cut 16 rounds with a glass. Top each with a spoon of pizza sauce, using 150ml, a pinch of grated mozzarella, 150g in total, and a slice of pepperoni. Bake at 230C for 8 minutes until golden underneath.","shop":["500g pizza dough@Bakery","150ml pizza sauce@Pantry","150g mozzarella@Dairy","16 slices pepperoni@Deli"]},{"n":"Brooklyn potato knishes","note":"Potato and slow onion in puff pastry logs with hot mustard.","how":"Boil 500g peeled potatoes 15 minutes and mash. Cook 1 diced brown onion in 30g butter over low heat for 15 minutes and mix in with salt and white pepper. Spread along 2 sheets puff pastry, roll into logs, cut into 8 and brush with 1 beaten egg. Bake at 200C for 25 minutes. Serve with 40g hot English mustard.","shop":["500g potatoes@Produce","1 brown onion@Produce","30g butter@Dairy","2 sheets puff pastry@Frozen","1 egg@Dairy","40g hot English mustard@Pantry"]}],"m":[{"n":"Manhattan steak sandwich","note":"Sliced sirloin on ciabatta with slow onions, rocket and horseradish cream.","how":"Cook 2 sliced brown onions in butter over low heat for 30 minutes until jammy. Sear 2 sirloin steaks, about 600g, hard for 3 minutes a side, rest and slice thin. Split and toast 4 pieces of ciabatta, spread with 100g horseradish cream and pile with steak, onions and 60g rocket.","shop":["2 brown onions@Produce","20g butter@Dairy","600g sirloin steak@Meat","4 ciabatta rolls@Bakery","100g horseradish cream@Pantry","60g rocket@Produce"]}],"w":[{"n":"Black and white cookies","note":"Soft vanilla cookies iced half vanilla, half chocolate.","how":"Beat 115g butter with 150g caster sugar, add 1 egg, 80g sour cream and 1 tsp vanilla, then mix in 250g plain flour and 1 tsp baking powder. Scoop 12 mounds and bake at 180C for 12 minutes. Ice half of each flat side with 250g icing sugar mixed with hot water, then stir 2 tbsp cocoa into the rest for the other half.","shop":["115g butter@Dairy","150g caster sugar@Pantry","1 egg@Dairy","80g sour cream@Dairy","1 tsp vanilla extract@Pantry","250g plain flour@Pantry","1 tsp baking powder@Pantry","250g icing sugar@Pantry","2 tbsp cocoa@Pantry"]}],"d":[{"n":"Espresso","note":"Short double ristretto with a glass of water.","how":"For each cup, grind 18g espresso beans fine and pull a short double, about 25g in the cup. Make four, using 72g beans, and serve each with a small glass of water.","shop":["72g espresso beans@Pantry"]}],"shopping":["500g pizza dough@Bakery","150ml pizza sauce@Pantry","150g mozzarella@Dairy","16 slices pepperoni@Deli","500g potatoes@Produce","1 brown onion@Produce","165g butter@Dairy","2 sheets puff pastry@Frozen","2 egg@Dairy","40g hot English mustard@Pantry","2 brown onions@Produce","600g sirloin steak@Meat","4 ciabatta rolls@Bakery","100g horseradish cream@Pantry","60g rocket@Produce","150g caster sugar@Pantry","80g sour cream@Dairy","1 tsp vanilla extract@Pantry","250g plain flour@Pantry","1 tsp baking powder@Pantry","250g icing sugar@Pantry","2 tbsp cocoa@Pantry","72g espresso beans@Pantry"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Escape from New York (1981)":{"poster":"assets/menu-posters/escape-from-new-york-1981.jpg","colour":"#b93423","servings":4,"tagline":"Get in. Get the President. Get dinner.","cue":"Serve the mains when the Duke rolls up in his chandelier car.","menu":{"s":[{"n":"Cabbie's road snacks","note":"Beef jerky and honey-roasted peanuts with a few dried chillies.","how":"Tip 150g beef jerky and 200g honey-roasted peanuts into a big paper bag. Add 4 dried chillies broken in half for a bit of heat, close the top and shake well. Serve straight from the bag.","shop":["150g beef jerky@Pantry","200g honey-roasted peanuts@Pantry","4 dried chillies@Pantry"]},{"n":"Survival tin sardines","note":"Sardines on saltine crackers with lemon, hot sauce and parsley.","how":"Drain 2 tins sardines in oil, about 220g. Lay a sardine on each of 24 saltine crackers, squeeze over lemon, add a drop of hot sauce and a little chopped parsley. Serve on the tin lids for the full survival look.","shop":["220g tinned sardines@Pantry","24 saltine crackers@Pantry","1 lemon@Produce","1 tsp hot sauce@Pantry","1 bunch parsley@Produce"]}],"m":[{"n":"Liberty Island burgers","note":"Double smashed patties with cheese, grilled onion, pickles and mustard.","how":"Roll 800g beef mince into 8 balls. Smash each flat on a smoking flat-top or heavy pan, season, cook 2 minutes, flip and add a slice of American cheese. Grill 1 sliced brown onion alongside. Stack two patties per toasted bun with the onion, sliced pickles and yellow mustard.","shop":["800g beef mince@Meat","8 slices American cheese@Dairy","1 brown onion@Produce","4 burger buns@Bakery","4 dill pickles@Pantry","3 tbsp yellow mustard@Pantry"]}],"w":[{"n":"Ration bars","note":"Chewy golden syrup oat bars topped with dark chocolate.","how":"Melt 150g butter with 3 tbsp golden syrup and 100g brown sugar, then stir in 250g rolled oats. Press into a lined 20cm square tin and bake at 180C for 20 minutes. Cool, spread with 100g melted dark chocolate and cut into 12 bars once set.","shop":["150g butter@Dairy","3 tbsp golden syrup@Pantry","100g brown sugar@Pantry","250g rolled oats@Pantry","100g dark chocolate@Pantry"]}],"d":[{"n":"Black coffee","note":"Drip coffee served black in steel mugs.","how":"Brew 1 litre of drip coffee with 60g ground coffee. Pour black into four steel mugs and keep the pot hot on the stove for refills through the night.","shop":["60g ground coffee@Pantry"]}],"shopping":["150g beef jerky@Pantry","200g honey-roasted peanuts@Pantry","4 dried chillies@Pantry","220g tinned sardines@Pantry","24 saltine crackers@Pantry","1 lemon@Produce","1 tsp hot sauce@Pantry","1 bunch parsley@Produce","800g beef mince@Meat","8 slices American cheese@Dairy","1 brown onion@Produce","4 burger buns@Bakery","4 dill pickles@Pantry","3 tbsp yellow mustard@Pantry","150g butter@Dairy","3 tbsp golden syrup@Pantry","100g brown sugar@Pantry","250g rolled oats@Pantry","100g dark chocolate@Pantry","60g ground coffee@Pantry"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Serpico (1973)":{"poster":"assets/menu-posters/serpico-1973.jpg","colour":"#656235","servings":4,"tagline":"One honest cop. No free sandwiches.","cue":"Serve the mains when Frank turns down the free meal at the deli.","menu":{"s":[{"n":"Village bagels and lox","note":"Toasted bagels with cream cheese, lox, capers, onion and dill.","how":"Split and toast 4 bagels. Spread each half thickly with cream cheese, using 200g in total. Top with 200g smoked salmon, 1 tbsp capers, thinly sliced red onion and small sprigs of dill. Cut each half in two to share.","shop":["4 bagels@Bakery","200g cream cheese@Dairy","200g smoked salmon@Seafood","1 tbsp capers@Pantry","1 red onion@Produce","1 bunch dill@Produce"]},{"n":"Hot pretzels","note":"Bakery soft pretzels refreshed with butter and salt, mustard alongside.","how":"Brush 4 soft pretzels with 20g melted butter and sprinkle with 1 tsp rock salt. Bake at 200C for 5 minutes until hot and glossy. Cut in half and serve with 100g yellow mustard.","shop":["4 soft pretzels@Bakery","20g butter@Dairy","1 tsp rock salt@Pantry","100g yellow mustard@Pantry"]}],"m":[{"n":"Deli hero, paid for","note":"Steamed pastrami heroes with Swiss, coleslaw and Russian dressing.","how":"Steam 500g sliced pastrami for 10 minutes until glossy. Mix 100g mayonnaise with 2 tbsp tomato sauce, 1 tsp horseradish and 1 tbsp chopped pickle for Russian dressing. Toss 250g coleslaw mix with half the dressing. Fill 4 long rolls with pastrami, 8 slices Swiss cheese, the slaw and the rest of the dressing.","shop":["500g pastrami@Deli","100g mayonnaise@Pantry","2 tbsp tomato sauce@Pantry","1 tsp horseradish@Pantry","1 dill pickle@Pantry","250g coleslaw mix@Produce","4 long rolls@Bakery","8 slices Swiss cheese@Deli"]}],"w":[{"n":"Black and white cookies","note":"Soft vanilla cookies iced half vanilla, half chocolate.","how":"Beat 115g butter with 150g caster sugar, add 1 egg, 80g sour cream and 1 tsp vanilla, then mix in 250g plain flour and 1 tsp baking powder. Scoop 12 mounds onto lined trays and bake at 180C for 12 minutes. Make a thick icing with 250g icing sugar and hot water, ice half of each flat side, then add 2 tbsp cocoa to the rest and ice the other half.","shop":["115g butter@Dairy","150g caster sugar@Pantry","1 egg@Dairy","80g sour cream@Dairy","1 tsp vanilla extract@Pantry","250g plain flour@Pantry","1 tsp baking powder@Pantry","250g icing sugar@Pantry","2 tbsp cocoa@Pantry"]}],"d":[{"n":"Diner coffee, paid for","note":"Drip coffee in thick mugs, paid for before you drink it.","how":"Brew 1 litre of drip coffee with 60g ground coffee. Pour into four thick mugs with 200ml milk on the side. Pay for it first, the way Serpico always did.","shop":["60g ground coffee@Pantry","200ml full cream milk@Dairy"]}],"shopping":["4 bagels@Bakery","200g cream cheese@Dairy","200g smoked salmon@Seafood","1 tbsp capers@Pantry","1 red onion@Produce","1 bunch dill@Produce","4 soft pretzels@Bakery","135g butter@Dairy","1 tsp rock salt@Pantry","100g yellow mustard@Pantry","500g pastrami@Deli","100g mayonnaise@Pantry","2 tbsp tomato sauce@Pantry","1 tsp horseradish@Pantry","1 dill pickle@Pantry","250g coleslaw mix@Produce","4 long rolls@Bakery","8 slices Swiss cheese@Deli","150g caster sugar@Pantry","1 egg@Dairy","80g sour cream@Dairy","1 tsp vanilla extract@Pantry","250g plain flour@Pantry","1 tsp baking powder@Pantry","250g icing sugar@Pantry","2 tbsp cocoa@Pantry","60g ground coffee@Pantry","200ml full cream milk@Dairy"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Home Alone 2: Lost in New York (1992)":{"poster":"assets/menu-posters/home-alone-2-lost-in-new-york-1992.jpg","colour":"#205139","servings":4,"tagline":"Room service. Charge it to Dad.","cue":"Order room service when Kevin gets his own suite.","menu":{"s":[{"n":"Plaza minibar mix","note":"Buttery rosemary nuts with chocolate almonds and pretzels.","how":"Melt 30g butter with 2 tbsp brown sugar and 1 tbsp chopped rosemary. Toss through 300g mixed nuts, spread on a tray and roast at 170C for 12 minutes, stirring once. Cool, then mix with 150g chocolate almonds and 100g pretzels.","shop":["30g butter@Dairy","2 tbsp brown sugar@Pantry","1 bunch rosemary@Produce","300g mixed nuts@Pantry","150g chocolate almonds@Pantry","100g pretzels@Pantry"]},{"n":"Limo pizza bites","note":"Toasted English muffins with pizza sauce and bubbling mozzarella.","how":"Split 4 English muffins and toast lightly. Spread each half with pizza sauce, using 150ml in total, and top with 150g grated mozzarella. Grill for 3 to 4 minutes until bubbling and spotted brown. Cut into halves to serve.","shop":["4 English muffins@Bakery","150ml pizza sauce@Pantry","150g mozzarella@Dairy"]}],"m":[{"n":"Lobster mac and cheese","note":"Macaroni in Gruyère cheese sauce with butter-poached lobster and crumbs.","how":"Gently poach the meat of 2 lobster tails in 40g butter for 4 minutes and chop. Melt 40g butter, stir in 40g flour, then whisk in 600ml warm milk and simmer 5 minutes. Stir in 120g grated Gruyère and 100g cheddar. Fold through 400g cooked macaroni and the lobster, tip into a dish, top with 40g panko mixed with 20g melted butter and bake at 200C for 20 minutes.","shop":["2 lobster tails@Seafood","100g butter@Dairy","40g plain flour@Pantry","600ml full cream milk@Dairy","120g Gruyère@Deli","100g cheddar@Dairy","400g macaroni@Pantry","40g panko@Pantry"]}],"w":[{"n":"Room service sundae","note":"Towering sundae with hot fudge, cream, nuts, sprinkles and a cherry.","how":"Melt 100g dark chocolate with 100ml thickened cream for hot fudge. Whip another 200ml cream. Pile 8 scoops vanilla ice cream into four tall glasses, pour over the fudge, add the cream, 40g chopped nuts, sprinkles and a maraschino cherry on each.","shop":["100g dark chocolate@Pantry","300ml thickened cream@Dairy","1L vanilla ice cream@Frozen","40g mixed nuts@Pantry","1 jar sprinkles@Pantry","4 maraschino cherries@Pantry"]}],"d":[{"n":"Hot chocolate with whipped cream","note":"Rich hot chocolate topped with whipped cream and marshmallows.","how":"Heat 1 litre full cream milk until steaming and whisk in 150g chopped dark chocolate until smooth. Pour into four mugs, top with 150ml whipped thickened cream and a handful of marshmallows.","shop":["1L full cream milk@Dairy","150g dark chocolate@Pantry","150ml thickened cream@Dairy","100g marshmallows@Pantry"]}],"shopping":["130g butter@Dairy","2 tbsp brown sugar@Pantry","1 bunch rosemary@Produce","340g mixed nuts@Pantry","150g chocolate almonds@Pantry","100g pretzels@Pantry","4 English muffins@Bakery","150ml pizza sauce@Pantry","150g mozzarella@Dairy","2 lobster tails@Seafood","40g plain flour@Pantry","1.6L full cream milk@Dairy","120g Gruyère@Deli","100g cheddar@Dairy","400g macaroni@Pantry","40g panko@Pantry","250g dark chocolate@Pantry","450ml thickened cream@Dairy","1L vanilla ice cream@Frozen","1 jar sprinkles@Pantry","4 maraschino cherries@Pantry","100g marshmallows@Pantry"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"The Departed (2006)":{"poster":"assets/menu-posters/the-departed-2006.jpg","colour":"#233c52","servings":4,"tagline":"Two rats. One city. Plenty of chowder.","cue":"Serve the mains when Costigan and Sullivan figure out who the other one is.","menu":{"s":[{"n":"Boston clam chowder cups","note":"Creamy clam and potato chowder with bacon and oyster crackers.","how":"Fry 150g diced bacon until crisp, then sweat 1 diced onion and 2 celery sticks in the fat. Add 400g diced potatoes, 500ml clam juice or fish stock and thyme and simmer 15 minutes. Stir in 250g chopped clam meat and 200ml cream for the last 3 minutes. Serve in cups with 100g oyster crackers.","shop":["150g bacon@Meat","1 brown onion@Produce","2 celery sticks@Produce","400g potatoes@Produce","500ml fish stock@Pantry","250g clam meat@Seafood","200ml thickened cream@Dairy","100g oyster crackers@Pantry"]},{"n":"Southie bar fries","note":"Double-fried chips with malt vinegar and salt in paper cones.","how":"Cut 1kg potatoes into chips, rinse and dry. Fry at 140C for 6 minutes until soft, rest 20 minutes, then fry at 185C until crisp. Salt well, splash with 3 tbsp malt vinegar and serve in paper cones.","shop":["1kg potatoes@Produce","1.5L vegetable oil@Pantry","3 tbsp malt vinegar@Pantry"]}],"m":[{"n":"Southie fish and chips","note":"Lager-battered flathead with chips, minted mushy peas and malt vinegar.","how":"Whisk 200g plain flour, 50g cornflour and 330ml ice-cold lager into a batter. Dust 800g flathead fillets in flour, dip and fry at 180C for 4 minutes. Fry 1kg potatoes as chips at 140C then 185C. Cook 400g frozen peas, crush with butter and mint. Serve with malt vinegar.","shop":["200g plain flour@Pantry","50g cornflour@Pantry","330ml lager@Bottle shop","800g flathead fillets@Seafood","1kg potatoes@Produce","400g frozen peas@Frozen","20g butter@Dairy","1 bunch mint@Produce","2L vegetable oil@Pantry","2 tbsp malt vinegar@Pantry"]}],"w":[{"n":"Boston cream pie","note":"Two sponge layers filled with vanilla custard under dark chocolate ganache.","how":"Whisk 4 eggs and 120g sugar until thick, fold in 120g flour and bake in two 20cm tins at 180C for 18 minutes. For custard, heat 300ml milk, whisk into 3 yolks, 60g sugar and 25g cornflour and cook until thick, then cool. Sandwich the sponges with custard. Melt 100g dark chocolate with 100ml cream and pour over the top.","shop":["7 eggs@Dairy","180g caster sugar@Pantry","120g plain flour@Pantry","300ml full cream milk@Dairy","25g cornflour@Pantry","100g dark chocolate@Pantry","100ml thickened cream@Dairy"]}],"d":[{"n":"Cranberry juice","note":"Cranberry juice over ice, with vodka if you need to keep your cover.","how":"Fill four short glasses with ice and pour 150ml cranberry juice into each. For anyone keeping their cover, add 30ml vodka, about 120ml for four.","shop":["600ml cranberry juice@Drinks","120ml vodka@Bottle shop","1kg ice@Frozen"]}],"shopping":["150g bacon@Meat","1 brown onion@Produce","2 celery sticks@Produce","2.4kg potatoes@Produce","500ml fish stock@Pantry","250g clam meat@Seafood","300ml thickened cream@Dairy","100g oyster crackers@Pantry","3.5L vegetable oil@Pantry","5 tbsp malt vinegar@Pantry","320g plain flour@Pantry","75g cornflour@Pantry","330ml lager@Bottle shop","800g flathead fillets@Seafood","400g frozen peas@Frozen","20g butter@Dairy","1 bunch mint@Produce","7 eggs@Dairy","180g caster sugar@Pantry","300ml full cream milk@Dairy","100g dark chocolate@Pantry","600ml cranberry juice@Drinks","120ml vodka@Bottle shop","1kg ice@Frozen"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Get Shorty (1995)":{"poster":"assets/menu-posters/get-shorty-1995.jpg","colour":"#e15f20","servings":4,"tagline":"Look at me. Now pass the dip.","cue":"Serve the mains when Chili starts pitching his movie idea.","menu":{"s":[{"n":"Miami prawn cocktail","note":"Iced prawns on sliced avocado with a lime and horseradish cocktail sauce.","how":"Poach 500g peeled green prawns for 2 minutes in salted water, then chill in iced water. Mix 120ml tomato sauce with the juice of 1 lime, 1 tsp horseradish and a pinch of chilli flakes. Fan 2 sliced avocados across four plates, pile on the prawns and spoon over the sauce. Serve with lime wedges.","shop":["500g green prawns@Seafood","2 limes@Produce","2 avocados@Produce","120ml tomato sauce@Pantry","1 tsp horseradish@Pantry"]},{"n":"Diner fries","note":"Hand-cut chips fried twice until crisp and salted straight away.","how":"Cut 1kg potatoes into chips and rinse well. Fry at 140C for 6 minutes until soft but pale, drain and rest 20 minutes. Fry again at 185C for 3 to 4 minutes until crisp and golden. Salt straight away with fine salt and serve in paper cones.","shop":["1kg potatoes@Produce","1.5L vegetable oil@Pantry","1 tsp fine salt@Pantry"]}],"m":[{"n":"Chili Palmer's steak frites","note":"Seared sirloin with red wine butter sauce and double-fried frites.","how":"Fry 1kg potatoes cut into thin frites at 140C for 5 minutes, rest, then at 185C until crisp. Season 4 sirloin steaks, about 800g, sear hard for 3 minutes a side and rest. Sweat 2 chopped shallots in the pan fat, add 150ml red wine and reduce by two thirds, then whisk in 50g cold butter. Slice the steak and spoon the sauce over.","shop":["1kg potatoes@Produce","1.5L vegetable oil@Pantry","800g sirloin steak@Meat","2 shallots@Produce","150ml red wine@Bottle shop","50g butter@Dairy"]}],"w":[{"n":"B-movie popcorn sundae","note":"Vanilla ice cream with hot fudge, caramel popcorn and salted peanuts.","how":"Pop 40g popcorn kernels. Melt 50g butter with 80g brown sugar, toss through the popcorn and bake at 150C for 10 minutes to set. Melt 100g dark chocolate with 100ml cream for hot fudge. Scoop 8 balls of vanilla ice cream into four bowls, pour over the fudge and top with the popcorn and 50g salted peanuts.","shop":["40g popcorn kernels@Pantry","50g butter@Dairy","80g brown sugar@Pantry","100g dark chocolate@Pantry","100ml thickened cream@Dairy","1L vanilla ice cream@Frozen","50g salted peanuts@Pantry"]}],"d":[{"n":"Bloody Mary","note":"Spiced vodka and tomato juice rolled between tins, with a celery stick.","how":"For each drink, put 45ml vodka, 120ml tomato juice, 10ml lemon juice, 2 dashes Worcestershire sauce, 2 dashes hot sauce and a pinch each of celery salt and pepper in a tin with ice. Pour back and forth between two tins 5 times, strain over fresh ice and add a celery stick. Makes four.","shop":["180ml vodka@Bottle shop","500ml tomato juice@Drinks","1 lemon@Produce","1 tsp Worcestershire sauce@Pantry","1 tsp hot sauce@Pantry","4 celery sticks@Produce","1kg ice@Frozen"]}],"shopping":["500g green prawns@Seafood","2 limes@Produce","2 avocados@Produce","120ml tomato sauce@Pantry","1 tsp horseradish@Pantry","2kg potatoes@Produce","3L vegetable oil@Pantry","1 tsp fine salt@Pantry","800g sirloin steak@Meat","2 shallots@Produce","150ml red wine@Bottle shop","100g butter@Dairy","40g popcorn kernels@Pantry","80g brown sugar@Pantry","100g dark chocolate@Pantry","100ml thickened cream@Dairy","1L vanilla ice cream@Frozen","50g salted peanuts@Pantry","180ml vodka@Bottle shop","500ml tomato juice@Drinks","1 lemon@Produce","1 tsp Worcestershire sauce@Pantry","1 tsp hot sauce@Pantry","4 celery sticks@Produce","1kg ice@Frozen"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Bugsy (1991)":{"poster":"assets/menu-posters/bugsy-1991.jpg","colour":"#b78a37","servings":4,"tagline":"He dreamed up Las Vegas. Then he blew the budget.","cue":"Serve dessert when the Flamingo finally opens its doors.","menu":{"s":[{"n":"Hollywood party blini and caviar","note":"Warm blini with crème fraîche, salmon roe and chives.","how":"Warm 16 buckwheat blini at 180C for 5 minutes. Top each with a teaspoon of crème fraîche, half a teaspoon of salmon roe and snipped chives. Serve straight away on a silver tray.","shop":["16 buckwheat blini@Bakery","100g crème fraîche@Dairy","50g salmon roe@Seafood","1 bunch chives@Produce"]},{"n":"Desert devilled eggs","note":"Devilled eggs whipped with mayo, mustard and cayenne.","how":"Boil 8 eggs for 10 minutes, cool in iced water and peel. Halve and whip the yolks with 3 tbsp mayonnaise, 1 tsp Dijon mustard, a pinch of cayenne and 1 tsp pickle juice until smooth. Pipe back into the whites and dust with smoked paprika.","shop":["8 eggs@Dairy","3 tbsp mayonnaise@Pantry","1 jar Dijon mustard@Pantry","1 pinch cayenne pepper@Pantry","1 tsp smoked paprika@Pantry"]}],"m":[{"n":"Flamingo steak Diane","note":"Seared scotch fillet in a brandy, mustard and cream pan sauce.","how":"Flatten 4 scotch fillet steaks, about 800g, and sear hot for 2 minutes a side, then rest. In the same pan, soften 2 chopped shallots and 1 garlic clove in 30g butter, add 60ml brandy and flame. Stir in 1 tbsp Dijon mustard, 1 tbsp Worcestershire sauce, 150ml beef stock and 150ml cream and reduce 4 minutes. Return the steaks to coat.","shop":["800g scotch fillet@Meat","2 shallots@Produce","1 garlic clove@Produce","30g butter@Dairy","60ml brandy@Bottle shop","1 jar Dijon mustard@Pantry","1 tbsp Worcestershire sauce@Pantry","150ml beef stock@Pantry","150ml thickened cream@Dairy"]}],"w":[{"n":"Pink flamingo pavlova","note":"Crisp pavlova with pink raspberry cream.","how":"Whisk 4 egg whites to soft peaks, then add 220g caster sugar a spoon at a time until glossy. Fold in 1 tsp cornflour and 1 tsp white vinegar, spread into a round and bake at 120C for 90 minutes, then cool in the oven. Whip 300ml thickened cream and fold through 125g crushed raspberries. Pile on top just before serving.","shop":["4 eggs@Dairy","220g caster sugar@Pantry","1 tsp cornflour@Pantry","1 tsp white vinegar@Pantry","300ml thickened cream@Dairy","125g raspberries@Produce"]}],"d":[{"n":"Champagne","note":"Brut champagne chilled hard and poured into coupes.","how":"Chill one 750ml bottle of brut champagne to about 7C, around 3 hours in the fridge or 30 minutes in an ice bucket. Pour into four coupes, about 180ml each.","shop":["750ml champagne@Bottle shop"]}],"shopping":["16 buckwheat blini@Bakery","100g crème fraîche@Dairy","50g salmon roe@Seafood","1 bunch chives@Produce","12 eggs@Dairy","3 tbsp mayonnaise@Pantry","1 jar Dijon mustard@Pantry","1 pinch cayenne pepper@Pantry","1 tsp smoked paprika@Pantry","800g scotch fillet@Meat","2 shallots@Produce","1 garlic clove@Produce","30g butter@Dairy","60ml brandy@Bottle shop","1 tbsp Worcestershire sauce@Pantry","150ml beef stock@Pantry","450ml thickened cream@Dairy","220g caster sugar@Pantry","1 tsp cornflour@Pantry","1 tsp white vinegar@Pantry","125g raspberries@Produce","750ml champagne@Bottle shop"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Donnie Brasco (1997)":{"poster":"assets/menu-posters/donnie-brasco-1997.jpg","colour":"#24413d","servings":4,"tagline":"Forget about it.","cue":"Before the mains, explain all the meanings of \"forget about it\" to the table.","menu":{"s":[{"n":"Miami garlic prawns","note":"Butterflied prawns sizzled with garlic, chilli, white wine and butter.","how":"Butterfly 500g green prawns. Heat 3 tbsp olive oil until very hot, add the prawns with 4 sliced garlic cloves and a pinch of chilli flakes and cook 2 minutes. Add 80ml white wine, bubble for a minute, then swirl in 30g butter and chopped parsley. Serve in the pan with crusty bread for the juices.","shop":["500g green prawns@Seafood","3 tbsp olive oil@Pantry","4 garlic cloves@Produce","80ml white wine@Bottle shop","30g butter@Dairy","1 bunch parsley@Produce","1 baguette@Bakery"]},{"n":"Fried mozzarella","note":"Golden crumbed mozzarella fingers with warm tomato sauce to dip.","how":"Cut 400g low-moisture mozzarella into 16 fingers and freeze 20 minutes. Dip in 50g flour, then 2 beaten eggs, then 100g breadcrumbs, then egg and crumbs again. Fry at 180C for 90 seconds until golden. Warm 250ml passata with a pinch of salt and oregano for dipping.","shop":["400g low-moisture mozzarella@Dairy","50g plain flour@Pantry","2 eggs@Dairy","100g breadcrumbs@Pantry","250ml passata@Pantry","1L vegetable oil@Pantry"]}],"m":[{"n":"Shoes-on teriyaki steak","note":"Seared sirloin brushed with sticky teriyaki, with rice and greens.","how":"Simmer 80ml soy sauce, 80ml mirin, 60ml sake and 2 tbsp sugar for 5 minutes until syrupy. Sear 4 sirloin steaks, about 800g, in a smoking pan for 3 minutes a side, brushing with glaze in the last minute. Rest 5 minutes and slice. Serve with 400g steamed short grain rice and 4 blanched bok choy.","shop":["80ml soy sauce@Pantry","80ml mirin@Pantry","60ml sake@Bottle shop","2 tbsp caster sugar@Pantry","800g sirloin steak@Meat","400g short grain rice@Pantry","4 bok choy@Produce"]}],"w":[{"n":"Ricotta cheesecake","note":"Light baked ricotta cheesecake with lemon and vanilla.","how":"Drain 750g fresh ricotta in a sieve for 2 hours. Beat with 150g caster sugar, 4 eggs, the zest of 1 lemon and 1 tsp vanilla extract until smooth. Pour into a lined 22cm springform tin and bake at 160C for 60 minutes. Turn off the oven and cool inside with the door ajar. Dust with icing sugar to serve.","shop":["750g fresh ricotta@Dairy","150g caster sugar@Pantry","4 eggs@Dairy","1 lemon@Produce","1 tsp vanilla extract@Pantry","1 tbsp icing sugar@Pantry"]}],"d":[{"n":"Scotch on the rocks","note":"Blended Scotch over one big ice cube in a heavy tumbler.","how":"Put a single large ice cube in each of four heavy tumblers. Pour 45ml blended Scotch over each, about 180ml in total. Serve straight away, no garnish.","shop":["180ml blended Scotch@Bottle shop","4 large ice cubes@Frozen"]}],"shopping":["500g green prawns@Seafood","3 tbsp olive oil@Pantry","4 garlic cloves@Produce","80ml white wine@Bottle shop","30g butter@Dairy","1 bunch parsley@Produce","1 baguette@Bakery","400g low-moisture mozzarella@Dairy","50g plain flour@Pantry","6 eggs@Dairy","100g breadcrumbs@Pantry","250ml passata@Pantry","1L vegetable oil@Pantry","80ml soy sauce@Pantry","80ml mirin@Pantry","60ml sake@Bottle shop","800g sirloin steak@Meat","400g short grain rice@Pantry","4 bok choy@Produce","750g fresh ricotta@Dairy","180g caster sugar@Pantry","1 lemon@Produce","1 tsp vanilla extract@Pantry","1 tbsp icing sugar@Pantry","180ml blended Scotch@Bottle shop","4 large ice cubes@Frozen"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Carlito's Way (1993)":{"poster":"assets/menu-posters/carlitos-way-1993.jpg","colour":"#9f2442","servings":4,"tagline":"One last score, then paradise.","cue":"Have dessert on the table before the Grand Central finale.","menu":{"s":[{"n":"Bacalaitos","note":"Lacy salt cod fritters with garlic and coriander.","how":"Soak 250g salt cod for 24 hours, changing the water three times, then flake. Whisk 200g plain flour, 2 tsp baking powder, 300ml water, 2 crushed garlic cloves and a handful of chopped coriander into a loose batter and fold in the cod. Fry wide flat spoonfuls in 180C oil until golden and lacy, drain and salt.","shop":["250g salt cod@Seafood","200g plain flour@Pantry","2 tsp baking powder@Pantry","2 garlic cloves@Produce","1 bunch coriander@Produce","1L vegetable oil@Pantry"]},{"n":"Tostones","note":"Twice-fried smashed green plantain with garlic and lime mojo.","how":"Peel 3 green plantains and cut into 3cm chunks. Fry at 160C for 4 minutes until soft, smash flat with a heavy glass and fry again at 190C until crisp. Salt well. Mix 3 crushed garlic cloves with the juice of 2 limes and 60ml olive oil and spoon over.","shop":["3 green plantains@Produce","3 garlic cloves@Produce","2 limes@Produce","60ml extra virgin olive oil@Pantry","1L vegetable oil@Pantry"]}],"m":[{"n":"Pernil","note":"Garlic and oregano roast pork shoulder with crackling, rice and pigeon peas.","how":"Stab a 2kg pork shoulder all over and rub with 8 crushed garlic cloves, 2 tsp dried oregano, 2 tsp salt and 2 tbsp white vinegar. Marinate overnight. Roast skin up at 160C for 5 hours, then 230C for 20 minutes to crackle. Cook 400g long grain rice with a 400g tin of pigeon peas, stock and a little onion to serve alongside.","shop":["2kg pork shoulder@Meat","8 garlic cloves@Produce","2 tsp dried oregano@Pantry","2 tbsp white vinegar@Pantry","400g long grain rice@Pantry","400g pigeon peas@Pantry"]}],"w":[{"n":"Paradise flan","note":"Coconut caramel flan, baked slowly and turned out cold.","how":"Melt 150g caster sugar in a pan until deep amber and pour into a ring tin. Blend a 395g tin condensed milk, 270ml coconut milk, 375ml evaporated milk and 5 eggs and pour over the caramel. Bake in a water bath at 160C for 50 minutes until just set. Chill overnight, run a knife around and turn out onto a plate.","shop":["150g caster sugar@Pantry","395g condensed milk@Pantry","270ml coconut milk@Pantry","375ml evaporated milk@Pantry","5 eggs@Dairy"]}],"d":[{"n":"Rum and cola","note":"Golden rum over ice with cold cola and a big squeeze of lime.","how":"Fill four tall glasses with ice. Pour 45ml golden rum into each, about 180ml in total, top with cold cola and squeeze in a big wedge of lime, about 2 limes for four drinks.","shop":["180ml golden rum@Bottle shop","1.25L cola@Drinks","2 limes@Produce","1kg ice@Frozen"]}],"shopping":["250g salt cod@Seafood","200g plain flour@Pantry","2 tsp baking powder@Pantry","13 garlic cloves@Produce","1 bunch coriander@Produce","2L vegetable oil@Pantry","3 green plantains@Produce","4 limes@Produce","60ml extra virgin olive oil@Pantry","2kg pork shoulder@Meat","2 tsp dried oregano@Pantry","2 tbsp white vinegar@Pantry","400g long grain rice@Pantry","400g pigeon peas@Pantry","150g caster sugar@Pantry","395g condensed milk@Pantry","270ml coconut milk@Pantry","375ml evaporated milk@Pantry","5 eggs@Dairy","180ml golden rum@Bottle shop","1.25L cola@Drinks","1kg ice@Frozen"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"The Godfather Part III (1990)":{"poster":"assets/menu-posters/the-godfather-part-iii-1990.jpg","colour":"#711e19","servings":4,"tagline":"The past never stays buried.","cue":"Hold the cannoli until the opera in the final act, and keep an eye on who made them.","menu":{"s":[{"n":"Palermo panelle","note":"Golden chickpea fritters fried crisp, finished with lemon and salt.","how":"Whisk 250g chickpea flour into 750ml cold water with 1 tsp salt until smooth. Cook over medium heat, stirring constantly, for 10 minutes until very thick. Add 2 tbsp chopped parsley, spread 1cm thick on an oiled tray and leave to set for 1 hour. Cut into squares and fry in 180C oil until puffed and golden. Drain, salt, and serve with lemon wedges.","shop":["250g chickpea flour@Pantry","1 bunch parsley@Produce","2 lemons@Produce","1L vegetable oil@Pantry"]},{"n":"Prosciutto and melon","note":"Ripe rockmelon wedges draped with prosciutto, pepper and olive oil.","how":"Leave 1 rockmelon at room temperature for an hour. Halve, scoop out the seeds, cut into 12 long wedges and cut off the skin. Drape each wedge with a slice of prosciutto (about 150g in total), add a crack of black pepper and a drizzle of extra virgin olive oil just before serving.","shop":["1 rockmelon@Produce","150g prosciutto@Deli","2 tbsp extra virgin olive oil@Pantry"]}],"m":[{"n":"Pasta alla Norma","note":"Rigatoni with fried eggplant, tomato and basil, under grated ricotta salata.","how":"Cut 2 eggplants into thick half moons and fry in batches in 120ml olive oil until deep gold, drain. Fry 3 sliced garlic cloves in 2 tbsp of the oil, add 800g San Marzano tomatoes and a handful of basil, simmer 20 minutes and season. Cook 500g rigatoni until al dente, toss with the sauce, eggplant and a splash of pasta water. Grate 100g ricotta salata heavily over the top.","shop":["2 eggplants@Produce","120ml olive oil@Pantry","3 garlic cloves@Produce","800g San Marzano tomatoes@Pantry","1 bunch basil@Produce","500g rigatoni@Pantry","100g ricotta salata@Deli"]}],"w":[{"n":"Opera night cannoli","note":"Crisp shells filled with sweet ricotta, candied orange and pistachio.","how":"Drain 500g fresh ricotta in a sieve for 2 hours. Beat with 80g icing sugar, 1/2 tsp ground cinnamon and 40g finely chopped candied orange peel. Spoon into a piping bag and fill 8 cannoli shells just before serving. Dip each end in 30g chopped pistachios and dust with a little more icing sugar.","shop":["500g fresh ricotta@Dairy","80g icing sugar@Pantry","1/2 tsp ground cinnamon@Pantry","40g candied orange peel@Pantry","8 cannoli shells@Bakery","30g pistachios@Pantry"]}],"d":[{"n":"Nero d'Avola","note":"Sicilian red opened early and served at cellar temperature.","how":"Open one 750ml bottle of Nero d'Avola 30 minutes before dinner and keep it at about 16C, cooler than the room. Pour into four large glasses, about 180ml each, with no ice.","shop":["750ml Nero d'Avola@Bottle shop"]}],"shopping":["250g chickpea flour@Pantry","1 bunch parsley@Produce","2 lemons@Produce","1L vegetable oil@Pantry","1 rockmelon@Produce","150g prosciutto@Deli","2 tbsp extra virgin olive oil@Pantry","2 eggplants@Produce","120ml olive oil@Pantry","3 garlic cloves@Produce","800g San Marzano tomatoes@Pantry","1 bunch basil@Produce","500g rigatoni@Pantry","100g ricotta salata@Deli","500g fresh ricotta@Dairy","80g icing sugar@Pantry","1/2 tsp ground cinnamon@Pantry","40g candied orange peel@Pantry","8 cannoli shells@Bakery","30g pistachios@Pantry","750ml Nero d'Avola@Bottle shop"]}}});
