Object.assign(MOVIE_MENU_EDITIONS,{"Quick Change (1990)":{"poster":"assets/menu-posters/quick-change-1990.jpg","colour":"#ddab20","servings":4,"tagline":"The bank job was easy. Leaving New York is hard.","cue":"Serve the mains when the cabbie who speaks no English drives them nowhere.","menu":{"s":[{"n":"Clown nose cherry tomatoes","note":"Cherry tomatoes filled with basil and lemon whipped feta.","how":"Cut the tops off 24 cherry tomatoes and scoop out the seeds. Blitz 150g feta with a handful of basil, the zest of 1 lemon and 2 tbsp olive oil until smooth. Pipe into the tomatoes and top each with a small basil leaf. A red nose for every guest.","shop":["24 cherry tomatoes@Produce","150g feta@Dairy","1 bunch basil@Produce","1 lemon@Produce","2 tbsp olive oil@Pantry"]},{"n":"Airport bar peanuts","note":"Butter-roasted peanuts with chilli and smoked paprika.","how":"Melt 20g butter and toss through 300g salted peanuts with 1/2 tsp chilli flakes and 1 tsp smoked paprika. Spread on a tray and roast at 170C for 10 minutes. Cool for 5 minutes and serve in small bowls.","shop":["20g butter@Dairy","300g salted peanuts@Pantry","1/2 tsp chilli flakes@Pantry","1 tsp smoked paprika@Pantry"]}],"m":[{"n":"Bodega sandwiches","note":"Turkey and Swiss kaiser rolls wrapped tight in paper.","how":"Split 4 kaiser rolls, spread with 80g mayonnaise and 1 tbsp mustard. Fill with 400g sliced turkey, 8 slices Swiss cheese, shredded iceberg lettuce and 2 sliced tomatoes, and season with salt and pepper. Wrap each tightly in paper and cut in half.","shop":["4 kaiser rolls@Bakery","80g mayonnaise@Pantry","1 tbsp yellow mustard@Pantry","400g sliced turkey@Deli","8 slices Swiss cheese@Deli","1 iceberg lettuce@Produce","2 tomatoes@Produce"]}],"w":[{"n":"Clown cake","note":"Jam sponge in white buttercream with a piped clown face and cherry nose.","how":"Split a 400g sponge cake and fill with 100g raspberry jam. Beat 200g butter with 400g icing sugar and spread all over the cake. Tint a little leftover buttercream and pipe a clown face on top, then press a maraschino cherry in for the nose.","shop":["400g sponge cake@Bakery","100g raspberry jam@Pantry","200g butter@Dairy","400g icing sugar@Pantry","1 maraschino cherry@Pantry"]}],"d":[{"n":"Airport beer","note":"Cold lager in plastic cups, a toast to leaving New York.","how":"Chill four 375ml bottles of lager in the fridge for at least two hours. Pour into plastic cups and toast to finally getting out of New York, before anything else goes wrong.","shop":["4 bottles lager@Bottle shop"]}],"shopping":["24 cherry tomatoes@Produce","150g feta@Dairy","1 bunch basil@Produce","1 lemon@Produce","2 tbsp olive oil@Pantry","220g butter@Dairy","300g salted peanuts@Pantry","1/2 tsp chilli flakes@Pantry","1 tsp smoked paprika@Pantry","4 kaiser rolls@Bakery","80g mayonnaise@Pantry","1 tbsp yellow mustard@Pantry","400g sliced turkey@Deli","8 slices Swiss cheese@Deli","1 iceberg lettuce@Produce","2 tomatoes@Produce","400g sponge cake@Bakery","100g raspberry jam@Pantry","400g icing sugar@Pantry","1 maraschino cherry@Pantry","4 bottles lager@Bottle shop"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Annie Hall (1977)":{"poster":"assets/menu-posters/annie-hall-1977.jpg","colour":"#8b6946","servings":4,"tagline":"La-di-da. Pass the lobster.","cue":"Serve the mains when the lobsters escape behind the fridge.","menu":{"s":[{"n":"Lobster bites","note":"Lemony lobster salad piled on toasted buttered brioche rounds.","how":"Chop 300g cooked lobster meat and fold with 3 tbsp mayonnaise, the juice of half a lemon, 1 finely diced celery stick and chopped chives. Cut 16 rounds from buttered brioche slices and toast. Pile the lobster on top.","shop":["300g cooked lobster meat@Seafood","3 tbsp mayonnaise@Pantry","1 lemon@Produce","1 celery stick@Produce","1 bunch chives@Produce","6 slices brioche@Bakery","20g butter@Dairy"]},{"n":"Wisconsin cheese plate","note":"Cheddar, colby and squeaky curds with crackers, apple and mustard.","how":"Take 150g aged cheddar, 150g colby cheese and 150g cheese curds out of the fridge an hour ahead. Arrange with 150g crackers, 2 sliced apples and a small pot of grainy mustard.","shop":["150g aged cheddar@Deli","150g colby cheese@Deli","150g cheese curds@Deli","150g crackers@Pantry","2 apples@Produce","2 tbsp wholegrain mustard@Pantry"]}],"m":[{"n":"Pastrami on white with mayo","note":"Steamed pastrami piled on soft white bread with mayo, lettuce and tomato.","how":"Steam 500g sliced pastrami for 10 minutes until glossy. Spread 8 slices soft white bread with 80g mayonnaise, add shredded iceberg lettuce and 2 sliced tomatoes, and pile the pastrami high. Alvy would want rye and mustard, so have them on the side.","shop":["500g pastrami@Deli","8 slices white bread@Bakery","80g mayonnaise@Pantry","1 iceberg lettuce@Produce","2 tomatoes@Produce"]}],"w":[{"n":"New York cheesecake","note":"Tall baked lemon cheesecake on a biscuit base.","how":"Crush 200g digestive biscuits with 80g melted butter and press into a 22cm tin. Beat 900g cream cheese with 220g caster sugar, 200g sour cream, 4 eggs and the zest of 1 lemon. Pour over and bake in a water bath at 150C for 70 minutes. Cool in the oven, then chill overnight.","shop":["200g digestive biscuits@Pantry","80g butter@Dairy","900g cream cheese@Dairy","220g caster sugar@Pantry","200g sour cream@Dairy","4 eggs@Dairy","1 lemon@Produce"]}],"d":[{"n":"Sparkling water","note":"Sparkling water with lemon, cucumber and mint over ice.","how":"Fill a big jug with ice, a sliced lemon, half a sliced cucumber and a handful of mint. Top with 1.5 litres chilled sparkling water and pour into four glasses, the closest thing to his alfalfa sprouts order.","shop":["1.5L sparkling water@Drinks","1 lemon@Produce","1 Lebanese cucumber@Produce","1 bunch mint@Produce","1kg ice@Frozen"]}],"shopping":["300g cooked lobster meat@Seafood","3 lemon@Produce","1 celery stick@Produce","1 bunch chives@Produce","6 slices brioche@Bakery","100g butter@Dairy","150g aged cheddar@Deli","150g colby cheese@Deli","150g cheese curds@Deli","150g crackers@Pantry","2 apples@Produce","2 tbsp wholegrain mustard@Pantry","500g pastrami@Deli","8 slices white bread@Bakery","125g mayonnaise@Pantry","1 iceberg lettuce@Produce","2 tomatoes@Produce","200g digestive biscuits@Pantry","900g cream cheese@Dairy","220g caster sugar@Pantry","200g sour cream@Dairy","4 eggs@Dairy","1.5L sparkling water@Drinks","1 Lebanese cucumber@Produce","1 bunch mint@Produce","1kg ice@Frozen"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Manhattan (1979)":{"poster":"assets/menu-posters/manhattan-1979.jpg","colour":"#353535","servings":4,"tagline":"New York in black and white. Dessert in colour.","cue":"Serve dessert as the Gershwin opening fades.","menu":{"s":[{"n":"Bagels and lox","note":"Toasted bagels, whipped cream cheese, lox, capers and red onion","how":"Whip 250g cream cheese with a splash of milk until light. Split and toast 4 bagels. Spread thickly, then layer with 200g smoked salmon, a few capers, paper-thin red onion and dill sprigs. Cut in half and serve on a board.","shop":["250g cream cheese@Dairy","4 bagels@Bakery","200g smoked salmon@Seafood","1 jar capers@Pantry","1 red onion@Produce","1 bunch dill@Produce"]},{"n":"Planetarium popcorn","note":"Dark smoky popcorn with flaky salt, like stars in a night sky","how":"Heat 2 tbsp coconut oil in a large pot with 3 kernels. When they pop, add 120g kernels, cover and shake until the popping slows. Toss with 50g melted butter, flaky salt and 1 tsp smoked paprika.","shop":["2 tbsp coconut oil@Pantry","120g popcorn kernels@Pantry","50g butter@Dairy","1 jar smoked paprika@Pantry"]}],"m":[{"n":"Chinese takeaway in bed","note":"Kung pao chicken and rice, eaten from the cartons","how":"Marinate 700g diced chicken thigh in 2 tbsp soy and 1 tbsp cornflour. Fry hot with 10 dried chillies and 1 tsp Sichuan pepper. Add sauce of 2 tbsp black vinegar, 2 tbsp soy, 1 tbsp sugar and 2 tbsp Shaoxing, then 80g peanuts and spring onion. Serve with 300g jasmine rice.","shop":["700g chicken thighs@Meat","1 bottle soy sauce@Pantry","1 box cornflour@Pantry","1 packet dried chillies@Pantry","1 jar Sichuan pepper@Pantry","1 bottle black vinegar@Pantry","1 bottle Shaoxing wine@Pantry","80g roasted peanuts@Pantry","1 bunch spring onions@Produce","300g jasmine rice@Pantry"]}],"w":[{"n":"Black and white cookies","note":"Soft vanilla cookies iced half vanilla, half chocolate","how":"Beat 115g butter with 150g sugar, 1 egg and 80g sour cream, then fold in 250g flour and 1 tsp baking powder. Scoop 8 large mounds and bake at 180C for 12 minutes. Ice the flat sides, half with vanilla icing and half with icing mixed with cocoa.","shop":["115g butter@Dairy","150g caster sugar@Pantry","1 egg@Dairy","80g sour cream@Dairy","250g plain flour@Pantry","1 tin baking powder@Pantry","300g icing sugar@Pantry","1 tin cocoa@Pantry"]}],"d":[{"n":"Manhattan cocktail","note":"Rye, sweet vermouth and bitters, stirred cold, with a cherry","how":"For each drink, stir 60ml rye, 30ml sweet vermouth and 2 dashes aromatic bitters over plenty of ice for 30 seconds. Strain into a chilled coupe and drop in a cocktail cherry. Makes four, so make them one or two at a time.","shop":["240ml rye whiskey@Bottle shop","120ml sweet vermouth@Bottle shop","1 bottle aromatic bitters@Bottle shop","1 jar cocktail cherries@Pantry"]}],"shopping":["250g cream cheese@Dairy","4 bagels@Bakery","200g smoked salmon@Seafood","1 jar capers@Pantry","1 red onion@Produce","1 bunch dill@Produce","2 tbsp coconut oil@Pantry","120g popcorn kernels@Pantry","165g butter@Dairy","1 jar smoked paprika@Pantry","700g chicken thighs@Meat","1 bottle soy sauce@Pantry","1 box cornflour@Pantry","1 packet dried chillies@Pantry","1 jar Sichuan pepper@Pantry","1 bottle black vinegar@Pantry","1 bottle Shaoxing wine@Pantry","80g roasted peanuts@Pantry","1 bunch spring onions@Produce","300g jasmine rice@Pantry","150g caster sugar@Pantry","1 egg@Dairy","80g sour cream@Dairy","250g plain flour@Pantry","1 tin baking powder@Pantry","300g icing sugar@Pantry","1 tin cocoa@Pantry","240ml rye whiskey@Bottle shop","120ml sweet vermouth@Bottle shop","1 bottle aromatic bitters@Bottle shop","1 jar cocktail cherries@Pantry"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Men in Black II (2002)":{"poster":"assets/menu-posters/men-in-black-ii-2002.jpg","colour":"#235c97","servings":4,"tagline":"Back in black. Still hungry.","cue":"Serve dinner when Frank the pug sings in the car.","menu":{"s":[{"n":"Ben's Famous pizza bites","note":"Mini pepperoni pizzas on rounds of dough, hot from the oven","how":"Roll out 500g pizza dough and cut into 16 rounds. Spread each with a spoon of pizza sauce, then add grated mozzarella and a slice of pepperoni. Bake on a hot tray at 230C for 8 minutes until the bases are crisp and the cheese bubbles.","shop":["500g pizza dough@Bakery","1 jar pizza sauce@Pantry","150g mozzarella@Dairy","100g pepperoni@Deli"]},{"n":"Pug cookies","note":"Brown butter cookies with little pug faces in chocolate","how":"Brown 125g butter and cool. Beat with 150g brown sugar and 1 egg, then mix in 200g flour and half a tsp bicarb. Roll into 16 balls and bake at 180C for 10 minutes. Cool, then pipe pug faces on with 50g melted dark chocolate.","shop":["125g butter@Dairy","150g brown sugar@Pantry","1 egg@Dairy","200g plain flour@Pantry","50g dark chocolate@Pantry"]}],"m":[{"n":"Ben's Famous pizza","note":"Thin crust pizza with crushed tomato, mozzarella and sausage","how":"Stretch 2 balls of cold-fermented dough, 500g in total, thin. Spread with 200g crushed tomato seasoned with salt. Top with 250g low-moisture mozzarella and 3 Italian sausages, skins off, crumbled. Bake on a steel at max heat for 7 minutes.","shop":["500g pizza dough@Bakery","200g crushed tomatoes@Pantry","250g low-moisture mozzarella@Dairy","3 Italian sausages@Meat"]}],"w":[{"n":"Neuralyser cake pops","note":"Cake pops dipped in white chocolate and brushed silver","how":"Crumble a 500g butter cake and mix with 100g cream cheese icing until it holds together. Roll into 16 balls, push in sticks and chill an hour. Dip in 300g melted white chocolate, set, then brush with silver lustre dust.","shop":["1 butter cake@Bakery","100g cream cheese@Dairy","50g icing sugar@Pantry","300g white chocolate@Pantry","1 jar silver lustre dust@Pantry"]}],"d":[{"n":"Sugar water","note":"Very sweet lemonade, the alien drink of choice","how":"Make a syrup of 150g caster sugar dissolved in 150ml hot water and cool. Stir with the juice of 4 lemons and 1L cold water. Serve over ice in four glasses with a lemon slice each. Taste and add more syrup if needed.","shop":["150g caster sugar@Pantry","5 lemons@Produce"]}],"shopping":["1kg pizza dough@Bakery","1 jar pizza sauce@Pantry","150g mozzarella@Dairy","100g pepperoni@Deli","125g butter@Dairy","150g brown sugar@Pantry","1 egg@Dairy","200g plain flour@Pantry","50g dark chocolate@Pantry","200g crushed tomatoes@Pantry","250g low-moisture mozzarella@Dairy","3 Italian sausages@Meat","1 butter cake@Bakery","100g cream cheese@Dairy","50g icing sugar@Pantry","300g white chocolate@Pantry","1 jar silver lustre dust@Pantry","150g caster sugar@Pantry","5 lemons@Produce"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Big Trouble in Little China (1986)":{"poster":"assets/menu-posters/big-trouble-in-little-china-1986.jpg","colour":"#9b2925","servings":4,"tagline":"Something big is cooking in Chinatown.","cue":"Serve the noodles when Jack drives the Pork-Chop Express into Chinatown.","menu":{"s":[{"n":"Pork and chive dumplings","note":"Crisp-bottomed pork and chive dumplings with vinegar and chilli oil","how":"Mix 400g pork mince with a chopped bunch of garlic chives, 1 tbsp grated ginger, 1 tbsp soy, 1 tbsp Shaoxing and 1 tsp sesame oil. Pleat into 30 gyoza wrappers. Fry until the bottoms crisp, add water and steam with the lid on for 4 minutes.","shop":["400g pork mince@Meat","1 bunch garlic chives@Produce","1 knob ginger@Produce","1 bottle soy sauce@Pantry","1 bottle Shaoxing wine@Pantry","1 bottle sesame oil@Pantry","30 gyoza wrappers@Frozen","1 bottle black vinegar@Pantry","1 jar chilli oil@Pantry"]},{"n":"Salt and pepper squid","note":"Crisp squid tossed with fried garlic, chilli and spring onion","how":"Score 500g squid tubes and cut into strips. Toss in 100g potato starch with salt, white pepper and a pinch of five spice. Fry at 190C for 90 seconds. Wok-toss with fried garlic, 2 sliced chillies and spring onion.","shop":["500g squid tubes@Seafood","100g potato starch@Pantry","1 jar white pepper@Pantry","1 jar five spice@Pantry","2 red chillies@Produce","3 garlic cloves@Produce","1 bunch spring onions@Produce","1L vegetable oil@Pantry"]}],"m":[{"n":"Pork-Chop Express ribs","note":"Sticky charred five spice ribs, glazed in hoisin and honey","how":"Rub 1.5kg pork ribs with 4 tbsp hoisin, 2 tbsp honey, 2 tbsp soy, 1 tsp five spice, 1 cube red fermented bean curd and 3 garlic cloves. Marinate overnight. Roast covered at 160C for 90 minutes, then uncover, glaze and blast at 220C until sticky.","shop":["1.5kg pork ribs@Meat","1 jar hoisin sauce@Pantry","1 jar honey@Pantry","1 bottle soy sauce@Pantry","1 jar five spice@Pantry","1 jar red fermented bean curd@Pantry","3 garlic cloves@Produce"]}],"w":[{"n":"Fortune cookies","note":"Crisp vanilla fortune cookies, each with a paper fortune inside","how":"Whisk 3 egg whites with 100g sugar, then stir in 60g flour, 40g melted butter and a little vanilla. Spread 8cm circles on a lined tray and bake at 180C for 6 minutes. Working fast, fold each around a paper fortune while hot.","shop":["3 eggs@Dairy","100g caster sugar@Pantry","60g plain flour@Pantry","40g butter@Dairy","1 bottle vanilla extract@Pantry"]}],"d":[{"n":"Plum wine","note":"Cold plum wine over a big ice cube with soda","how":"Chill a 750ml bottle of plum wine well. Put a large ice cube in each of four short glasses, pour about 120ml plum wine over each and top with a splash of soda water. Add a plum from the bottle if there are any.","shop":["750ml plum wine@Bottle shop","1 bottle soda water@Drinks"]}],"shopping":["400g pork mince@Meat","1 bunch garlic chives@Produce","1 knob ginger@Produce","1 bottle soy sauce@Pantry","1 bottle Shaoxing wine@Pantry","1 bottle sesame oil@Pantry","30 gyoza wrappers@Frozen","1 bottle black vinegar@Pantry","1 jar chilli oil@Pantry","500g squid tubes@Seafood","100g potato starch@Pantry","1 jar white pepper@Pantry","1 jar five spice@Pantry","2 red chillies@Produce","6 garlic cloves@Produce","1 bunch spring onions@Produce","1L vegetable oil@Pantry","1.5kg pork ribs@Meat","1 jar hoisin sauce@Pantry","1 jar honey@Pantry","1 jar red fermented bean curd@Pantry","3 eggs@Dairy","100g caster sugar@Pantry","60g plain flour@Pantry","40g butter@Dairy","1 bottle vanilla extract@Pantry","750ml plum wine@Bottle shop","1 bottle soda water@Drinks"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"The Last Dragon (1985)":{"poster":"assets/menu-posters/the-last-dragon-1985.jpg","colour":"#a57825","servings":4,"tagline":"Find the glow. Then find the dumplings.","cue":"Serve dinner when Leroy eats popcorn with chopsticks at the cinema.","menu":{"s":[{"n":"Chopstick popcorn","note":"Buttery furikake popcorn, eaten with chopsticks","how":"Heat 2 tbsp oil in a large pot with 3 kernels. When they pop, add 120g kernels, cover and shake until the popping slows. Toss with 50g melted butter, 3 tbsp furikake and a pinch of sugar. Hand out chopsticks and see who gives up first.","shop":["120g popcorn kernels@Pantry","2 tbsp vegetable oil@Pantry","50g butter@Dairy","1 jar furikake@Pantry","1 bag caster sugar@Pantry"]},{"n":"Harlem spring rolls","note":"Crisp vegetable spring rolls with sweet chilli","how":"Stir-fry 2 cups shredded cabbage, 1 grated carrot and 100g sliced shiitake. Add 50g soaked glass noodles, soy and white pepper, then cool. Roll tightly in 16 spring roll wrappers, sealing with water, and fry at 180C until golden. Serve with sweet chilli.","shop":["0.25 cabbage@Produce","1 carrot@Produce","100g shiitake mushrooms@Produce","50g glass noodles@Pantry","1 bottle soy sauce@Pantry","16 spring roll wrappers@Frozen","1 bottle sweet chilli sauce@Pantry","1L vegetable oil@Pantry"]}],"m":[{"n":"General Tso's chicken","note":"Double-fried chicken in a sweet, sticky chilli sauce with rice","how":"Toss 800g diced chicken thighs in 100g potato starch and fry twice at 180C. Fry 8 dried chillies, 3 garlic cloves and ginger, then add 3 tbsp soy, 2 tbsp black vinegar, 3 tbsp sugar and 125ml stock. Toss the chicken through. Serve with 300g jasmine rice.","shop":["800g chicken thighs@Meat","100g potato starch@Pantry","1 packet dried chillies@Pantry","3 garlic cloves@Produce","1 knob ginger@Produce","1 bottle soy sauce@Pantry","1 bottle black vinegar@Pantry","125ml chicken stock@Pantry","300g jasmine rice@Pantry","1L vegetable oil@Pantry"]}],"w":[{"n":"Glowing mango mochi","note":"Soft mochi wrapped around fresh mango and cream","how":"Mix 150g glutinous rice flour, 50g sugar and 200ml coconut milk, then steam for 20 minutes, stirring halfway. Dust a board with cornflour and divide into 8. Wrap each around a cube of mango and a spoon of whipped cream. Chill 30 minutes.","shop":["150g glutinous rice flour@Pantry","50g caster sugar@Pantry","200ml coconut milk@Pantry","1 box cornflour@Pantry","1 mango@Produce","150ml thickened cream@Dairy"]}],"d":[{"n":"Chrysanthemum iced tea","note":"Lightly sweet chrysanthemum tea, chilled over ice","how":"Steep 15g dried chrysanthemum flowers in 1L just-boiled water with 50g rock sugar for 5 minutes. Strain, cool and chill well in the fridge. Pour over ice in four tall glasses and float a flower or two on top.","shop":["15g dried chrysanthemum@Pantry","50g rock sugar@Pantry"]}],"shopping":["120g popcorn kernels@Pantry","50g butter@Dairy","1 jar furikake@Pantry","0.25 cabbage@Produce","1 carrot@Produce","100g shiitake mushrooms@Produce","50g glass noodles@Pantry","1 bottle soy sauce@Pantry","16 spring roll wrappers@Frozen","1 bottle sweet chilli sauce@Pantry","2.03L vegetable oil@Pantry","800g chicken thighs@Meat","100g potato starch@Pantry","1 packet dried chillies@Pantry","3 garlic cloves@Produce","1 knob ginger@Produce","1 bottle black vinegar@Pantry","125ml chicken stock@Pantry","300g jasmine rice@Pantry","150g glutinous rice flour@Pantry","50g caster sugar@Pantry","200ml coconut milk@Pantry","1 box cornflour@Pantry","1 mango@Produce","150ml thickened cream@Dairy","15g dried chrysanthemum@Pantry","50g rock sugar@Pantry"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Crocodile Dundee (1986)":{"poster":"assets/menu-posters/crocodile-dundee-1986.jpg","colour":"#88712d","servings":4,"tagline":"That's not a snack. This is a snack.","cue":"Pour a beer when Mick first sees a bidet in the hotel.","menu":{"s":[{"n":"Garlic prawn skewers","note":"Grilled garlic and chilli prawns with lemon myrtle butter","how":"Toss 600g peeled king prawns with 3 crushed garlic cloves, 1 chopped chilli, lemon zest and 2 tbsp oil. Thread onto skewers and grill hot for 90 seconds a side. Brush with 50g butter melted with 1 tsp lemon myrtle and serve with lemon.","shop":["600g king prawns@Seafood","3 garlic cloves@Produce","1 red chilli@Produce","2 lemons@Produce","50g butter@Dairy","1 jar lemon myrtle@Pantry"]},{"n":"Walkabout Creek party pies","note":"Little meat pies with puff lids and tomato sauce","how":"Cook 500g beef mince with 1 onion, 2 tbsp Worcestershire, 2 tbsp tomato sauce and 250ml stock, thicken and cool. Line patty tins with 2 sheets shortcrust, fill, top with 2 sheets puff and bake at 200C for 20 minutes.","shop":["500g beef mince@Meat","1 brown onion@Produce","1 bottle Worcestershire sauce@Pantry","1 bottle tomato sauce@Pantry","250ml beef stock@Pantry","2 sheets shortcrust pastry@Frozen","2 sheets puff pastry@Frozen"]}],"m":[{"n":"Barbecued barra","note":"Crisp-skinned barramundi with lemon myrtle garlic butter","how":"Score the skin of 4 barramundi fillets and pat very dry. Grill skin down over high heat until crisp, about 4 minutes, then flip for 1 minute. Melt 80g butter with 2 garlic cloves and 1 tsp lemon myrtle and spoon over.","shop":["4 barramundi fillets@Seafood","80g butter@Dairy","2 garlic cloves@Produce","1 jar lemon myrtle@Pantry","2 lemons@Produce"]}],"w":[{"n":"Lamingtons","note":"Sponge squares in chocolate icing rolled in coconut","how":"Cut a 500g butter sponge into 16 squares. Whisk 400g icing sugar, 40g cocoa, 20g melted butter and 150ml milk into a thin icing. Dip each square, drain and roll in 200g desiccated coconut. Set on a rack for an hour.","shop":["1 sponge cake@Bakery","400g icing sugar@Pantry","40g cocoa@Pantry","20g butter@Dairy","150ml full cream milk@Dairy","200g desiccated coconut@Pantry"]}],"d":[{"n":"Ice cold tinnies","note":"Aussie lager in cans, iced in an esky","how":"Fill an esky with a bag of ice and some cold water so the cans sit in it. Bury 12 cans of lager for at least an hour. Hand them out in stubby holders, which are not optional.","shop":["12 375ml cans Aussie lager@Bottle shop","1 bag ice@Frozen"]}],"shopping":["600g king prawns@Seafood","5 garlic cloves@Produce","1 red chilli@Produce","4 lemons@Produce","150g butter@Dairy","1 jar lemon myrtle@Pantry","500g beef mince@Meat","1 brown onion@Produce","1 bottle Worcestershire sauce@Pantry","1 bottle tomato sauce@Pantry","250ml beef stock@Pantry","2 sheets shortcrust pastry@Frozen","2 sheets puff pastry@Frozen","4 barramundi fillets@Seafood","1 sponge cake@Bakery","400g icing sugar@Pantry","40g cocoa@Pantry","150ml full cream milk@Dairy","200g desiccated coconut@Pantry","12 375ml cans Aussie lager@Bottle shop","1 bag ice@Frozen"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Crocodile Dundee II (1988)":{"poster":"assets/menu-posters/crocodile-dundee-ii-1988.jpg","colour":"#8e773b","servings":4,"tagline":"From New York back to the bush.","cue":"Serve the mains when Mick sets up his bush ambush.","menu":{"s":[{"n":"Bush damper with golden syrup","note":"Warm damper with butter and golden syrup","how":"Rub 60g butter into 450g self-raising flour and a pinch of salt. Mix in about 300ml milk to a soft dough, shape into a round and score a cross. Bake at 200C for 30 minutes until it sounds hollow. Serve warm with butter and golden syrup.","shop":["100g butter@Dairy","450g self-raising flour@Pantry","300ml full cream milk@Dairy","1 tin golden syrup@Pantry"]},{"n":"Snags on sticks","note":"Thick sausages rolled in bread with onions and sauce","how":"Grill 8 thick beef sausages slowly over medium heat for 15 minutes, turning often. Fry 2 sliced onions until soft and golden. Wrap each sausage in a slice of white bread with onions and a squeeze of tomato sauce.","shop":["8 thick beef sausages@Meat","8 slices white bread@Bakery","2 brown onions@Produce","1 bottle tomato sauce@Pantry"]}],"m":[{"n":"Campfire barra","note":"Whole barra with lemon, ginger and coriander cooked in foil","how":"Stuff a 1.5kg whole barramundi with lemon slices, a sliced knob of ginger and a bunch of coriander. Dot with 50g butter and wrap well in foil. Cook over hot coals or a hot grill for 20 minutes, turning once.","shop":["1.5kg whole barramundi@Seafood","2 lemons@Produce","1 knob ginger@Produce","1 bunch coriander@Produce","50g butter@Dairy"]}],"w":[{"n":"Pavlova","note":"Crisp-shelled pavlova with cream, passionfruit and mango","how":"Whip 4 whites to soft peaks, add 220g caster sugar gradually until glossy, then fold in 1 tsp cornflour and 1 tsp vinegar. Bake at 120C for 90 minutes and cool in the oven. Top with 300ml whipped cream, 4 passionfruit and a sliced mango.","shop":["4 eggs@Dairy","220g caster sugar@Pantry","1 box cornflour@Pantry","1 bottle white vinegar@Pantry","300ml thickened cream@Dairy","4 passionfruit@Produce","1 mango@Produce"]}],"d":[{"n":"Cold tinnies","note":"Aussie lager in cans, straight from the esky","how":"Fill an esky with a bag of ice and a little cold water. Bury 12 cans of lager for at least an hour before anyone sits down. Hand them out one at a time, cold enough to hurt your hand.","shop":["12 375ml cans Aussie lager@Bottle shop","1 bag ice@Frozen"]}],"shopping":["150g butter@Dairy","450g self-raising flour@Pantry","300ml full cream milk@Dairy","1 tin golden syrup@Pantry","8 thick beef sausages@Meat","8 slices white bread@Bakery","2 brown onions@Produce","1 bottle tomato sauce@Pantry","1.5kg whole barramundi@Seafood","2 lemons@Produce","1 knob ginger@Produce","1 bunch coriander@Produce","4 eggs@Dairy","220g caster sugar@Pantry","1 box cornflour@Pantry","1 bottle white vinegar@Pantry","300ml thickened cream@Dairy","4 passionfruit@Produce","1 mango@Produce","12 375ml cans Aussie lager@Bottle shop","1 bag ice@Frozen"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Annie (1982)":{"poster":"assets/menu-posters/annie-1982.jpg","colour":"#b13131","servings":4,"tagline":"The sun'll come out. So will dessert.","cue":"Serve the snacks when Annie arrives at the Warbucks mansion.","menu":{"s":[{"n":"Warbucks mansion canapés","note":"Chicken and mushroom vol-au-vents with prosciutto asparagus","how":"Bake 16 vol-au-vent cases until crisp. Fry 250g diced chicken thigh and 150g mushrooms, add 150ml cream and thyme and reduce. Fill the cases. Blanch 2 bunches asparagus and wrap each spear in half a slice of prosciutto.","shop":["16 vol-au-vent cases@Frozen","250g chicken thighs@Meat","150g mushrooms@Produce","150ml thickened cream@Dairy","1 bunch thyme@Produce","2 bunches asparagus@Produce","100g prosciutto@Deli"]},{"n":"Radio City popcorn","note":"Buttery salted popcorn in paper cones","how":"Heat 2 tbsp coconut oil with 3 kernels, and when they pop add 120g kernels, cover and shake until the popping slows. Toss with 50g melted butter and fine salt while hot. Roll paper into cones and fill them up.","shop":["2 tbsp coconut oil@Pantry","120g popcorn kernels@Pantry","50g butter@Dairy","1 box fine salt@Pantry"]}],"m":[{"n":"Warbucks roast chicken","note":"Tarragon butter roast chicken with gravy, potatoes and peas","how":"Dry-brine a 1.8kg chicken overnight. Push 60g butter mixed with chopped tarragon under the skin. Roast at 220C for 20 minutes, then 180C until the thigh hits 72C, with 1kg potatoes. Make gravy with 250ml stock. Serve with buttered peas.","shop":["1.8kg whole chicken@Meat","80g butter@Dairy","1 bunch tarragon@Produce","1kg potatoes@Produce","250ml chicken stock@Pantry","300g frozen peas@Frozen"]}],"w":[{"n":"Mansion sundaes","note":"Hot fudge sundaes with cream, almonds and a cherry","how":"Melt 150g dark chocolate with 150ml cream and 2 tbsp golden syrup into a hot fudge. Scoop vanilla ice cream into four tall glasses, pour over the fudge and top with whipped cream, toasted flaked almonds and a cherry.","shop":["150g dark chocolate@Pantry","300ml thickened cream@Dairy","1 tin golden syrup@Pantry","1L vanilla ice cream@Frozen","50g flaked almonds@Pantry","1 jar maraschino cherries@Pantry"]}],"d":[{"n":"Pink lemonade","note":"Sweet lemonade turned pink with raspberry cordial","how":"Dissolve 150g sugar in 150ml hot water and cool. Mix with the juice of 4 lemons, 1L cold water and 60ml raspberry cordial until pink. Serve over ice in four glasses with a lemon slice each.","shop":["150g caster sugar@Pantry","5 lemons@Produce","1 bottle raspberry cordial@Drinks"]}],"shopping":["16 vol-au-vent cases@Frozen","250g chicken thighs@Meat","150g mushrooms@Produce","450ml thickened cream@Dairy","1 bunch thyme@Produce","2 bunches asparagus@Produce","100g prosciutto@Deli","2 tbsp coconut oil@Pantry","120g popcorn kernels@Pantry","130g butter@Dairy","1 box fine salt@Pantry","1.8kg whole chicken@Meat","1 bunch tarragon@Produce","1kg potatoes@Produce","250ml chicken stock@Pantry","300g frozen peas@Frozen","150g dark chocolate@Pantry","1 tin golden syrup@Pantry","1L vanilla ice cream@Frozen","50g flaked almonds@Pantry","1 jar maraschino cherries@Pantry","150g caster sugar@Pantry","5 lemons@Produce","1 bottle raspberry cordial@Drinks"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Beverly Hills Cop III (1994)":{"poster":"assets/menu-posters/beverly-hills-cop-iii-1994.jpg","colour":"#285b9c","servings":4,"tagline":"The theme park ride from hell.","cue":"Serve the snacks when the Spider ride gets stuck.","menu":{"s":[{"n":"Wonder World popcorn","note":"Crunchy baked caramel popcorn, like the stuff at the theme park","how":"Pop 120g kernels. Boil 150g brown sugar, 80g butter and 3 tbsp golden syrup for 4 minutes, then stir in half a tsp bicarb. Pour over the popcorn, toss and bake at 120C for 45 minutes, stirring every 15. Cool and break up.","shop":["120g popcorn kernels@Pantry","150g brown sugar@Pantry","80g butter@Dairy","1 tin golden syrup@Pantry","1 box bicarb soda@Pantry"]},{"n":"Midway corn dogs","note":"Cornmeal-battered franks fried on sticks, with mustard","how":"Whisk 150g cornmeal, 100g flour, 2 tbsp sugar, 2 tsp baking powder, 1 egg and 250ml buttermilk. Pat 8 franks dry and push onto sticks. Dip in batter and fry at 180C for 4 minutes until deep gold. Serve with mustard.","shop":["150g fine cornmeal@Pantry","100g plain flour@Pantry","1 tin baking powder@Pantry","1 egg@Dairy","250ml buttermilk@Dairy","8 hot dog franks@Meat","1 bottle yellow mustard@Pantry","1L vegetable oil@Pantry"]}],"m":[{"n":"Theme park turkey legs","note":"Brined smoky turkey drumsticks, roasted until falling apart","how":"Dissolve 80g salt and 80g brown sugar in 2L water with 1 tbsp smoked paprika. Brine 4 turkey drumsticks overnight. Pat dry, rub with more paprika and roast at 150C for 2 hours until the meat pulls easily from the bone.","shop":["80g sea salt@Pantry","80g brown sugar@Pantry","1 jar smoked paprika@Pantry","4 turkey drumsticks@Meat"]}],"w":[{"n":"Fairy floss and toffee apples","note":"Glossy red toffee apples with fairy floss on the side","how":"Push sticks into 4 apples. Boil 400g sugar, 125ml water and 1 tsp vinegar to 150C, then add a few drops of red colouring. Dip and twirl the apples, then set on baking paper. Serve with a bag of fairy floss.","shop":["4 apples@Produce","400g caster sugar@Pantry","1 bottle white vinegar@Pantry","1 bottle red food colouring@Pantry","1 bag fairy floss@Pantry"]}],"d":[{"n":"Blue slushie","note":"Bright blue raspberry slushies that turn your tongue blue","how":"Blitz 200ml blue raspberry cordial with 600ml cold water and 4 cups of ice in a blender until it is smooth and slushy. Pour into four cups and serve straight away with spoon straws before it melts.","shop":["1 bottle blue raspberry cordial@Drinks","1 bag ice@Frozen"]}],"shopping":["120g popcorn kernels@Pantry","230g brown sugar@Pantry","80g butter@Dairy","1 tin golden syrup@Pantry","1 box bicarb soda@Pantry","150g fine cornmeal@Pantry","100g plain flour@Pantry","1 tin baking powder@Pantry","1 egg@Dairy","250ml buttermilk@Dairy","8 hot dog franks@Meat","1 bottle yellow mustard@Pantry","1L vegetable oil@Pantry","80g sea salt@Pantry","1 jar smoked paprika@Pantry","4 turkey drumsticks@Meat","4 apples@Produce","400g caster sugar@Pantry","1 bottle white vinegar@Pantry","1 bottle red food colouring@Pantry","1 bag fairy floss@Pantry","1 bottle blue raspberry cordial@Drinks","1 bag ice@Frozen"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Once Upon a Time in America (1984)":{"poster":"assets/menu-posters/once-upon-a-time-in-america-1984.jpg","colour":"#6b4326","servings":4,"tagline":"Fifty years of friendship, one very long dinner.","cue":"Bring the charlotte russe out when young Patsy sits on the stairs with his.","menu":{"s":[{"n":"Delancey Street knishes","note":"Buttery potato and slow-cooked onion baked in golden puff pastry.","how":"Boil 500g peeled potatoes 15 minutes, drain and mash. Cook 1 finely diced brown onion in 30g butter over low heat for 15 minutes until golden, then mix into the mash with salt and white pepper. Cut 2 sheets puff pastry into 4 squares each, fill, fold into parcels and brush with 1 beaten egg. Bake at 200C for 25 minutes. Serve with 40g hot English mustard.","shop":["500g potatoes@Produce","1 brown onion@Produce","30g butter@Dairy","2 sheets puff pastry@Frozen","1 egg@Dairy","40g hot English mustard@Pantry"]},{"n":"Bagel crisps with schmear","note":"Thin baked bagel crisps with chive cream cheese and smoked salmon.","how":"Slice 3 day-old bagels into thin rounds, brush with 2 tbsp olive oil and bake at 180C for 12 minutes until crisp. Beat 250g cream cheese with 2 tbsp chopped chives and the zest of 1 lemon. Serve the crisps with the schmear and 150g smoked salmon on the side.","shop":["3 bagels@Bakery","2 tbsp olive oil@Pantry","250g cream cheese@Dairy","1 bunch chives@Produce","1 lemon@Produce","150g smoked salmon@Seafood"]}],"m":[{"n":"Fat Moe's back room brisket","note":"Slow-braised brisket on sweet onions, sliced thick with rich gravy.","how":"Season a 1.5kg beef brisket with salt and pepper and sear hard on all sides. Slice 3 brown onions into a roasting dish, sit the brisket on top, and pour over 500ml beef stock whisked with 2 tbsp tomato paste and 2 tsp sweet paprika. Cover and braise at 150C for 4 hours. Rest 20 minutes, slice against the grain, and boil the juices for 10 minutes to make gravy.","shop":["1.5kg beef brisket@Meat","3 brown onions@Produce","500ml beef stock@Pantry","2 tbsp tomato paste@Pantry","2 tsp sweet paprika@Pantry"]}],"w":[{"n":"Patsy's charlotte russe","note":"Sponge cups piped high with vanilla cream and a cherry.","how":"Cut 8 rounds from a 300g sponge cake to fit the bottom of 8 paper cups. Whip 300ml thickened cream with 100g mascarpone, 2 tbsp icing sugar and 1 tsp vanilla extract to firm peaks. Pipe high over the sponge in a tall swirl and top each with a maraschino cherry. Chill 30 minutes before serving.","shop":["300g sponge cake@Bakery","300ml thickened cream@Dairy","100g mascarpone@Dairy","2 tbsp icing sugar@Pantry","1 tsp vanilla extract@Pantry","8 maraschino cherries@Pantry"]}],"d":[{"n":"Bootleg whisky","note":"Rye whiskey poured neat into china coffee cups.","how":"Pour 45ml rye whiskey, about 180ml in total, into each of four china coffee cups, the way it was served when it was illegal. Put a small jug of cold water on the table so everyone can add a splash.","shop":["180ml rye whiskey@Bottle shop"]}],"shopping":["500g potatoes@Produce","1 brown onion@Produce","30g butter@Dairy","2 sheets puff pastry@Frozen","1 egg@Dairy","40g hot English mustard@Pantry","3 bagels@Bakery","2 tbsp olive oil@Pantry","250g cream cheese@Dairy","1 bunch chives@Produce","1 lemon@Produce","150g smoked salmon@Seafood","1.5kg beef brisket@Meat","3 brown onions@Produce","500ml beef stock@Pantry","2 tbsp tomato paste@Pantry","2 tsp sweet paprika@Pantry","300g sponge cake@Bakery","300ml thickened cream@Dairy","100g mascarpone@Dairy","2 tbsp icing sugar@Pantry","1 tsp vanilla extract@Pantry","8 maraschino cherries@Pantry","180ml rye whiskey@Bottle shop"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"The Pope of Greenwich Village (1984)":{"poster":"assets/menu-posters/the-pope-of-greenwich-village-1984.jpg","colour":"#72252a","servings":4,"tagline":"Big plans. Small cousins. Bad luck.","cue":"Pour the wine when Paulie gets caught skimming and loses them both their jobs.","menu":{"s":[{"n":"Clams oreganata","note":"Clams under golden garlic, oregano and parmesan crumbs.","how":"Steam 1kg clams with a splash of water in a covered pan until they open, about 4 minutes, and discard any closed ones. Remove the top shells. Mix 60g breadcrumbs, 2 crushed garlic cloves, 1 tsp dried oregano, 30g grated parmesan and 3 tbsp olive oil. Top each clam and grill for 3 minutes until golden.","shop":["1kg clams@Seafood","60g breadcrumbs@Pantry","2 garlic cloves@Produce","1 tsp dried oregano@Pantry","30g parmesan@Dairy","3 tbsp olive oil@Pantry"]},{"n":"Waiter's antipasto","note":"Prosciutto on rockmelon, with bocconcini dressed in bright basil oil.","how":"Cut 1 rockmelon into 12 skinless wedges and drape with 120g prosciutto. Blitz a bunch of basil with 80ml olive oil and a pinch of salt. Drain 220g bocconcini, dress with the basil oil and cracked pepper and serve beside the melon.","shop":["1 rockmelon@Produce","120g prosciutto@Deli","1 bunch basil@Produce","80ml olive oil@Pantry","220g bocconcini@Deli"]}],"m":[{"n":"Veal marsala","note":"Seared veal escalopes in a glossy mushroom and marsala sauce.","how":"Dust 600g veal escalopes in seasoned flour and sear in butter and oil for 1 minute a side, then set aside. Brown 250g sliced button mushrooms in the same pan, add 150ml marsala and 150ml beef stock and reduce by half. Whisk in 40g cold butter, return the veal and warm through for a minute. Serve with crusty bread.","shop":["600g veal escalopes@Meat","2 tbsp plain flour@Pantry","60g butter@Dairy","250g button mushrooms@Produce","150ml marsala@Bottle shop","150ml beef stock@Pantry"]}],"w":[{"n":"Zabaglione","note":"Warm whisked marsala custard spooned over fresh strawberries.","how":"Whisk 4 egg yolks, 60g caster sugar and 80ml marsala in a heatproof bowl over simmering water for 6 to 8 minutes until thick, pale and tripled in volume. Spoon warm over 250g halved strawberries in four glasses and serve straight away.","shop":["4 eggs@Dairy","60g caster sugar@Pantry","80ml marsala@Bottle shop","250g strawberries@Produce"]}],"d":[{"n":"Chianti","note":"Chianti Classico decanted and poured with a flourish.","how":"Decant one 750ml bottle of Chianti Classico 30 minutes before dinner and keep it at about 16C. Pour into four glasses, about 180ml each, the way Charlie would at the restaurant.","shop":["750ml Chianti Classico@Bottle shop"]}],"shopping":["1kg clams@Seafood","60g breadcrumbs@Pantry","2 garlic cloves@Produce","1 tsp dried oregano@Pantry","30g parmesan@Dairy","1 rockmelon@Produce","120g prosciutto@Deli","1 bunch basil@Produce","125ml olive oil@Pantry","220g bocconcini@Deli","600g veal escalopes@Meat","2 tbsp plain flour@Pantry","60g butter@Dairy","250g button mushrooms@Produce","230ml marsala@Bottle shop","150ml beef stock@Pantry","4 eggs@Dairy","60g caster sugar@Pantry","250g strawberries@Produce","750ml Chianti Classico@Bottle shop"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Saturday Night Fever (1977)":{"poster":"assets/menu-posters/saturday-night-fever-1977.jpg","colour":"#c52a68","servings":4,"tagline":"Strut in. Fold your slice. Strut out.","cue":"Serve the slices during the opening walk down 86th Street.","menu":{"s":[{"n":"Bay Ridge garlic knots","note":"Pizza dough knots tossed hot in garlic butter and parmesan.","how":"Cut 500g pizza dough into 12 strips, tie each into a loose knot and leave to prove 30 minutes on a lined tray. Bake at 230C for 12 minutes until golden. Melt 50g butter with 3 crushed garlic cloves and toss the knots in it straight from the oven, then shower with 30g grated parmesan.","shop":["500g pizza dough@Bakery","50g butter@Dairy","3 garlic cloves@Produce","30g parmesan@Dairy"]},{"n":"Disco fries","note":"Crisp fries under hot beef gravy and melted mozzarella.","how":"Cut 1kg potatoes into chips, soak 30 minutes, dry and fry at 150C for 6 minutes, then at 190C until crisp. Melt 30g butter, stir in 2 tbsp flour for a minute, then whisk in 400ml hot beef stock and simmer 5 minutes into gravy. Pile the fries on a tray, pour over the gravy, top with 150g grated mozzarella and grill for a minute.","shop":["1kg potatoes@Produce","30g butter@Dairy","2 tbsp plain flour@Pantry","400ml beef stock@Pantry","150g mozzarella@Dairy","1L vegetable oil@Pantry"]}],"m":[{"n":"Two slices stacked","note":"Big thin New York slices, stacked two at a time and folded.","how":"Take 2 balls of pizza dough, about 500g, rested at room temperature for an hour. Blend 400g crushed tomatoes with 1 tsp salt and 1 tsp dried oregano. Stretch each base thin, spread with sauce and scatter 250g grated low-moisture mozzarella across both. Bake on a preheated tray at the oven's highest setting for 8 to 10 minutes. Cut into big slices, stack two and fold.","shop":["500g pizza dough@Bakery","400g crushed tomatoes@Pantry","1 tsp dried oregano@Pantry","250g low-moisture mozzarella@Dairy"]}],"w":[{"n":"Disco ball cake pops","note":"Cake and cream cheese balls dipped in white chocolate and silver cachous.","how":"Crumble 400g butter cake into a bowl and mix with 100g cream cheese until it holds together. Roll into 16 balls and chill 30 minutes. Push a stick into each, dip in 300g melted white chocolate and roll in 50g silver cachous so they sparkle. Stand in a glass to set.","shop":["400g butter cake@Bakery","100g cream cheese@Dairy","300g white chocolate@Pantry","50g silver cachous@Pantry","16 lollipop sticks@Pantry"]}],"d":[{"n":"7 and 7","note":"Blended whiskey over ice topped with lemonade.","how":"Fill four tall glasses with ice. Pour 45ml blended whiskey into each, about 180ml in total, then top with chilled lemonade, about 150ml a glass. Stir once and serve.","shop":["180ml blended whiskey@Bottle shop","600ml lemonade@Drinks","1kg ice@Frozen"]}],"shopping":["1kg pizza dough@Bakery","80g butter@Dairy","3 garlic cloves@Produce","30g parmesan@Dairy","1kg potatoes@Produce","2 tbsp plain flour@Pantry","400ml beef stock@Pantry","150g mozzarella@Dairy","1L vegetable oil@Pantry","400g crushed tomatoes@Pantry","1 tsp dried oregano@Pantry","250g low-moisture mozzarella@Dairy","400g butter cake@Bakery","100g cream cheese@Dairy","300g white chocolate@Pantry","50g silver cachous@Pantry","16 lollipop sticks@Pantry","180ml blended whiskey@Bottle shop","600ml lemonade@Drinks","1kg ice@Frozen"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"My Cousin Vinny (1992)":{"poster":"assets/menu-posters/my-cousin-vinny-1992.jpg","colour":"#237b8b","servings":4,"tagline":"Two yutes walk into a diner.","cue":"Serve breakfast during the grits cross-examination.","menu":{"s":[{"n":"Five-minute grits","note":"Slow-stirred creamy grits finished with butter and sharp cheddar.","how":"Bring 500ml milk and 500ml water to the boil with 1 tsp salt. Whisk in 150g stone-ground grits or polenta, then stir over low heat for 25 minutes until creamy. Finish with 40g butter and 80g grated sharp cheddar. Not five minutes, whatever anyone says.","shop":["500ml full cream milk@Dairy","150g stone-ground grits@Pantry","40g butter@Dairy","80g cheddar@Dairy"]},{"n":"Fried green tomatoes","note":"Cornmeal-crusted green tomatoes with a caper remoulade.","how":"Slice 3 green tomatoes 1cm thick, salt and leave 10 minutes, then pat dry. Dip in 150ml buttermilk, then 120g fine cornmeal seasoned with salt and pepper, and shallow-fry at 180C for 2 minutes a side. Mix 100g mayonnaise, 1 tsp mustard, 1 tbsp chopped capers and a dash of hot sauce for the remoulade.","shop":["3 green tomatoes@Produce","150ml buttermilk@Dairy","120g fine cornmeal@Pantry","100g mayonnaise@Pantry","1 tbsp capers@Pantry","1 tsp hot sauce@Pantry","500ml vegetable oil@Pantry"]}],"m":[{"n":"Sac-O-Suds chicken fried steak","note":"Crisp pounded steaks under black pepper cream gravy, with mash.","how":"Pound 4 minute steaks, about 600g, very thin. Dredge in seasoned flour, dip in 200ml buttermilk, then flour again, and shallow-fry 3 minutes a side until crisp. Pour off most of the oil, stir 2 tbsp flour into the pan, whisk in 400ml milk and simmer thick with lots of black pepper. Serve over 800g mashed potato.","shop":["600g minute steaks@Meat","150g plain flour@Pantry","200ml buttermilk@Dairy","400ml full cream milk@Dairy","800g potatoes@Produce","30g butter@Dairy","500ml vegetable oil@Pantry"]}],"w":[{"n":"Pecan pie","note":"Classic pecan pie in crisp shortcrust.","how":"Line a 23cm tin with 2 sheets sweet shortcrust pastry and blind bake at 180C for 15 minutes. Whisk 3 eggs, 200ml golden syrup, 100g brown sugar and 60g melted butter, fold in 200g pecans and pour into the case. Bake at 170C for 45 minutes until just set. Cool before slicing.","shop":["2 sheets sweet shortcrust pastry@Frozen","3 eggs@Dairy","200ml golden syrup@Pantry","100g brown sugar@Pantry","60g butter@Dairy","200g pecans@Pantry"]}],"d":[{"n":"Sweet tea","note":"Strong sweet black tea served cold with lemon.","how":"Steep 6 black tea bags in 1 litre of just-boiled water for 5 minutes, remove the bags and stir in 150g caster sugar while hot. Add 500ml cold water and chill. Serve over ice with lemon slices.","shop":["6 black tea bags@Pantry","150g caster sugar@Pantry","1 lemon@Produce","1kg ice@Frozen"]}],"shopping":["900ml full cream milk@Dairy","150g stone-ground grits@Pantry","130g butter@Dairy","80g cheddar@Dairy","3 green tomatoes@Produce","350ml buttermilk@Dairy","120g fine cornmeal@Pantry","100g mayonnaise@Pantry","1 tbsp capers@Pantry","1 tsp hot sauce@Pantry","1L vegetable oil@Pantry","600g minute steaks@Meat","150g plain flour@Pantry","800g potatoes@Produce","2 sheets sweet shortcrust pastry@Frozen","3 eggs@Dairy","200ml golden syrup@Pantry","100g brown sugar@Pantry","200g pecans@Pantry","6 black tea bags@Pantry","150g caster sugar@Pantry","1 lemon@Produce","1kg ice@Frozen"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Teenage Mutant Ninja Turtles (1990)":{"poster":"assets/menu-posters/teenage-mutant-ninja-turtles-1990.jpg","colour":"#478b35","servings":4,"tagline":"Four brothers. Four pizzas. Zero leftovers.","cue":"Order the pizza when it gets delivered down the drain.","menu":{"s":[{"n":"Sewer pizza rolls","note":"Rolled pizza dough spirals of pepperoni, sauce and mozzarella.","how":"Roll 500g pizza dough into a thin rectangle. Spread with 150ml pizza sauce, cover with 80g sliced pepperoni and 150g grated mozzarella. Roll up tightly from the long side, slice into 12 rounds and place cut side up on a lined tray. Bake at 220C for 15 minutes until golden.","shop":["500g pizza dough@Bakery","150ml pizza sauce@Pantry","80g pepperoni@Deli","150g mozzarella@Dairy"]},{"n":"Splinter's cheese plate","note":"Cheddar, brie and gouda with crackers, grapes and honey on the brie.","how":"Take 150g aged cheddar, 150g brie and 150g gouda out of the fridge an hour before serving. Arrange on a board with 150g crackers and a bunch of grapes. Drizzle 1 tbsp honey over the brie just before it goes on the table.","shop":["150g aged cheddar@Deli","150g brie@Deli","150g gouda@Deli","150g crackers@Pantry","500g grapes@Produce","1 tbsp honey@Pantry"]}],"m":[{"n":"Four-pie pizza night","note":"Four pizzas: pepperoni, mushroom, supreme, and everything in the fridge.","how":"Divide 1kg pizza dough into 4 balls and stretch thin. Spread each with pizza sauce, using 400ml in total, and 400g grated mozzarella across all four. Top one with pepperoni, one with sliced mushrooms, one with pepperoni, mushroom and capsicum, and one with whatever is left. Bake each on a preheated tray at the oven's highest setting for 8 minutes.","shop":["1kg pizza dough@Bakery","400ml pizza sauce@Pantry","400g mozzarella@Dairy","150g pepperoni@Deli","200g button mushrooms@Produce","1 capsicum@Produce"]}],"w":[{"n":"Pizza cookie","note":"Giant choc chip cookie baked on a pizza tray and topped with lollies.","how":"Beat 125g soft butter with 150g brown sugar and 1 egg, then mix in 200g plain flour, 1/2 tsp bicarb soda and 150g choc chips. Press into a greased pizza tray and bake at 180C for 15 minutes. Drizzle with 50g melted chocolate and scatter 100g lollies over the top. Cut into wedges.","shop":["125g butter@Dairy","150g brown sugar@Pantry","1 egg@Dairy","200g plain flour@Pantry","1/2 tsp bicarb soda@Pantry","150g choc chips@Pantry","50g dark chocolate@Pantry","100g lollies@Pantry"]}],"d":[{"n":"Green ooze float","note":"Lime soda poured over vanilla ice cream until it foams.","how":"Put two scoops of vanilla ice cream in each of four tall glasses, about 500ml in total. Slowly pour chilled lime soda over the top, about 250ml a glass, letting it foam up like ooze. Serve with a spoon and a straw.","shop":["500ml vanilla ice cream@Frozen","1.25L lime soda@Drinks"]}],"shopping":["1.5kg pizza dough@Bakery","550ml pizza sauce@Pantry","230g pepperoni@Deli","550g mozzarella@Dairy","150g aged cheddar@Deli","150g brie@Deli","150g gouda@Deli","150g crackers@Pantry","500g grapes@Produce","1 tbsp honey@Pantry","200g button mushrooms@Produce","1 capsicum@Produce","125g butter@Dairy","150g brown sugar@Pantry","1 egg@Dairy","200g plain flour@Pantry","1/2 tsp bicarb soda@Pantry","150g choc chips@Pantry","50g dark chocolate@Pantry","100g lollies@Pantry","500ml vanilla ice cream@Frozen","1.25L lime soda@Drinks"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Spider-Man (2002)":{"poster":"assets/menu-posters/spider-man-2002.jpg","colour":"#b5212d","servings":4,"tagline":"With great snacks comes great responsibility.","cue":"Serve the snacks at the wrestling match where Peter wins his first prize money.","menu":{"s":[{"n":"Web nachos","note":"Corn chips with beans and jalapeño under a spiderweb of hot queso.","how":"Spread 300g corn chips on a tray with a 400g tin black beans and 2 sliced jalapeños and warm at 180C for 5 minutes. Melt 200g grated cheddar into 150ml evaporated milk over low heat, stirring until smooth. Pour into a squeeze bottle and pipe a spiderweb across the chips.","shop":["300g corn chips@Pantry","400g black beans@Pantry","2 jalapeños@Produce","200g cheddar@Dairy","150ml evaporated milk@Pantry"]},{"n":"Thanksgiving sliders","note":"Mini rolls of roast turkey, cranberry sauce and crisp stuffing.","how":"Make a 170g stuffing mix as the packet says, press into a tray and bake at 190C for 25 minutes until crisp, then cut into 8 squares. Toast 8 slider buns. Fill each with 300g warm sliced roast turkey in total, a spoon of cranberry sauce and a square of stuffing.","shop":["170g stuffing mix@Pantry","8 slider buns@Bakery","300g roast turkey@Deli","150g cranberry sauce@Pantry"]}],"m":[{"n":"Aunt May's Thanksgiving roast","note":"Brined roast turkey breast with stuffing, gravy, potato and pumpkin.","how":"Brine a 1.2kg turkey breast overnight in 2 litres water with 100g salt. Pat dry, rub with butter and roast at 170C to 70C inside, about 75 minutes. Rest 15 minutes. Roast 800g potatoes and 600g pumpkin in chunks alongside. Bake a 170g stuffing mix. Make gravy from the pan juices, 2 tbsp flour and 400ml chicken stock.","shop":["1.2kg turkey breast@Meat","100g cooking salt@Pantry","30g butter@Dairy","800g potatoes@Produce","600g pumpkin@Produce","170g stuffing mix@Pantry","2 tbsp plain flour@Pantry","400ml chicken stock@Pantry"]}],"w":[{"n":"Aunt May's pancakes","note":"Fluffy buttermilk pancakes stacked high and drowned in maple syrup.","how":"Whisk 250g plain flour, 2 tbsp sugar, 2 tsp baking powder and a pinch of salt. Add 2 eggs, 400ml buttermilk and 40g melted butter and rest 15 minutes. Cook ladlefuls in a buttered pan over medium heat until bubbles set, then flip. Stack high and pour over 150ml maple syrup.","shop":["250g plain flour@Pantry","2 tbsp caster sugar@Pantry","2 tsp baking powder@Pantry","2 eggs@Dairy","400ml buttermilk@Dairy","60g butter@Dairy","150ml maple syrup@Pantry"]}],"d":[{"n":"Red and blue slushie","note":"Red and blue cordial slush layered in one cup.","how":"Blend 100ml raspberry cordial with 2 cups ice and 100ml water until slushy, and do the same with 100ml blue cordial. Spoon the red into four cups, then layer the blue on top. Serve with a spoon straw.","shop":["100ml raspberry cordial@Drinks","100ml blue cordial@Drinks","1kg ice@Frozen"]}],"shopping":["300g corn chips@Pantry","400g black beans@Pantry","2 jalapeños@Produce","200g cheddar@Dairy","150ml evaporated milk@Pantry","340g stuffing mix@Pantry","8 slider buns@Bakery","300g roast turkey@Deli","150g cranberry sauce@Pantry","1.2kg turkey breast@Meat","100g cooking salt@Pantry","90g butter@Dairy","800g potatoes@Produce","600g pumpkin@Produce","400ml chicken stock@Pantry","280g plain flour@Pantry","2 tbsp caster sugar@Pantry","2 tsp baking powder@Pantry","2 eggs@Dairy","400ml buttermilk@Dairy","150ml maple syrup@Pantry","100ml raspberry cordial@Drinks","100ml blue cordial@Drinks","1kg ice@Frozen"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"The Taking of Pelham One Two Three (1974)":{"poster":"assets/menu-posters/the-taking-of-pelham-one-two-three-1974.jpg","colour":"#ba921f","servings":4,"tagline":"Subway hostage. Snacks on the platform.","cue":"Serve the snacks when Garber hears the sneeze.","menu":{"s":[{"n":"Platform pretzels","note":"Soft salted pretzels with yellow mustard, like a subway stall.","how":"Mix 500g bread flour, 7g dried yeast, 1 tsp salt and 300ml warm water, knead 8 minutes and rise 1 hour. Shape 8 pretzels. Dip each for 30 seconds in 2 litres simmering water with 4 tbsp bicarb soda, sprinkle with rock salt and bake at 220C for 12 minutes. Serve with 100g yellow mustard.","shop":["500g bread flour@Pantry","7g dried yeast@Pantry","4 tbsp bicarb soda@Pantry","2 tbsp rock salt@Pantry","100g yellow mustard@Pantry"]},{"n":"Transit office jam doughnuts","note":"Warm jam doughnuts rolled in caster sugar.","how":"Warm 8 jam doughnuts on a tray at 160C for 2 minutes. Roll each straight away in 80g caster sugar so it sticks, and serve on a plate in the middle of the table like the transit office tray.","shop":["8 jam doughnuts@Bakery","80g caster sugar@Pantry"]}],"m":[{"n":"Transit authority hero","note":"Long turkey, Swiss and salad heroes wrapped tight in paper.","how":"Split 4 long rolls and spread each with mayonnaise, using 100g in total. Layer with 400g sliced turkey, 8 slices Swiss cheese, shredded iceberg lettuce and 2 sliced tomatoes. Season, close, wrap tightly in paper and cut in half.","shop":["4 long rolls@Bakery","100g mayonnaise@Pantry","400g sliced turkey@Deli","8 slices Swiss cheese@Deli","1 iceberg lettuce@Produce","2 tomatoes@Produce"]}],"w":[{"n":"Crumb cake","note":"Butter cake under a thick layer of cinnamon crumble.","how":"Rub 100g flour, 100g brown sugar, 1 tsp cinnamon and 80g cold butter into big crumbs. Beat 125g butter with 125g caster sugar, add 2 eggs and fold in 200g self-raising flour with 100ml milk. Spread in a lined 20cm square tin, cover thickly with the crumble and bake at 180C for 40 minutes.","shop":["100g plain flour@Pantry","100g brown sugar@Pantry","1 tsp ground cinnamon@Pantry","205g butter@Dairy","125g caster sugar@Pantry","2 eggs@Dairy","200g self-raising flour@Pantry","100ml full cream milk@Dairy"]}],"d":[{"n":"Bodega coffee","note":"Drip coffee with milk and sugar in paper cups.","how":"Brew 1 litre of drip coffee with 60g ground coffee. Pour into four paper cups, add milk, about 200ml in total, and sugar to taste, and snap on the lids.","shop":["60g ground coffee@Pantry","200ml full cream milk@Dairy","1 bag raw sugar@Pantry"]}],"shopping":["500g bread flour@Pantry","7g dried yeast@Pantry","4 tbsp bicarb soda@Pantry","2 tbsp rock salt@Pantry","100g yellow mustard@Pantry","8 jam doughnuts@Bakery","205g caster sugar@Pantry","4 long rolls@Bakery","100g mayonnaise@Pantry","400g sliced turkey@Deli","8 slices Swiss cheese@Deli","1 iceberg lettuce@Produce","2 tomatoes@Produce","100g plain flour@Pantry","100g brown sugar@Pantry","1 tsp ground cinnamon@Pantry","205g butter@Dairy","2 eggs@Dairy","200g self-raising flour@Pantry","300ml full cream milk@Dairy","60g ground coffee@Pantry","1 bag raw sugar@Pantry"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Ghost Dog: The Way of the Samurai (1999)":{"poster":"assets/menu-posters/ghost-dog-the-way-of-the-samurai-1999.jpg","colour":"#303857","servings":4,"tagline":"Silent. Loyal. Hungry.","cue":"Serve dessert when Ghost Dog swaps books with Pearline.","menu":{"s":[{"n":"Rooftop mixed nuts","note":"Soy, honey and sesame roasted nuts and pumpkin seeds.","how":"Toss 250g mixed nuts and 50g pumpkin seeds with 1 tbsp soy sauce, 1 tbsp honey and 1 tbsp sesame seeds. Spread on a lined tray and roast at 170C for 12 minutes, stirring once. Cool on the tray so they crisp.","shop":["250g mixed nuts@Pantry","50g pumpkin seeds@Pantry","1 tbsp soy sauce@Pantry","1 tbsp honey@Pantry","1 tbsp sesame seeds@Pantry"]},{"n":"Edamame","note":"Salted edamame with a drop of sesame oil.","how":"Boil 500g frozen edamame in salted water for 4 minutes and drain well. Toss with 1 tsp sea salt flakes and 1 tsp sesame oil and serve warm in a bowl, with another bowl for the empty pods.","shop":["500g frozen edamame@Frozen","1 tsp sea salt flakes@Pantry","1 tsp sesame oil@Pantry"]}],"m":[{"n":"Teriyaki rice bowl","note":"Glazed teriyaki chicken over rice with pickled ginger and spring onion.","how":"Simmer 80ml soy sauce, 80ml mirin, 60ml sake and 2 tbsp sugar for 5 minutes until syrupy. Sear 800g chicken thighs skin side down for 8 minutes, flip, cook 5 minutes, then pour in the sauce and turn until glazed. Slice over 400g steamed short grain rice with 40g pickled ginger and sliced spring onion.","shop":["80ml soy sauce@Pantry","80ml mirin@Pantry","60ml sake@Bottle shop","2 tbsp caster sugar@Pantry","800g chicken thighs@Meat","400g short grain rice@Pantry","40g pickled ginger@Pantry","2 spring onions@Produce"]}],"w":[{"n":"Coconut ice cream","note":"Creamy coconut ice cream scattered with golden toasted coconut.","how":"Toast 50g shredded coconut in a dry pan until golden. Blend 400ml coconut cream, 200ml thickened cream and 120g caster sugar until the sugar dissolves, then stir in most of the coconut. Churn, or freeze in a tub and stir every hour for 4 hours. Scoop and finish with the rest of the coconut.","shop":["50g shredded coconut@Pantry","400ml coconut cream@Pantry","200ml thickened cream@Dairy","120g caster sugar@Pantry"]}],"d":[{"n":"Green tea","note":"Sencha steeped gently and poured into small cups.","how":"Heat 800ml water to about 75C, just steaming. Pour over 2 tbsp sencha green tea in a small pot and steep 90 seconds. Pour into four small cups, going back and forth so each cup gets an even strength.","shop":["2 tbsp sencha green tea@Pantry"]}],"shopping":["250g mixed nuts@Pantry","50g pumpkin seeds@Pantry","1 tbsp honey@Pantry","1 tbsp sesame seeds@Pantry","500g frozen edamame@Frozen","1 tsp sea salt flakes@Pantry","1 tsp sesame oil@Pantry","95ml soy sauce@Pantry","80ml mirin@Pantry","60ml sake@Bottle shop","800g chicken thighs@Meat","400g short grain rice@Pantry","40g pickled ginger@Pantry","2 spring onions@Produce","50g shredded coconut@Pantry","400ml coconut cream@Pantry","200ml thickened cream@Dairy","150g caster sugar@Pantry","2 tbsp sencha green tea@Pantry"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Die Hard with a Vengeance (1995)":{"poster":"assets/menu-posters/die-hard-with-a-vengeance-1995.jpg","colour":"#b34c29","servings":4,"tagline":"One very long day in New York. Snacks for the road.","cue":"Pour drinks when McClane gets the water jug puzzle.","menu":{"s":[{"n":"Zeus's shop counter sweets","note":"Liquorice, jelly beans, chocolate and salted peanuts in one big bowl.","how":"Tip 150g liquorice, 150g jelly beans, 4 chocolate bars broken into chunks and 100g salted peanuts into a big bowl and mix. Put it on the counter, the way it sits in Zeus's shop.","shop":["150g liquorice@Pantry","150g jelly beans@Pantry","4 chocolate bars@Pantry","100g salted peanuts@Pantry"]},{"n":"Central Park pretzels","note":"Soft pretzels refreshed with butter and salt, mustard alongside.","how":"Brush 4 soft pretzels with 20g melted butter and sprinkle with 1 tsp rock salt. Bake at 200C for 5 minutes until hot and glossy. Serve with 100g yellow mustard for dipping.","shop":["4 soft pretzels@Bakery","20g butter@Dairy","1 tsp rock salt@Pantry","100g yellow mustard@Pantry"]}],"m":[{"n":"Bacon egg and cheese on a roll","note":"Crisp bacon, fried egg and melted cheese in a toasted roll.","how":"Fry 8 rashers bacon until crisp. Fry 4 eggs in the same pan, breaking the yolks, and lay a slice of American cheese on each to melt. Split and butter 4 kaiser rolls and toast them. Fill with 2 rashers bacon and an egg each, season with salt and pepper and add tomato sauce.","shop":["8 rashers bacon@Meat","4 eggs@Dairy","4 slices American cheese@Dairy","4 kaiser rolls@Bakery","20g butter@Dairy","3 tbsp tomato sauce@Pantry"]}],"w":[{"n":"Crumb cake","note":"Butter cake under thick cinnamon crumble and icing sugar.","how":"Rub 100g plain flour, 100g brown sugar, 1 tsp cinnamon and 80g cold butter into big crumbs. Beat 125g butter with 125g caster sugar, add 2 eggs and fold in 200g self-raising flour with 100ml milk. Spread in a lined 20cm tin, cover with the crumble and bake at 180C for 40 minutes. Dust with icing sugar.","shop":["100g plain flour@Pantry","100g brown sugar@Pantry","1 tsp ground cinnamon@Pantry","205g butter@Dairy","125g caster sugar@Pantry","2 eggs@Dairy","200g self-raising flour@Pantry","100ml full cream milk@Dairy","1 tbsp icing sugar@Pantry"]}],"d":[{"n":"Water jug lemonade","note":"Fresh lemonade in a big jug, measured to exactly four litres.","how":"Dissolve 300g caster sugar in 300ml hot water and cool. Add 400ml lemon juice, about 10 lemons, and top up with cold water to exactly 4 litres. Work it out with a 5 litre and a 3 litre jug if you're feeling brave. Serve over ice.","shop":["300g caster sugar@Pantry","10 lemons@Produce","1kg ice@Frozen"]}],"shopping":["150g liquorice@Pantry","150g jelly beans@Pantry","4 chocolate bars@Pantry","100g salted peanuts@Pantry","4 soft pretzels@Bakery","245g butter@Dairy","1 tsp rock salt@Pantry","100g yellow mustard@Pantry","8 rashers bacon@Meat","6 eggs@Dairy","4 slices American cheese@Dairy","4 kaiser rolls@Bakery","3 tbsp tomato sauce@Pantry","100g plain flour@Pantry","100g brown sugar@Pantry","1 tsp ground cinnamon@Pantry","425g caster sugar@Pantry","200g self-raising flour@Pantry","100ml full cream milk@Dairy","1 tbsp icing sugar@Pantry","10 lemons@Produce","1kg ice@Frozen"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"16 Blocks (2006)":{"poster":"assets/menu-posters/16-blocks-2006.jpg","colour":"#326d70","servings":4,"tagline":"Sixteen blocks. One long lunch.","cue":"Serve dessert when Eddie talks about opening a bakery.","menu":{"s":[{"n":"Bus pretzels","note":"Hard pretzels with hot mustard cheddar dip.","how":"Warm 150ml evaporated milk in a small pan and stir in 200g grated cheddar over low heat until smooth. Add 1 tsp Dijon mustard and a pinch of cayenne. Serve hot in a bowl with 200g hard pretzels.","shop":["150ml evaporated milk@Pantry","200g cheddar@Dairy","1 tsp Dijon mustard@Pantry","1 pinch cayenne pepper@Pantry","200g pretzels@Pantry"]},{"n":"Chinatown dumplings","note":"Crisp-bottomed pork dumplings with soy, vinegar and ginger dip.","how":"Fry 24 frozen pork dumplings flat side down in 1 tbsp oil for 2 minutes, add 120ml water, cover and steam 4 minutes, then fry again until crisp underneath. Mix 3 tbsp soy sauce, 2 tbsp black vinegar and 1 tbsp fine ginger matchsticks for dipping.","shop":["24 frozen pork dumplings@Frozen","3 tbsp soy sauce@Pantry","2 tbsp black vinegar@Pantry","1 piece ginger@Produce"]}],"m":[{"n":"Chopped cheese","note":"Griddle-chopped beef and onion with melted cheese in a hero.","how":"Fry 1 diced onion on a hot griddle, add 600g beef mince and chop it up with a spatula as it browns, seasoning well. Lay 6 slices American cheese on top and chop through until melted. Pile into 4 toasted hero rolls with shredded lettuce, sliced tomato and mayo.","shop":["1 brown onion@Produce","600g beef mince@Meat","6 slices American cheese@Dairy","4 hero rolls@Bakery","1 iceberg lettuce@Produce","2 tomatoes@Produce","80g mayonnaise@Pantry"]}],"w":[{"n":"Eddie's birthday cake","note":"Chocolate layer cake in chocolate buttercream, with candles.","how":"Beat 200g butter with 200g caster sugar, add 4 eggs, then fold in 220g self-raising flour, 40g cocoa and 120ml milk. Bake in two 20cm tins at 180C for 25 minutes. Beat 150g butter with 300g icing sugar and 40g cocoa, sandwich and cover the cakes, and add birthday candles.","shop":["350g butter@Dairy","200g caster sugar@Pantry","4 eggs@Dairy","220g self-raising flour@Pantry","80g cocoa@Pantry","120ml full cream milk@Dairy","300g icing sugar@Pantry","1 pack birthday candles@Pantry"]}],"d":[{"n":"Bodega coffee","note":"Drip coffee with milk and sugar in paper cups.","how":"Brew 1 litre of drip coffee with 60g ground coffee. Pour into four paper cups with milk, about 200ml in total, and sugar to taste, and serve fast.","shop":["60g ground coffee@Pantry","200ml full cream milk@Dairy","1 bag raw sugar@Pantry"]}],"shopping":["150ml evaporated milk@Pantry","200g cheddar@Dairy","1 tsp Dijon mustard@Pantry","1 pinch cayenne pepper@Pantry","200g pretzels@Pantry","24 frozen pork dumplings@Frozen","3 tbsp soy sauce@Pantry","2 tbsp black vinegar@Pantry","1 piece ginger@Produce","1 brown onion@Produce","600g beef mince@Meat","6 slices American cheese@Dairy","4 hero rolls@Bakery","1 iceberg lettuce@Produce","2 tomatoes@Produce","80g mayonnaise@Pantry","350g butter@Dairy","200g caster sugar@Pantry","4 eggs@Dairy","220g self-raising flour@Pantry","80g cocoa@Pantry","320ml full cream milk@Dairy","300g icing sugar@Pantry","1 pack birthday candles@Pantry","60g ground coffee@Pantry","1 bag raw sugar@Pantry"]}}});
