Object.assign(MOVIE_MENU_EDITIONS,{"Goodfellas (1990)":{"poster":"assets/menu-posters/goodfellas-1990.jpg","colour":"#7d2525","servings":4,"tagline":"As far back as I can remember, I always wanted seconds.","cue":"Plate up the mains when Paulie starts slicing garlic in the prison kitchen.","menu":{"s":[{"n":"Razor-thin garlic bruschetta","note":"Grilled ciabatta with tomato and garlic sliced as thin as possible.","how":"Slice 6 garlic cloves paper thin on a mandoline and cook in 80ml extra virgin olive oil over low heat for 5 minutes until soft and barely golden. Grill 8 slices of ciabatta, rub with the cut side of 2 halved tomatoes and season with salt. Spoon the garlic and its oil over the top and finish with torn basil.","shop":["6 garlic cloves@Produce","80ml extra virgin olive oil@Pantry","1 loaf ciabatta@Bakery","2 truss tomatoes@Produce","1 bunch basil@Produce"]},{"n":"Copacabana prawn cocktail","note":"Poached prawns on crisp iceberg with a brandy Marie Rose sauce.","how":"Poach 500g peeled green prawns for 2 minutes in salted water with a slice of lemon, then chill in iced water. Mix 120g mayonnaise with 2 tbsp tomato sauce, 1 tsp Worcestershire sauce, a few drops of hot sauce and 1 tsp brandy. Shred half an iceberg lettuce into four coupes, add the prawns and spoon over the sauce. Dust with paprika and serve with lemon wedges.","shop":["500g green prawns@Seafood","2 lemons@Produce","120g mayonnaise@Pantry","2 tbsp tomato sauce@Pantry","1 tsp Worcestershire sauce@Pantry","1 iceberg lettuce@Produce"]}],"m":[{"n":"Prison gravy with three-meat meatballs","note":"Veal, beef and pork meatballs simmered in a thin-garlic tomato sauce.","how":"Soak 2 slices bread in 80ml milk, then mix with 200g veal mince, 200g beef mince, 200g pork mince, 1 egg, 40g grated pecorino, chopped parsley and 1 crushed garlic clove. Roll into 16 balls and brown. In the same pot gently cook 4 garlic cloves sliced razor thin and half a diced onion, add 800g San Marzano tomatoes and the meatballs and simmer 90 minutes. Serve over 500g spaghetti.","shop":["200g veal mince@Meat","200g beef mince@Meat","200g pork mince@Meat","1 egg@Dairy","40g pecorino@Deli","5 garlic cloves@Produce","800g San Marzano tomatoes@Pantry","500g spaghetti@Pantry"]}],"w":[{"n":"Lemon ice","note":"Fluffy scraped lemon ice served in little paper cups.","how":"Simmer 200g caster sugar with 500ml water and the zest of 2 lemons for 5 minutes, then cool. Stir in 250ml lemon juice, about 6 lemons. Pour into a shallow tray and freeze, scraping with a fork every 30 minutes for 3 hours until light and fluffy. Serve in paper cups.","shop":["6 lemons@Produce","200g caster sugar@Pantry"]}],"d":[{"n":"Scotch and soda","note":"Blended Scotch over ice in a tall glass, topped with soda.","how":"Fill four highball glasses with ice. Pour 45ml blended Scotch into each, about 180ml in total, and top with chilled soda water, about 120ml each. No garnish, the way it was poured at the Bamboo Lounge.","shop":["180ml blended Scotch@Bottle shop","500ml soda water@Drinks","1kg ice@Frozen"]}],"shopping":["11 garlic cloves@Produce","80ml extra virgin olive oil@Pantry","1 loaf ciabatta@Bakery","2 truss tomatoes@Produce","1 bunch basil@Produce","500g green prawns@Seafood","8 lemons@Produce","120g mayonnaise@Pantry","2 tbsp tomato sauce@Pantry","1 tsp Worcestershire sauce@Pantry","1 iceberg lettuce@Produce","200g veal mince@Meat","200g beef mince@Meat","200g pork mince@Meat","1 egg@Dairy","40g pecorino@Deli","800g San Marzano tomatoes@Pantry","500g spaghetti@Pantry","200g caster sugar@Pantry","180ml blended Scotch@Bottle shop","500ml soda water@Drinks","1kg ice@Frozen"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Mean Streets (1973)":{"poster":"assets/menu-posters/mean-streets-1973.jpg","colour":"#b62924","servings":4,"tagline":"Sins in the street. Penance at the bar.","cue":"Hit play on the jukebox and pour a round when Johnny Boy walks into Tony's bar.","menu":{"s":[{"n":"San Gennaro sausage bites","note":"Blistered Italian sausage with charred onion and capsicum on toothpicks.","how":"Grill 500g Italian sausages over high heat for 12 minutes, turning, until blistered and cooked through. Grill 1 red capsicum and 1 onion cut into chunks until charred at the edges. Slice the sausages thick and thread onto toothpicks with the capsicum and onion. Serve with 50g hot mustard.","shop":["500g Italian sausages@Meat","1 red capsicum@Produce","1 brown onion@Produce","50g hot mustard@Pantry"]},{"n":"Fried calamari","note":"Tender squid rings in a crisp semolina coat with lemon.","how":"Slice 500g squid tubes into rings and soak in 250ml buttermilk for 30 minutes. Mix 100g fine semolina with 100g plain flour and plenty of salt. Drain the squid, toss in the flour mix and fry in 190C oil in batches for 90 seconds until pale gold. Salt and serve with 2 lemons cut into wedges.","shop":["500g squid tubes@Seafood","250ml buttermilk@Dairy","100g fine semolina@Pantry","100g plain flour@Pantry","2 lemons@Produce","1L vegetable oil@Pantry"]}],"m":[{"n":"Penne arrabbiata","note":"Penne in a fiery garlic, chilli and tomato sauce with pecorino.","how":"Gently fry 4 sliced garlic cloves and 1 tsp dried chilli flakes in 4 tbsp olive oil for 2 minutes. Add 800g crushed tomatoes and simmer 15 minutes, seasoning well. Cook 500g penne until al dente and toss through the sauce with a splash of pasta water and chopped parsley. Finish with 50g grated pecorino.","shop":["4 garlic cloves@Produce","1 tsp dried chilli flakes@Pantry","4 tbsp olive oil@Pantry","800g crushed tomatoes@Pantry","500g penne@Pantry","1 bunch parsley@Produce","50g pecorino@Deli"]}],"w":[{"n":"Zeppole","note":"Hot fried dough puffs shaken in a bag of icing sugar.","how":"Mix 250g plain flour, 7g dried yeast, 1 tbsp caster sugar, a pinch of salt and 200ml warm water into a sticky batter and leave to rise for 1 hour. Drop teaspoons into 175C oil and fry 3 minutes until puffed and golden. Drain, tip into a paper bag with 60g icing sugar, shake and eat hot.","shop":["250g plain flour@Pantry","7g dried yeast@Pantry","1 tbsp caster sugar@Pantry","60g icing sugar@Pantry","1L vegetable oil@Pantry"]}],"d":[{"n":"Red wine","note":"Cheap and cheerful Italian red in a jug, slightly chilled.","how":"Chill one 750ml bottle of Italian red in the fridge for 20 minutes so it is just cool. Pour into a jug and serve in short tumblers, about 180ml each.","shop":["750ml Italian red wine@Bottle shop"]}],"shopping":["500g Italian sausages@Meat","1 red capsicum@Produce","1 brown onion@Produce","50g hot mustard@Pantry","500g squid tubes@Seafood","250ml buttermilk@Dairy","100g fine semolina@Pantry","350g plain flour@Pantry","2 lemons@Produce","2L vegetable oil@Pantry","4 garlic cloves@Produce","1 tsp dried chilli flakes@Pantry","4 tbsp olive oil@Pantry","800g crushed tomatoes@Pantry","500g penne@Pantry","1 bunch parsley@Produce","50g pecorino@Deli","7g dried yeast@Pantry","1 tbsp caster sugar@Pantry","60g icing sugar@Pantry","750ml Italian red wine@Bottle shop"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"The Untouchables (1987)":{"poster":"assets/menu-posters/the-untouchables-1987.jpg","colour":"#203b4b","servings":4,"tagline":"Never bring a knife to a gunfight. Bring a fork.","cue":"Pour Ness his drink at the very end, when he's finally earned one.","menu":{"s":[{"n":"Chicago hot dogs","note":"Poppy seed buns loaded Chicago style with relish, pickle and celery salt.","how":"Simmer 8 all-beef franks for 5 minutes, then griddle until marked. Steam 8 poppy seed hot dog buns for a minute. Load each frank with yellow mustard, sweet relish, diced onion, tomato wedges, a pickle spear and 2 pickled chillies, and finish with a pinch of celery salt. No tomato sauce.","shop":["8 all-beef franks@Meat","8 poppy seed hot dog buns@Bakery","3 tbsp yellow mustard@Pantry","4 tbsp sweet relish@Pantry","1 brown onion@Produce","2 tomatoes@Produce","4 dill pickles@Pantry","16 pickled chillies@Pantry","1 tsp celery salt@Pantry"]},{"n":"Prohibition pretzels","note":"Soft salted pretzels with a honey and lager mustard.","how":"Mix 500g bread flour, 7g dried yeast, 1 tsp salt and 300ml warm water, knead 8 minutes and rise 1 hour. Shape 8 pretzels. Dip each for 30 seconds in 2 litres boiling water with 4 tbsp bicarb soda, sprinkle with rock salt and bake at 220C for 12 minutes. Whisk 4 tbsp wholegrain mustard with 2 tbsp lager and 1 tbsp honey.","shop":["500g bread flour@Pantry","7g dried yeast@Pantry","4 tbsp bicarb soda@Pantry","2 tbsp rock salt@Pantry","4 tbsp wholegrain mustard@Pantry","2 tbsp lager@Bottle shop","1 tbsp honey@Pantry"]}],"m":[{"n":"Italian beef","note":"Shaved roast beef soaked in garlic jus, piled in rolls with giardiniera.","how":"Rub a 1kg beef topside with salt, pepper and oregano and roast at 200C to 52C inside, about 35 minutes. Chill, then shave thin. Simmer 750ml beef stock with 3 crushed garlic cloves, 1 tsp dried oregano and plenty of black pepper. Warm the beef in the jus, pile into 4 long rolls, dip the whole sandwich, and top with 200g hot giardiniera.","shop":["1kg beef topside@Meat","750ml beef stock@Pantry","3 garlic cloves@Produce","2 tsp dried oregano@Pantry","4 long rolls@Bakery","200g hot giardiniera@Deli"]}],"w":[{"n":"Bourbon pecan pie","note":"Glossy bourbon pecan filling baked in crisp sweet shortcrust.","how":"Line a 23cm tin with 2 sheets sweet shortcrust pastry, blind bake at 180C for 15 minutes. Whisk 3 eggs, 200ml golden syrup, 100g brown sugar, 60g melted butter and 30ml bourbon, then fold in 200g pecans. Pour into the case and bake at 170C for 45 minutes until just set. Cool before slicing.","shop":["2 sheets sweet shortcrust pastry@Frozen","3 eggs@Dairy","200ml golden syrup@Pantry","100g brown sugar@Pantry","60g butter@Dairy","30ml bourbon@Bottle shop","200g pecans@Pantry"]}],"d":[{"n":"Repeal Day old fashioned","note":"Rye stirred with sugar and bitters over a big cube.","how":"Make sugar syrup by dissolving 40g caster sugar in 40ml hot water. For each drink, stir 60ml rye whiskey, 10ml syrup and 2 dashes aromatic bitters over ice for 30 seconds and strain over one big cube. Twist a strip of orange peel over the top. Makes four with 240ml rye.","shop":["240ml rye whiskey@Bottle shop","40g caster sugar@Pantry","1 bottle aromatic bitters@Bottle shop","1 orange@Produce","4 large ice cubes@Frozen"]}],"shopping":["8 all-beef franks@Meat","8 poppy seed hot dog buns@Bakery","3 tbsp yellow mustard@Pantry","4 tbsp sweet relish@Pantry","1 brown onion@Produce","2 tomatoes@Produce","4 dill pickles@Pantry","16 pickled chillies@Pantry","1 tsp celery salt@Pantry","500g bread flour@Pantry","7g dried yeast@Pantry","4 tbsp bicarb soda@Pantry","2 tbsp rock salt@Pantry","4 tbsp wholegrain mustard@Pantry","2 tbsp lager@Bottle shop","1 tbsp honey@Pantry","1kg beef topside@Meat","750ml beef stock@Pantry","3 garlic cloves@Produce","2 tsp dried oregano@Pantry","4 long rolls@Bakery","200g hot giardiniera@Deli","2 sheets sweet shortcrust pastry@Frozen","3 eggs@Dairy","200ml golden syrup@Pantry","100g brown sugar@Pantry","60g butter@Dairy","30ml bourbon@Bottle shop","200g pecans@Pantry","240ml rye whiskey@Bottle shop","40g caster sugar@Pantry","1 bottle aromatic bitters@Bottle shop","1 orange@Produce","4 large ice cubes@Frozen"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Analyze This (1999)":{"poster":"assets/menu-posters/analyze-this-1999.jpg","colour":"#244536","servings":4,"tagline":"Therapy, but make it Italian.","cue":"Serve dessert when Paul tells Ben \"you, you're good\".","menu":{"s":[{"n":"Fried calamari","note":"Tender squid rings in a light semolina crust with lemon.","how":"Slice 500g squid tubes into rings and soak in 250ml buttermilk for 30 minutes. Mix 100g fine semolina and 100g plain flour with plenty of salt. Toss the drained squid through and fry at 190C in batches for 90 seconds. Salt and serve with 2 lemons cut into wedges.","shop":["500g squid tubes@Seafood","250ml buttermilk@Dairy","100g fine semolina@Pantry","100g plain flour@Pantry","2 lemons@Produce","1L vegetable oil@Pantry"]},{"n":"Mozzarella in carrozza","note":"Fried mozzarella sandwiches in a golden egg and crumb coat.","how":"Cut the crusts off 8 slices white bread and make 4 sandwiches with 250g sliced mozzarella. Cut each into triangles. Dip in 3 eggs beaten with 3 tbsp milk, then press into 100g breadcrumbs. Shallow-fry in 1cm of oil for 2 minutes a side until golden and the cheese melts.","shop":["8 slices white bread@Bakery","250g mozzarella@Dairy","3 eggs@Dairy","3 tbsp full cream milk@Dairy","100g breadcrumbs@Pantry","1L vegetable oil@Pantry"]}],"m":[{"n":"Paul Vitti's veal parm","note":"Crumbed veal under marinara and bubbling mozzarella, with spaghetti.","how":"Dust 600g veal escalopes in flour, dip in 2 beaten eggs and coat in 120g breadcrumbs. Shallow-fry 2 minutes a side until golden. Top each with warm passata, 200g sliced mozzarella and 30g parmesan and grill until bubbling. Serve with 400g spaghetti tossed in the rest of the 700ml passata.","shop":["600g veal escalopes@Meat","2 tbsp plain flour@Pantry","2 eggs@Dairy","120g breadcrumbs@Pantry","700ml passata@Pantry","200g mozzarella@Dairy","30g parmesan@Dairy","400g spaghetti@Pantry"]}],"w":[{"n":"Cannoli","note":"Ricotta and orange cannoli with chocolate-dipped ends.","how":"Drain 500g fresh ricotta for 2 hours, then beat with 80g icing sugar and the zest of 1 orange. Melt 50g dark chocolate and dip the ends of 8 cannoli shells, then let set. Pipe the filling in just before serving.","shop":["500g fresh ricotta@Dairy","80g icing sugar@Pantry","1 orange@Produce","50g dark chocolate@Pantry","8 cannoli shells@Bakery"]}],"d":[{"n":"Negroni","note":"Gin, bitter red aperitif and sweet vermouth over a big cube.","how":"For each drink, stir 30ml gin, 30ml bitter red aperitif and 30ml sweet vermouth over ice for 20 seconds and strain over a big ice cube in a tumbler. Add a slice of orange. Makes four with 120ml of each.","shop":["120ml gin@Bottle shop","120ml bitter red aperitif@Bottle shop","120ml sweet vermouth@Bottle shop","1 orange@Produce","4 large ice cubes@Frozen"]}],"shopping":["500g squid tubes@Seafood","250ml buttermilk@Dairy","100g fine semolina@Pantry","130g plain flour@Pantry","2 lemons@Produce","2L vegetable oil@Pantry","8 slices white bread@Bakery","450g mozzarella@Dairy","5 eggs@Dairy","3 tbsp full cream milk@Dairy","220g breadcrumbs@Pantry","600g veal escalopes@Meat","700ml passata@Pantry","30g parmesan@Dairy","400g spaghetti@Pantry","500g fresh ricotta@Dairy","80g icing sugar@Pantry","2 orange@Produce","50g dark chocolate@Pantry","8 cannoli shells@Bakery","120ml gin@Bottle shop","120ml bitter red aperitif@Bottle shop","120ml sweet vermouth@Bottle shop","4 large ice cubes@Frozen"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Mickey Blue Eyes (1999)":{"poster":"assets/menu-posters/mickey-blue-eyes-1999.jpg","colour":"#244b8b","servings":4,"tagline":"Marry the girl. Marry the family.","cue":"Serve the mains when Michael tries to do the Kansas City accent.","menu":{"s":[{"n":"English tea sandwiches","note":"Crustless finger sandwiches of cucumber, egg and cress, and smoked salmon.","how":"Boil 3 eggs for 10 minutes, then mash with 2 tbsp mayonnaise and cress. Butter 12 slices white bread. Make 2 sandwiches with thin cucumber, 2 with the egg, and 2 with 100g smoked salmon on 100g cream cheese. Cut off the crusts and cut each into 3 fingers.","shop":["12 slices white bread@Bakery","40g butter@Dairy","1 Lebanese cucumber@Produce","3 eggs@Dairy","2 tbsp mayonnaise@Pantry","1 punnet mustard cress@Produce","100g smoked salmon@Seafood","100g cream cheese@Dairy"]},{"n":"Fried ravioli","note":"Crisp crumbed ricotta ravioli with warm marinara and parmesan.","how":"Dip 400g fresh ricotta ravioli in 2 beaten eggs, then in 120g breadcrumbs. Fry at 180C in batches for 2 minutes until crisp and golden, then drain. Shower with 30g grated parmesan and serve with 300ml warm passata seasoned with salt and oregano for dipping.","shop":["400g ricotta ravioli@Dairy","2 eggs@Dairy","120g breadcrumbs@Pantry","30g parmesan@Dairy","300ml passata@Pantry","1L vegetable oil@Pantry"]}],"m":[{"n":"Vito's linguine with clams","note":"Linguine in garlicky white wine clam juices with parsley.","how":"Soak 1kg clams in salted water for 30 minutes to purge. Gently fry 4 sliced garlic cloves and a pinch of chilli in 60ml olive oil, add the clams and 150ml white wine, cover and steam 4 minutes until open. Cook 400g linguine 1 minute short, finish it in the pan juices and toss with chopped parsley and more olive oil.","shop":["1kg clams@Seafood","4 garlic cloves@Produce","60ml olive oil@Pantry","150ml white wine@Bottle shop","400g linguine@Pantry","1 bunch parsley@Produce"]}],"w":[{"n":"Tiramisu","note":"Espresso-soaked biscuits layered with marsala mascarpone cream and cocoa.","how":"Whisk 4 egg yolks with 100g caster sugar until pale, then fold in 500g mascarpone and 4 egg whites whipped stiff. Mix 300ml strong espresso with 3 tbsp marsala. Dip 24 savoiardi biscuits quickly and layer with the cream in a dish. Dust with 2 tbsp cocoa and chill overnight.","shop":["4 eggs@Dairy","100g caster sugar@Pantry","500g mascarpone@Dairy","300ml espresso@Pantry","3 tbsp marsala@Bottle shop","24 savoiardi biscuits@Pantry","2 tbsp cocoa@Pantry"]}],"d":[{"n":"Pinot grigio","note":"Crisp pinot grigio well chilled and poured small and often.","how":"Chill one 750ml bottle of pinot grigio to about 8C, around 3 hours in the fridge. Pour small glasses, about 120ml each, and top up through dinner.","shop":["750ml pinot grigio@Bottle shop"]}],"shopping":["12 slices white bread@Bakery","40g butter@Dairy","1 Lebanese cucumber@Produce","9 eggs@Dairy","2 tbsp mayonnaise@Pantry","1 punnet mustard cress@Produce","100g smoked salmon@Seafood","100g cream cheese@Dairy","400g ricotta ravioli@Dairy","120g breadcrumbs@Pantry","30g parmesan@Dairy","300ml passata@Pantry","1L vegetable oil@Pantry","1kg clams@Seafood","4 garlic cloves@Produce","60ml olive oil@Pantry","150ml white wine@Bottle shop","400g linguine@Pantry","1 bunch parsley@Produce","100g caster sugar@Pantry","500g mascarpone@Dairy","300ml espresso@Pantry","3 tbsp marsala@Bottle shop","24 savoiardi biscuits@Pantry","2 tbsp cocoa@Pantry","750ml pinot grigio@Bottle shop"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Miller's Crossing (1990)":{"poster":"assets/menu-posters/millers-crossing-1990.jpg","colour":"#294730","servings":4,"tagline":"What's the rumpus?","cue":"Plate up when Tom goes back into the woods looking for his hat.","menu":{"s":[{"n":"Rye toast with chicken liver pâté","note":"Silky brandy chicken liver pâté under clarified butter, on rye toast.","how":"Trim 400g chicken livers and sear in butter for 2 minutes a side until still pink. Add 2 chopped shallots and thyme, then 40ml brandy and let it bubble off. Blitz with 150g soft butter until silky, season and press into a dish. Pour over 50g melted clarified butter and chill 4 hours. Serve with 8 slices toasted rye.","shop":["400g chicken livers@Meat","200g butter@Dairy","2 shallots@Produce","1 bunch thyme@Produce","40ml brandy@Bottle shop","8 slices rye bread@Bakery"]},{"n":"Cheese straws","note":"Twisted puff pastry straws with cheddar, parmesan and cayenne.","how":"Brush 2 sheets puff pastry with 1 beaten egg. Scatter one sheet with 80g grated aged cheddar, 30g grated parmesan and a pinch of cayenne, lay the other on top and press. Cut into 1.5cm strips, twist each and bake at 220C for 12 minutes until puffed and golden.","shop":["2 sheets puff pastry@Frozen","1 egg@Dairy","80g cheddar@Dairy","30g parmesan@Dairy","1 pinch cayenne pepper@Pantry"]}],"m":[{"n":"Leo's Irish stew","note":"Lamb neck chops braised with potato, onion, carrot and stout.","how":"Brown 1.2kg lamb neck chops in batches. Layer in a heavy pot with 2 sliced brown onions, 3 carrots in chunks and 800g potatoes in thick slices. Pour over 375ml stout and 300ml beef stock, cover and braise at 160C for 2 hours until tender. Finish with chopped parsley.","shop":["1.2kg lamb neck chops@Meat","2 brown onions@Produce","3 carrots@Produce","800g potatoes@Produce","375ml stout@Bottle shop","300ml beef stock@Pantry","1 bunch parsley@Produce"]}],"w":[{"n":"Whisky bread pudding","note":"Brioche and whiskey-soaked raisin pudding baked in a rich custard.","how":"Soak 80g raisins in 60ml Irish whiskey for 30 minutes. Butter 8 slices stale brioche and layer in a dish with the raisins. Whisk 4 eggs, 300ml milk, 200ml cream and 80g sugar and pour over. Rest 30 minutes, then bake at 170C for 40 minutes until puffed and golden.","shop":["80g raisins@Pantry","60ml Irish whiskey@Bottle shop","8 slices brioche@Bakery","40g butter@Dairy","4 eggs@Dairy","300ml full cream milk@Dairy","200ml thickened cream@Dairy","80g caster sugar@Pantry"]}],"d":[{"n":"Irish whiskey","note":"Irish whiskey neat in a heavy glass, water on the side.","how":"Pour 45ml Irish whiskey into each of four heavy glasses, about 180ml in total. Put a small jug of cold water on the table for anyone who wants a few drops.","shop":["180ml Irish whiskey@Bottle shop"]}],"shopping":["400g chicken livers@Meat","240g butter@Dairy","2 shallots@Produce","1 bunch thyme@Produce","40ml brandy@Bottle shop","8 slices rye bread@Bakery","2 sheets puff pastry@Frozen","1 egg@Dairy","80g cheddar@Dairy","30g parmesan@Dairy","1 pinch cayenne pepper@Pantry","1.2kg lamb neck chops@Meat","2 brown onions@Produce","3 carrots@Produce","800g potatoes@Produce","375ml stout@Bottle shop","300ml beef stock@Pantry","1 bunch parsley@Produce","80g raisins@Pantry","240ml Irish whiskey@Bottle shop","8 slices brioche@Bakery","4 eggs@Dairy","300ml full cream milk@Dairy","200ml thickened cream@Dairy","80g caster sugar@Pantry"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Moonstruck (1987)":{"poster":"assets/menu-posters/moonstruck-1987.jpg","colour":"#344d6c","servings":4,"tagline":"Snap out of it and eat.","cue":"Bring out the bread when Ronny is in the bakery basement.","menu":{"s":[{"n":"Ronny's bakery bread","note":"Warm crusty Italian loaf torn into grassy olive oil and salt.","how":"Warm a crusty Italian loaf at 200C for 8 minutes. Pour 80ml extra virgin olive oil into a shallow dish with 1 tsp sea salt flakes and a good crack of pepper. Tear the bread at the table and dip.","shop":["1 loaf Italian bread@Bakery","80ml extra virgin olive oil@Pantry","1 tsp sea salt flakes@Pantry"]},{"n":"Eggs in the hole","note":"Fried eggs cooked in rings of red capsicum inside buttered toast.","how":"Cut a hole in 4 thick slices white bread. Melt 40g butter in a big pan and lay in the bread. Put a thick ring of red capsicum in each hole, crack an egg into it, and fry until the white sets, flipping the bread once. Season with salt and pepper.","shop":["4 slices white bread@Bakery","40g butter@Dairy","1 red capsicum@Produce","4 eggs@Dairy"]}],"m":[{"n":"Chicken scaloppine","note":"Thin seared chicken in lemon, white wine and caper butter sauce.","how":"Slice 2 large chicken breasts, about 600g, in half horizontally and pound thin. Dust in flour and sear in oil and 20g butter for 2 minutes a side, then set aside. Add 100ml white wine, the juice of 1 lemon and 2 tbsp capers, reduce by half and swirl in 40g cold butter and parsley. Return the chicken to coat.","shop":["600g chicken breasts@Meat","2 tbsp plain flour@Pantry","60g butter@Dairy","100ml white wine@Bottle shop","1 lemon@Produce","2 tbsp capers@Pantry","1 bunch parsley@Produce"]}],"w":[{"n":"Cannoli","note":"Orange ricotta cannoli with chocolate-dipped ends.","how":"Drain 500g fresh ricotta for 2 hours, then beat with 80g icing sugar and the zest of 1 orange. Dip the ends of 8 cannoli shells in 50g melted dark chocolate and let set. Pipe in the filling just before serving.","shop":["500g fresh ricotta@Dairy","80g icing sugar@Pantry","1 orange@Produce","50g dark chocolate@Pantry","8 cannoli shells@Bakery"]}],"d":[{"n":"Champagne","note":"Brut champagne in coupes for the family toast at the end.","how":"Chill one 750ml bottle of brut champagne to about 7C. Pour into four coupes, about 180ml each, and raise them to la famiglia, the way they do at the kitchen table.","shop":["750ml champagne@Bottle shop"]}],"shopping":["1 loaf Italian bread@Bakery","80ml extra virgin olive oil@Pantry","1 tsp sea salt flakes@Pantry","4 slices white bread@Bakery","100g butter@Dairy","1 red capsicum@Produce","4 eggs@Dairy","600g chicken breasts@Meat","2 tbsp plain flour@Pantry","100ml white wine@Bottle shop","1 lemon@Produce","2 tbsp capers@Pantry","1 bunch parsley@Produce","500g fresh ricotta@Dairy","80g icing sugar@Pantry","1 orange@Produce","50g dark chocolate@Pantry","8 cannoli shells@Bakery","750ml champagne@Bottle shop"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Big Night (1996)":{"poster":"assets/menu-posters/big-night-1996.jpg","colour":"#535825","servings":4,"tagline":"One night to save the restaurant.","cue":"Bring out the timpano when the dinner guests hold their breath.","menu":{"s":[{"n":"Arancini","note":"Saffron risotto balls with mozzarella and peas, fried deep gold.","how":"Cook 300g arborio rice in 900ml stock with a pinch of saffron until thick and chill overnight on a tray. Wrap golf balls of rice around a cube of mozzarella and a few peas, using 100g mozzarella and 50g peas. Roll in flour, 2 beaten eggs and 100g breadcrumbs, and fry at 175C until deep gold.","shop":["300g arborio rice@Pantry","900ml chicken stock@Pantry","1 pinch saffron@Pantry","100g mozzarella@Dairy","50g frozen peas@Frozen","2 eggs@Dairy","100g breadcrumbs@Pantry","1L vegetable oil@Pantry"]},{"n":"Antipasto board","note":"Prosciutto, lemony bresaola with rocket, eggplant, capsicum and olives.","how":"Lay 100g prosciutto flat on a board. Dress 100g bresaola with lemon juice, olive oil and a handful of rocket. Add 150g marinated eggplant, 2 roasted red capsicums peeled and sliced, 150g mixed olives and a warm loaf of Italian bread.","shop":["100g prosciutto@Deli","100g bresaola@Deli","1 lemon@Produce","1 bag rocket@Produce","150g marinated eggplant@Deli","2 red capsicums@Produce","150g mixed olives@Deli","1 loaf Italian bread@Bakery"]}],"m":[{"n":"Timpano","note":"Pasta drum of ziti, ragù, salami, egg and provolone, cut like a cake.","how":"Make dough with 300g 00 flour and 3 eggs, roll thin and line a buttered ovenproof bowl. Toss 400g cooked ziti with ragù made from 500g beef mince and 700ml passata. Layer in the bowl with 100g diced salami, 3 boiled eggs and 150g provolone. Fold the dough over, bake at 180C for 1 hour, rest 30 minutes, turn out and slice.","shop":["300g 00 flour@Pantry","6 eggs@Dairy","400g ziti or penne@Pantry","500g beef mince@Meat","700ml passata@Pantry","100g salami@Deli","150g provolone@Deli","20g butter@Dairy"]}],"w":[{"n":"Panna cotta","note":"Vanilla panna cotta turned out with fresh berries.","how":"Soak 2 gelatine leaves in cold water. Heat 500ml thickened cream, 100ml milk, 80g caster sugar and a split vanilla bean until steaming. Squeeze the gelatine and whisk it in, strain, and pour into four moulds. Set 6 hours. Dip the moulds in hot water, turn out and serve with 250g berries.","shop":["2 gelatine leaves@Pantry","500ml thickened cream@Dairy","100ml full cream milk@Dairy","80g caster sugar@Pantry","1 vanilla bean@Pantry","250g berries@Produce"]}],"d":[{"n":"Grappa","note":"Lightly chilled grappa in small glasses, with espresso for the brave.","how":"Chill a bottle of grappa for an hour. Pour 30ml into each of four small glasses, about 120ml in total. Make four short espressos with 30g ground coffee for anyone still standing after the timpano.","shop":["120ml grappa@Bottle shop","30g ground coffee@Pantry"]}],"shopping":["300g arborio rice@Pantry","900ml chicken stock@Pantry","1 pinch saffron@Pantry","100g mozzarella@Dairy","50g frozen peas@Frozen","8 eggs@Dairy","100g breadcrumbs@Pantry","1L vegetable oil@Pantry","100g prosciutto@Deli","100g bresaola@Deli","1 lemon@Produce","1 bag rocket@Produce","150g marinated eggplant@Deli","2 red capsicums@Produce","150g mixed olives@Deli","1 loaf Italian bread@Bakery","300g 00 flour@Pantry","400g ziti or penne@Pantry","500g beef mince@Meat","700ml passata@Pantry","100g salami@Deli","150g provolone@Deli","20g butter@Dairy","2 gelatine leaves@Pantry","500ml thickened cream@Dairy","100ml full cream milk@Dairy","80g caster sugar@Pantry","1 vanilla bean@Pantry","250g berries@Produce","120ml grappa@Bottle shop","30g ground coffee@Pantry"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Raging Bull (1980)":{"poster":"assets/menu-posters/raging-bull-1980.jpg","colour":"#963329","servings":4,"tagline":"Fight hard. Eat harder.","cue":"Serve the steak when Jake starts complaining his steak is overcooked.","menu":{"s":[{"n":"Boiled eggs","note":"Jammy seven-minute eggs with celery salt and cracked pepper.","how":"Lower 8 eggs into boiling water and cook exactly 7 minutes, then straight into iced water for 5 minutes. Peel, halve and sprinkle with 1 tsp celery salt and cracked black pepper.","shop":["8 eggs@Dairy","1 tsp celery salt@Pantry"]},{"n":"Copacabana prawns","note":"Chilled poached prawns with sharp horseradish cocktail sauce.","how":"Poach 500g peeled green prawns in salted water for 2 minutes and chill in iced water. Mix 150ml tomato sauce with 2 tsp horseradish and the juice of 1 lemon. Serve the prawns on ice with the sauce and lemon wedges.","shop":["500g green prawns@Seafood","150ml tomato sauce@Pantry","2 tsp horseradish@Pantry","2 lemons@Produce"]}],"m":[{"n":"Jake's steak","note":"Dry-brined porterhouse, seared hard and butter basted with garlic.","how":"Salt 2 porterhouse steaks, about 600g each, and leave uncovered in the fridge overnight. Sear in a smoking pan for 3 minutes a side, then add 50g butter, 3 crushed garlic cloves and a few thyme sprigs and baste until 52C inside. Rest 8 minutes and slice off the bone to share.","shop":["1.2kg porterhouse steak@Meat","50g butter@Dairy","3 garlic cloves@Produce","1 bunch thyme@Produce"]}],"w":[{"n":"Ricotta cake","note":"Baked lemon and vanilla ricotta cake dusted with icing sugar.","how":"Drain 750g fresh ricotta for 2 hours. Beat with 150g caster sugar, 4 eggs, the zest of 1 lemon and 1 tsp vanilla extract. Pour into a lined 22cm springform tin and bake at 160C for 60 minutes, then cool in the oven with the door ajar. Dust with icing sugar.","shop":["750g fresh ricotta@Dairy","150g caster sugar@Pantry","4 eggs@Dairy","1 lemon@Produce","1 tsp vanilla extract@Pantry","1 tbsp icing sugar@Pantry"]}],"d":[{"n":"Ice cold beer","note":"American lager in frosted glasses straight from the freezer.","how":"Put four glasses in the freezer for 30 minutes and chill four 355ml bottles of American lager. Pour into the frosted glasses and serve straight away.","shop":["4 bottles American lager@Bottle shop"]}],"shopping":["12 eggs@Dairy","1 tsp celery salt@Pantry","500g green prawns@Seafood","150ml tomato sauce@Pantry","2 tsp horseradish@Pantry","2 lemons@Produce","1.2kg porterhouse steak@Meat","50g butter@Dairy","3 garlic cloves@Produce","1 bunch thyme@Produce","750g fresh ricotta@Dairy","150g caster sugar@Pantry","1 lemon@Produce","1 tsp vanilla extract@Pantry","1 tbsp icing sugar@Pantry","4 bottles American lager@Bottle shop"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Things to Do in Denver When You're Dead (1995)":{"poster":"assets/menu-posters/things-to-do-in-denver-when-youre-dead-1995.jpg","colour":"#22535b","servings":4,"tagline":"Boat drinks.","cue":"Pour boat drinks every time someone says \"boat drinks\".","menu":{"s":[{"n":"Denver diner onion rings","note":"Thick beer-battered onion rings fried until puffed.","how":"Slice 2 large brown onions into thick rings and soak in 250ml buttermilk for 30 minutes. Whisk 150g plain flour with 200ml lager and a pinch of salt. Dip the rings in the batter and fry at 185C for 2 minutes until puffed and golden. Salt straight away.","shop":["2 brown onions@Produce","250ml buttermilk@Dairy","150g plain flour@Pantry","200ml lager@Bottle shop","1.5L vegetable oil@Pantry"]},{"n":"Fries with gravy","note":"Double-fried chips with hot brown gravy.","how":"Fry 1kg potatoes cut into chips at 140C for 6 minutes, rest, then at 185C until crisp. Cook 30g butter and 2 tbsp flour until nut brown, whisk in 400ml beef stock and simmer 5 minutes, seasoning well. Pour the gravy over the chips.","shop":["1kg potatoes@Produce","1.5L vegetable oil@Pantry","30g butter@Dairy","2 tbsp plain flour@Pantry","400ml beef stock@Pantry"]}],"m":[{"n":"Patty melt","note":"Beef patty on rye with Swiss and slow onions, griddled in butter.","how":"Cook 2 sliced brown onions in butter over low heat for 25 minutes. Shape 600g beef mince into 4 thin oval patties and sear 2 minutes a side. Butter 8 slices rye bread on the outside, fill each sandwich with a patty, onions and 2 slices Swiss cheese, and griddle in butter until crisp and melted.","shop":["2 brown onions@Produce","60g butter@Dairy","600g beef mince@Meat","8 slices rye bread@Bakery","8 slices Swiss cheese@Deli"]}],"w":[{"n":"Apple pie","note":"Lattice-topped Granny Smith apple pie with cinnamon and sugar.","how":"Peel and slice 1kg Granny Smith apples and toss with 100g caster sugar, 1 tsp cinnamon and 2 tbsp flour. Line a pie dish with 1 sheet sweet shortcrust, fill, and weave a lattice from a second sheet. Bake at 190C for 50 minutes until golden and bubbling.","shop":["1kg Granny Smith apples@Produce","100g caster sugar@Pantry","1 tsp ground cinnamon@Pantry","2 tbsp plain flour@Pantry","2 sheets sweet shortcrust pastry@Frozen"]}],"d":[{"n":"Boat drinks","note":"Piña colada blended icy with a cocktail umbrella.","how":"For four drinks, blend 200ml white rum, 240ml pineapple juice and 160ml coconut cream with 4 cups of ice until smooth. Pour into tall glasses and add a cocktail umbrella.","shop":["200ml white rum@Bottle shop","240ml pineapple juice@Drinks","160ml coconut cream@Pantry","1kg ice@Frozen"]}],"shopping":["4 brown onions@Produce","250ml buttermilk@Dairy","210g plain flour@Pantry","200ml lager@Bottle shop","3L vegetable oil@Pantry","1kg potatoes@Produce","90g butter@Dairy","400ml beef stock@Pantry","600g beef mince@Meat","8 slices rye bread@Bakery","8 slices Swiss cheese@Deli","1kg Granny Smith apples@Produce","100g caster sugar@Pantry","1 tsp ground cinnamon@Pantry","2 sheets sweet shortcrust pastry@Frozen","200ml white rum@Bottle shop","240ml pineapple juice@Drinks","160ml coconut cream@Pantry","1kg ice@Frozen"]}}});
