Object.assign(MOVIE_MENU_EDITIONS,{"Speed (1994)":{"poster":"assets/menu-posters/speed-1994.jpg","colour":"#b62923","servings":4,"tagline":"Keep it above 50.","cue":"Serve the mains when the bus jumps the freeway gap.","menu":{"s":[{"n":"LAX runway nachos","note":"Baked nachos with cheddar, jalapeños and black beans","how":"Spread a 300g bag of corn chips on a tray. Scatter over a drained tin of black beans, 200g grated cheddar and sliced jalapeños. Bake at 200C for 8 minutes until melted. Top with sour cream and a jar of salsa.","shop":["300g corn chips@Pantry","1 tin black beans@Pantry","200g cheddar@Dairy","1 jar jalapeños@Pantry","200g sour cream@Dairy","1 jar salsa@Pantry"]},{"n":"Subway train snacks","note":"Smoky buttered pretzels and peanuts, baked and bagged for the ride","how":"Toss 200g hard pretzels and 200g roasted peanuts with 50g melted butter and 1 tsp smoked paprika. Spread on a tray and bake at 160C for 15 minutes, stirring once. Cool and tip into paper bags.","shop":["200g pretzels@Pantry","200g peanuts@Pantry","50g butter@Dairy","1 jar smoked paprika@Pantry"]}],"m":[{"n":"LA street tacos","note":"Chargrilled citrus skirt steak in doubled corn tortillas","how":"Marinate 800g skirt steak in the juice of 2 limes and 1 orange, 3 garlic cloves and 1 tsp cumin for 2 hours. Grill very hot for 3 minutes a side, rest and chop. Serve in doubled corn tortillas with onion, coriander and salsa verde.","shop":["800g skirt steak@Meat","2 limes@Produce","1 orange@Produce","3 garlic cloves@Produce","1 jar ground cumin@Pantry","24 corn tortillas@Bakery","1 onion@Produce","1 bunch coriander@Produce","1 jar salsa verde@Pantry"]}],"w":[{"n":"Ice cream sandwiches","note":"Choc chip cookie ice cream sandwiches rolled in sprinkles","how":"Soften 1L vanilla ice cream for 5 minutes. Sandwich a thick scoop between two soft choc chip cookies, using 8 cookies for 4 sandwiches. Roll the edges in sprinkles, wrap in baking paper and freeze for an hour.","shop":["8 choc chip cookies@Bakery","1L vanilla ice cream@Frozen","1 jar sprinkles@Pantry"]}],"d":[{"n":"Annie's coffee","note":"Cold brew over ice with milk and a scoop of ice cream","how":"Steep 100g coarsely ground coffee in 1L cold water in the fridge overnight, then strain. Pour over ice in four tall glasses, about 200ml each, add a splash of milk and float a scoop of vanilla ice cream on top.","shop":["100g coffee beans@Pantry","200ml full cream milk@Dairy","500ml vanilla ice cream@Frozen"]}],"shopping":["300g corn chips@Pantry","1 tin black beans@Pantry","200g cheddar@Dairy","1 jar jalapeños@Pantry","200g sour cream@Dairy","1 jar salsa@Pantry","200g pretzels@Pantry","200g peanuts@Pantry","50g butter@Dairy","1 jar smoked paprika@Pantry","800g skirt steak@Meat","2 limes@Produce","1 orange@Produce","3 garlic cloves@Produce","1 jar ground cumin@Pantry","24 corn tortillas@Bakery","1 onion@Produce","1 bunch coriander@Produce","1 jar salsa verde@Pantry","8 choc chip cookies@Bakery","1.5L vanilla ice cream@Frozen","1 jar sprinkles@Pantry","100g coffee beans@Pantry","200ml full cream milk@Dairy"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Last Action Hero (1993)":{"poster":"assets/menu-posters/last-action-hero-1993.jpg","colour":"#a33226","servings":4,"tagline":"Jack Slater. Pass the popcorn.","cue":"Serve the popcorn when Danny crashes into Jack Slater's movie.","menu":{"s":[{"n":"Magic ticket popcorn","note":"Brown butter popcorn in striped paper bags","how":"Cook 60g butter until golden and nutty. Heat 2 tbsp coconut oil with 3 kernels, then add 120g kernels once they pop, cover and shake until the popping slows. Toss with the brown butter and flaky salt and fill striped paper bags.","shop":["60g butter@Dairy","1 jar coconut oil@Pantry","120g popcorn kernels@Pantry","1 box sea salt flakes@Pantry"]},{"n":"Pandora Theatre hot dogs","note":"Blistered franks with mustard and sauce, wrapped in foil","how":"Simmer 8 franks for 5 minutes, then griddle until blistered. Steam 8 buns, fill with the franks and squeeze over yellow mustard and tomato sauce. Wrap each tightly in foil like a cinema candy bar would.","shop":["8 hot dog franks@Meat","8 hot dog buns@Bakery","1 bottle yellow mustard@Pantry","1 bottle tomato sauce@Pantry"]}],"m":[{"n":"Slater's LA rib eye","note":"Thick rib eye with garlic butter and a loaded baked potato","how":"Dry-brine 2 thick rib eyes overnight. Bake 4 potatoes at 200C for an hour. Sear the steaks, finish at 200C to 54C inside and rest. Top with 60g garlic butter, slice to share and load the potatoes with sour cream and 150g crispy bacon.","shop":["2 rib eye steaks@Meat","4 potatoes@Produce","60g butter@Dairy","2 garlic cloves@Produce","200g sour cream@Dairy","150g bacon@Meat"]}],"w":[{"n":"Matinee ice cream sundae","note":"Hot fudge sundaes with salted peanuts and a cherry","how":"Melt 150g dark chocolate with 150ml cream and 2 tbsp golden syrup. Scoop vanilla ice cream into four bowls, pour over the hot fudge and top with whipped cream, a handful of salted peanuts and a cherry.","shop":["150g dark chocolate@Pantry","300ml thickened cream@Dairy","1 tin golden syrup@Pantry","1L vanilla ice cream@Frozen","100g peanuts@Pantry","1 jar maraschino cherries@Pantry"]}],"d":[{"n":"Danny's chocolate milk","note":"Cold chocolate milk made from scratch","how":"Whisk 3 tbsp cocoa and 3 tbsp sugar into 150ml hot milk until smooth. Top up with 850ml cold milk and chill in the fridge for 30 minutes. Stir again and pour into four glasses.","shop":["1 tin cocoa@Pantry","1 bag caster sugar@Pantry","1L full cream milk@Dairy"]}],"shopping":["120g butter@Dairy","1 jar coconut oil@Pantry","120g popcorn kernels@Pantry","1 box sea salt flakes@Pantry","8 hot dog franks@Meat","8 hot dog buns@Bakery","1 bottle yellow mustard@Pantry","1 bottle tomato sauce@Pantry","2 rib eye steaks@Meat","4 potatoes@Produce","2 garlic cloves@Produce","200g sour cream@Dairy","150g bacon@Meat","150g dark chocolate@Pantry","300ml thickened cream@Dairy","1 tin golden syrup@Pantry","1L vanilla ice cream@Frozen","100g peanuts@Pantry","1 jar maraschino cherries@Pantry","1 tin cocoa@Pantry","1 bag caster sugar@Pantry","1L full cream milk@Dairy"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Airplane! (1980)":{"poster":"assets/menu-posters/airplane-1980.jpg","colour":"#315b86","servings":4,"tagline":"Fish or the steak? We had the lasagne.","cue":"Serve the mains right after the fish course takes out the crew.","menu":{"s":[{"n":"Flight deck snack tray","note":"Neat rows of cheese, crackers, grapes and cocktail onions","how":"Cut 200g cheddar into cubes. Thread cubes onto toothpicks with a green grape and a cocktail onion. Lay them out in neat rows on a tray beside a row of crackers, like an old airline snack service.","shop":["200g cheddar@Dairy","300g grapes@Produce","1 jar cocktail onions@Pantry","1 packet crackers@Pantry"]},{"n":"Airline peanuts","note":"Warm salted nuts in little packets","how":"Mix 200g dry-roasted peanuts and 100g almonds with a pinch of sugar and salt. Warm on a tray at 160C for 5 minutes. Cool slightly and divide into small paper packets, one for each passenger.","shop":["200g dry-roasted peanuts@Pantry","100g almonds@Pantry","1 box fine salt@Pantry"]}],"m":[{"n":"The steak, not the fish","note":"Peppercorn sirloin with mash and beans on a tray","how":"Sear 4 sirloins hard and rest. Crush 1 tbsp peppercorns into the pan, add 250ml cream and reduce until thick. Mash 1kg potatoes with butter and milk. Steam 300g green beans. Serve on trays, airline style.","shop":["4 sirloin steaks@Meat","1 jar black peppercorns@Pantry","250ml thickened cream@Dairy","1kg potatoes@Produce","60g butter@Dairy","100ml full cream milk@Dairy","300g green beans@Produce"]}],"w":[{"n":"Airline cheesecake","note":"Baked cheesecake slab in neat squares with a cherry","how":"Mix 250g crushed biscuits with 100g melted butter and press into a slab tin. Beat 750g cream cheese, 200g sugar, 3 eggs and 150g sour cream. Bake in a water bath at 150C for 50 minutes. Chill overnight, cut into squares and top each with a cherry.","shop":["250g digestive biscuits@Pantry","100g butter@Dairy","750g cream cheese@Dairy","200g caster sugar@Pantry","3 eggs@Dairy","150g sour cream@Dairy","200g cherries@Produce"]}],"d":[{"n":"Black coffee","note":"Drip coffee poured black, straight from the pot","how":"Brew 60g ground coffee with 1L water in a drip machine. Carry the pot around and pour into each cup black. Offer refills constantly, whether or not anyone has asked, and try not to spill it.","shop":["60g ground coffee@Pantry"]}],"shopping":["200g cheddar@Dairy","300g grapes@Produce","1 jar cocktail onions@Pantry","1 packet crackers@Pantry","200g dry-roasted peanuts@Pantry","100g almonds@Pantry","1 box fine salt@Pantry","4 sirloin steaks@Meat","1 jar black peppercorns@Pantry","250ml thickened cream@Dairy","1kg potatoes@Produce","160g butter@Dairy","100ml full cream milk@Dairy","300g green beans@Produce","250g digestive biscuits@Pantry","750g cream cheese@Dairy","200g caster sugar@Pantry","3 eggs@Dairy","150g sour cream@Dairy","200g cherries@Produce","60g ground coffee@Pantry"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"The Rock (1996)":{"poster":"assets/menu-posters/the-rock-1996.jpg","colour":"#244c56","servings":4,"tagline":"Welcome to the Rock.","cue":"Serve the snacks when Mason gets his haircut at the Fairmont.","menu":{"s":[{"n":"San Francisco sourdough","note":"Warm sourdough with salted butter and oil with dukkah","how":"Warm a sourdough loaf at 200C for 8 minutes and tear into chunks. Serve with 125g soft salted butter and a shallow dish of extra virgin olive oil with 3 tbsp dukkah scattered on top for dipping.","shop":["1 sourdough loaf@Bakery","125g salted butter@Dairy","1 bottle extra virgin olive oil@Pantry","1 jar dukkah@Pantry"]},{"n":"Fisherman's Wharf prawns","note":"Garlic chilli prawns in butter and white wine, with bread","how":"Heat 3 tbsp olive oil, add 5 sliced garlic cloves and 1 sliced chilli, then 600g peeled green prawns. Toss over high heat for 2 minutes. Add 60g butter, a splash of white wine and parsley. Serve with bread for the juices.","shop":["1 bottle extra virgin olive oil@Pantry","5 garlic cloves@Produce","1 red chilli@Produce","600g green prawns@Seafood","60g butter@Dairy","100ml white wine@Bottle shop","1 bunch parsley@Produce"]}],"m":[{"n":"Mason's Fairmont room service","note":"Butter-basted rib eye with béarnaise and frites","how":"Reduce 60ml white wine vinegar with tarragon to 2 tbsp, whisk with 3 yolks over low heat and drizzle in 200g warm clarified butter. Fry 1kg potato chips twice. Sear 4 rib eyes, baste with 40g butter, thyme and garlic, rest and serve.","shop":["60ml white wine vinegar@Pantry","1 bunch tarragon@Produce","3 eggs@Dairy","240g butter@Dairy","1kg potatoes@Produce","4 rib eye steaks@Meat","1 bunch thyme@Produce","2 garlic cloves@Produce","2L vegetable oil@Pantry"]}],"w":[{"n":"San Francisco chocolate squares","note":"Fudgy walnut chocolate squares with flaky salt","how":"Melt 200g dark chocolate with 150g butter. Whisk in 250g sugar and 3 eggs, then fold in 100g flour and 100g toasted walnuts. Bake in a lined tin at 175C for 25 minutes. Sprinkle with flaky salt, cool and cut into squares.","shop":["200g dark chocolate@Pantry","150g butter@Dairy","250g caster sugar@Pantry","3 eggs@Dairy","100g plain flour@Pantry","100g walnuts@Pantry","1 box sea salt flakes@Pantry"]}],"d":[{"n":"Single malt","note":"Single malt Scotch neat, with a few drops of water","how":"Pour 30ml single malt Scotch into each of four small tumblers. Add a few drops of water with a teaspoon to open it up. Sip slowly, the way a retired SAS man would after a long day.","shop":["120ml single malt Scotch@Bottle shop"]}],"shopping":["1 sourdough loaf@Bakery","125g salted butter@Dairy","1 bottle extra virgin olive oil@Pantry","1 jar dukkah@Pantry","7 garlic cloves@Produce","1 red chilli@Produce","600g green prawns@Seafood","450g butter@Dairy","100ml white wine@Bottle shop","1 bunch parsley@Produce","60ml white wine vinegar@Pantry","1 bunch tarragon@Produce","6 eggs@Dairy","1kg potatoes@Produce","4 rib eye steaks@Meat","1 bunch thyme@Produce","2L vegetable oil@Pantry","200g dark chocolate@Pantry","250g caster sugar@Pantry","100g plain flour@Pantry","100g walnuts@Pantry","1 box sea salt flakes@Pantry","120ml single malt Scotch@Bottle shop"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Face/Off (1997)":{"poster":"assets/menu-posters/face-off-1997.jpg","colour":"#ad552c","servings":4,"tagline":"Two faces. One dinner.","cue":"Serve the mains when the prison boots go on.","menu":{"s":[{"n":"Church canapés","note":"Smoked salmon on buttered rye with crème fraîche and dill","how":"Butter 6 slices rye bread and cut into small squares. Top each with a fold of smoked salmon, using 200g in total, a small spoon of crème fraîche, a dill sprig and a crack of black pepper. Serve cold on a tray.","shop":["6 slices rye bread@Bakery","30g butter@Dairy","200g smoked salmon@Seafood","100ml crème fraîche@Dairy","1 bunch dill@Produce"]},{"n":"Peach slices","note":"Ripe peach wedges with warm honey, lime and mint","how":"Cut 4 ripe peaches into wedges and arrange on a plate. Warm 2 tbsp honey with the juice of a lime and drizzle over. Scatter with torn mint and a small pinch of flaky salt. Serve straight away.","shop":["4 peaches@Produce","1 jar honey@Pantry","1 lime@Produce","1 bunch mint@Produce","1 box sea salt flakes@Pantry"]}],"m":[{"n":"Castor's lavish dinner","note":"Garlic butter lobster tails with a sharp green salad","how":"Split 4 lobster tails lengthways. Brush with 80g butter melted with 2 garlic cloves and chopped parsley. Grill flesh side up for 6 to 8 minutes until just white. Toss salad leaves with a lemon and olive oil vinaigrette and serve alongside.","shop":["4 lobster tails@Seafood","80g butter@Dairy","2 garlic cloves@Produce","1 bunch parsley@Produce","2 lemons@Produce","150g salad leaves@Produce","1 bottle extra virgin olive oil@Pantry"]}],"w":[{"n":"Peach cobbler","note":"Warm cinnamon peaches under a buttery biscuit topping","how":"Toss 6 sliced peaches with 80g sugar, lemon juice and 1 tsp cinnamon in a baking dish. Rub 80g butter into 200g self-raising flour, stir in 150ml buttermilk and drop spoonfuls over the fruit. Bake at 190C for 35 minutes.","shop":["6 peaches@Produce","80g caster sugar@Pantry","1 lemon@Produce","1 jar cinnamon@Pantry","80g butter@Dairy","200g self-raising flour@Pantry","150ml buttermilk@Dairy"]}],"d":[{"n":"Champagne","note":"Brut champagne, chilled and poured into flutes","how":"Chill a 750ml bottle of brut champagne in an ice bucket with ice and water for 30 minutes. Open it gently so it hisses rather than pops. Pour slowly into four flutes and let the foam settle before topping up.","shop":["750ml champagne@Bottle shop"]}],"shopping":["6 slices rye bread@Bakery","190g butter@Dairy","200g smoked salmon@Seafood","100ml crème fraîche@Dairy","1 bunch dill@Produce","10 peaches@Produce","1 jar honey@Pantry","1 lime@Produce","1 bunch mint@Produce","1 box sea salt flakes@Pantry","4 lobster tails@Seafood","2 garlic cloves@Produce","1 bunch parsley@Produce","2 lemons@Produce","150g salad leaves@Produce","1 bottle extra virgin olive oil@Pantry","80g caster sugar@Pantry","1 lemon@Produce","1 jar cinnamon@Pantry","200g self-raising flour@Pantry","150ml buttermilk@Dairy","750ml champagne@Bottle shop"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Cliffhanger (1993)":{"poster":"assets/menu-posters/cliffhanger-1993.jpg","colour":"#2c5571","servings":4,"tagline":"Hang on to your dinner.","cue":"Serve the mains when the money cases fall from the plane.","menu":{"s":[{"n":"Mountain trail mix","note":"Nuts, apricots, dark chocolate and pepitas for the climb","how":"Toss 200g mixed nuts, 100g chopped dried apricots, 100g dark chocolate chunks and 50g pepitas with a pinch of sea salt. Divide into four zip bags or a big bowl. Keep it handy for the long haul.","shop":["200g mixed nuts@Pantry","100g dried apricots@Pantry","100g dark chocolate@Pantry","50g pepitas@Pantry"]},{"n":"Ranger hut soup","note":"Creamy roast pumpkin soup poured from a thermos","how":"Roast 1kg diced pumpkin at 200C for 30 minutes. Soften 1 onion and 2 garlic cloves, add the pumpkin and 750ml stock and simmer 10 minutes. Blitz smooth, stir in 100ml cream and pour into a warmed thermos.","shop":["1kg pumpkin@Produce","1 brown onion@Produce","2 garlic cloves@Produce","750ml chicken stock@Pantry","100ml thickened cream@Dairy"]}],"m":[{"n":"Campfire steak","note":"Rosemary rump grilled over coals with foil-baked potatoes","how":"Wrap 4 potatoes with a knob of butter each in foil and bake in the coals for 45 minutes. Rub 4 rump steaks with salt, pepper and chopped rosemary. Grill over hot coals for 4 minutes a side and rest on a board.","shop":["4 potatoes@Produce","60g butter@Dairy","4 rump steaks@Meat","1 bunch rosemary@Produce"]}],"w":[{"n":"Hot chocolate brownies","note":"Warm fudgy brownies with hot chocolate sauce","how":"Melt 200g dark chocolate with 150g butter. Whisk in 250g sugar and 3 eggs, then fold in 80g flour and 30g cocoa. Bake at 175C for 25 minutes. Melt 100g chocolate with 150ml cream and pour over the warm brownies at the table.","shop":["300g dark chocolate@Pantry","150g butter@Dairy","250g caster sugar@Pantry","3 eggs@Dairy","80g plain flour@Pantry","30g cocoa@Pantry","150ml thickened cream@Dairy"]}],"d":[{"n":"Summit hot chocolate","note":"Frothy dark hot chocolate with a pinch of salt","how":"Heat 1L milk until steaming. Whisk in 150g chopped dark chocolate and a pinch of salt until melted and frothy. Pour into four mugs and drink while it's hot, wrapped in a blanket.","shop":["1L full cream milk@Dairy","150g dark chocolate@Pantry"]}],"shopping":["200g mixed nuts@Pantry","100g dried apricots@Pantry","550g dark chocolate@Pantry","50g pepitas@Pantry","1kg pumpkin@Produce","1 brown onion@Produce","2 garlic cloves@Produce","750ml chicken stock@Pantry","250ml thickened cream@Dairy","4 potatoes@Produce","210g butter@Dairy","4 rump steaks@Meat","1 bunch rosemary@Produce","250g caster sugar@Pantry","3 eggs@Dairy","80g plain flour@Pantry","30g cocoa@Pantry","1L full cream milk@Dairy"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Back to the Future Part II (1989)":{"poster":"assets/menu-posters/back-to-the-future-part-ii-1989.jpg","colour":"#385c8b","servings":4,"tagline":"Hoverboards and hydrated pizza.","cue":"Serve the mains when Lorraine puts the tiny pizza in the hydrator.","menu":{"s":[{"n":"Cafe 80's fries","note":"Spiral curly fries with smoked paprika salt","how":"Spiralise 4 large potatoes and soak in cold water for 30 minutes. Dry very well on tea towels. Fry at 180C in batches until crisp and golden. Toss with fine salt mixed with 1 tsp smoked paprika and serve hot.","shop":["4 potatoes@Produce","2L vegetable oil@Pantry","1 box fine salt@Pantry","1 jar smoked paprika@Pantry"]},{"n":"Hoverboard tortilla chips","note":"Pink hoverboard tortilla chips with guacamole","how":"Cut 6 flour tortillas into hoverboard shapes. Fry at 180C until crisp and toss with salt and 1 tsp beetroot powder for a pink colour. Mash 3 avocados with the juice of a lime and salt for guacamole.","shop":["6 flour tortillas@Bakery","1L vegetable oil@Pantry","1 jar beetroot powder@Pantry","3 avocados@Produce","1 lime@Produce"]}],"m":[{"n":"Hydrated pizza","note":"Thin New York pepperoni pizza after a quick mini pizza reveal","how":"Bake 4 mini pizza bases with sauce and cheese for the reveal. Then stretch 500g dough thin, spread with 200g crushed tomatoes, add 250g low-moisture mozzarella and 100g pepperoni, and bake on a hot steel at max heat for 7 minutes.","shop":["4 mini pizza bases@Bakery","500g pizza dough@Bakery","200g crushed tomatoes@Pantry","300g low-moisture mozzarella@Dairy","100g pepperoni@Deli"]}],"w":[{"n":"Jaws 19 shark jelly","note":"Blue jelly with gummy sharks swimming in it","how":"Make 2 packets blue jelly crystals with 500ml boiling and 500ml cold water. Pour halfway into four glasses and chill until just starting to set. Push in gummy sharks, add the rest of the jelly and set. Top with whipped cream waves.","shop":["2 packets blue jelly crystals@Pantry","1 bag gummy sharks@Pantry","200ml thickened cream@Dairy"]}],"d":[{"n":"Cafe 80's milkshake","note":"Thick strawberry milkshake with fresh strawberries","how":"For each shake, blend 3 scoops strawberry ice cream with 4 strawberries and 150ml cold milk until thick. Pour into a tall chilled glass with a straw. Make four one after the other so they stay thick.","shop":["1.5L strawberry ice cream@Frozen","250g strawberries@Produce","600ml full cream milk@Dairy"]}],"shopping":["4 potatoes@Produce","3L vegetable oil@Pantry","1 box fine salt@Pantry","1 jar smoked paprika@Pantry","6 flour tortillas@Bakery","1 jar beetroot powder@Pantry","3 avocados@Produce","1 lime@Produce","4 mini pizza bases@Bakery","500g pizza dough@Bakery","200g crushed tomatoes@Pantry","300g low-moisture mozzarella@Dairy","100g pepperoni@Deli","2 packets blue jelly crystals@Pantry","1 bag gummy sharks@Pantry","200ml thickened cream@Dairy","1.5L strawberry ice cream@Frozen","250g strawberries@Produce","600ml full cream milk@Dairy"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"I Am Legend (2007)":{"poster":"assets/menu-posters/i-am-legend-2007.jpg","colour":"#596346","servings":4,"tagline":"Last man in New York. Last tin of peaches.","cue":"Serve the snacks when Robert and Sam go hunting deer in Times Square.","menu":{"s":[{"n":"Central Park corn chips","note":"Corn tortilla chips with fresh corn and tomato salsa","how":"Cut 12 corn tortillas into wedges and fry at 180C until crisp, then salt. Char 2 corn cobs and cut off the kernels. Mix with 3 diced tomatoes, chopped coriander and the juice of 2 limes. Serve the salsa in a bowl with the chips.","shop":["12 corn tortillas@Bakery","1L vegetable oil@Pantry","2 corn cobs@Produce","3 tomatoes@Produce","1 bunch coriander@Produce","2 limes@Produce"]},{"n":"Tinned peaches","note":"Grilled tinned peaches with honey yoghurt","how":"Drain 2 tins of peach halves and pat dry. Grill cut side down in a hot pan for 3 minutes until caramelised. Serve warm with a spoon of Greek yoghurt mixed with honey, about 200g yoghurt in total.","shop":["2 tins peach halves@Pantry","200g Greek yoghurt@Dairy","1 jar honey@Pantry"]}],"m":[{"n":"Pan-fried steak","note":"Garlic and thyme basted sirloin, with a plain bit for the dog","how":"Season 4 sirloins well and sear in a hot pan for 3 minutes a side. Add 50g butter, 2 crushed garlic cloves and thyme and baste for a minute. Rest 5 minutes and slice. Keep a plain unseasoned piece aside for the dog.","shop":["4 sirloin steaks@Meat","50g butter@Dairy","2 garlic cloves@Produce","1 bunch thyme@Produce"]}],"w":[{"n":"Peach cobbler","note":"Brown sugar peaches under a buttermilk biscuit topping","how":"Drain 2 tins sliced peaches and toss with 60g brown sugar and 1 tsp cinnamon in a baking dish. Rub 80g butter into 200g self-raising flour, stir in 150ml buttermilk and drop spoonfuls over the fruit. Bake at 190C for 35 minutes.","shop":["2 tins sliced peaches@Pantry","60g brown sugar@Pantry","1 jar cinnamon@Pantry","80g butter@Dairy","200g self-raising flour@Pantry","150ml buttermilk@Dairy"]}],"d":[{"n":"Bourbon on the bench","note":"Bourbon neat, or bottled water for the long night","how":"Pour 45ml bourbon neat into each of four tumblers. Put a few bottles of spring water on the bench for anyone who wants to keep a clear head. Lock the door before you pour.","shop":["180ml bourbon@Bottle shop","4 bottles spring water@Drinks"]}],"shopping":["12 corn tortillas@Bakery","1L vegetable oil@Pantry","2 corn cobs@Produce","3 tomatoes@Produce","1 bunch coriander@Produce","2 limes@Produce","2 tins peach halves@Pantry","200g Greek yoghurt@Dairy","1 jar honey@Pantry","4 sirloin steaks@Meat","130g butter@Dairy","2 garlic cloves@Produce","1 bunch thyme@Produce","2 tins sliced peaches@Pantry","60g brown sugar@Pantry","1 jar cinnamon@Pantry","200g self-raising flour@Pantry","150ml buttermilk@Dairy","180ml bourbon@Bottle shop","4 bottles spring water@Drinks"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"The Terminator (1984)":{"poster":"assets/menu-posters/the-terminator-1984.jpg","colour":"#273b62","servings":4,"tagline":"I'll be back. With dessert.","cue":"Serve the mains when Sarah's waitress shift goes wrong at Big Jeff's.","menu":{"s":[{"n":"Big Jeff's fries","note":"Thin golden fries with sauce in a squeeze bottle","how":"Cut 1kg russets into thin fries and soak for 30 minutes, then dry well. Fry at 140C for 5 minutes, rest, then at 190C until golden. Salt straight away and serve with tomato sauce in a squeeze bottle.","shop":["1kg russet potatoes@Produce","2L vegetable oil@Pantry","1 bottle tomato sauce@Pantry"]},{"n":"Tech Noir bar nachos","note":"Baked nachos with refried beans, cheddar and jalapeños","how":"Spread a 300g bag of corn chips on a tray and dot with a tin of refried beans. Scatter with 200g grated cheddar and sliced jalapeños. Bake at 200C for 8 minutes and top with sour cream and a jar of salsa.","shop":["300g corn chips@Pantry","1 tin refried beans@Pantry","200g cheddar@Dairy","1 jar jalapeños@Pantry","200g sour cream@Dairy","1 jar salsa@Pantry"]}],"m":[{"n":"Big Jeff's burger","note":"Classic diner cheeseburger with the works","how":"Shape 800g chuck mince into 4 thick patties, season just before cooking and griddle to medium. Melt cheddar on top under a lid. Build on toasted buns with shredded iceberg, sliced tomato, onion and pickles.","shop":["800g beef chuck mince@Meat","4 slices cheddar@Dairy","0.5 iceberg lettuce@Produce","2 tomatoes@Produce","1 onion@Produce","1 jar dill pickles@Pantry","4 burger buns@Bakery"]}],"w":[{"n":"Big Jeff's cherry pie","note":"Lattice-topped cherry pie, the slice everyone at the diner orders","how":"Toss 800g pitted cherries, fresh or frozen, with 150g sugar, the juice of a lemon and 3 tbsp cornflour. Line a pie dish with 2 sheets sweet shortcrust, fill and weave a lattice from 2 more. Bake at 190C for 50 minutes.","shop":["800g cherries@Frozen","150g caster sugar@Pantry","1 box cornflour@Pantry","1 lemon@Produce","4 sheets sweet shortcrust pastry@Frozen"]}],"d":[{"n":"Diner coffee","note":"Drip coffee in diner mugs, milk and sugar on the table","how":"Brew 60g ground coffee with 1L water in a drip machine. Pour into heavy diner mugs and leave a jug of milk and the sugar bowl on the table. Refill whenever a mug is half empty.","shop":["60g ground coffee@Pantry","200ml full cream milk@Dairy","1 bag caster sugar@Pantry"]}],"shopping":["1kg russet potatoes@Produce","2L vegetable oil@Pantry","1 bottle tomato sauce@Pantry","300g corn chips@Pantry","1 tin refried beans@Pantry","200g cheddar@Dairy","1 jar jalapeños@Pantry","200g sour cream@Dairy","1 jar salsa@Pantry","800g beef chuck mince@Meat","4 slices cheddar@Dairy","0.5 iceberg lettuce@Produce","2 tomatoes@Produce","1 onion@Produce","1 jar dill pickles@Pantry","4 burger buns@Bakery","800g cherries@Frozen","150g caster sugar@Pantry","1 box cornflour@Pantry","1 lemon@Produce","4 sheets sweet shortcrust pastry@Frozen","60g ground coffee@Pantry","200ml full cream milk@Dairy"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"RoboCop (1987)":{"poster":"assets/menu-posters/robocop-1987.jpg","colour":"#304d66","servings":4,"tagline":"I'd buy that for a dollar.","cue":"Serve the snacks every time I'd buy that for a dollar comes on the TV.","menu":{"s":[{"n":"6000 SUX popcorn","note":"Buttery popcorn with a heavy cheese powder dusting","how":"Pop 120g kernels in 2 tbsp oil. Toss with 50g melted butter, then 4 tbsp cheddar cheese powder, 1 tsp smoked paprika and a pinch of salt until every piece is orange. Serve in a big bowl.","shop":["120g popcorn kernels@Pantry","1 bottle vegetable oil@Pantry","50g butter@Dairy","1 jar cheddar cheese powder@Pantry","1 jar smoked paprika@Pantry"]},{"n":"OCP boardroom canapés","note":"Smoked salmon rye and whipped feta cucumber cups","how":"Butter 4 slices rye bread, cut into squares and top with 150g smoked salmon, crème fraîche and dill. Cut 2 cucumbers into thick rounds, scoop a little hollow and fill with 150g feta whipped with a splash of olive oil.","shop":["4 slices rye bread@Bakery","20g butter@Dairy","150g smoked salmon@Seafood","100ml crème fraîche@Dairy","1 bunch dill@Produce","2 Lebanese cucumbers@Produce","150g feta@Deli"]}],"m":[{"n":"Detroit coney dog","note":"Franks with loose coney chilli, mustard and diced onion","how":"Brown 300g beef mince with half a diced onion, 2 tsp chilli powder and 1 tsp cumin. Add 200ml water and simmer 20 minutes until loose. Griddle 8 franks, put in steamed buns and top with chilli, mustard and diced white onion.","shop":["300g beef mince@Meat","2 onions@Produce","1 jar chilli powder@Pantry","1 jar ground cumin@Pantry","8 hot dog franks@Meat","8 hot dog buns@Bakery","1 bottle yellow mustard@Pantry"]}],"w":[{"n":"Nukem cupcakes","note":"Chocolate cupcakes under a torched mushroom-cloud meringue","how":"Beat 125g butter and 150g sugar, add 2 eggs, then fold in 175g self-raising flour, 30g cocoa and 125ml milk. Bake 12 cupcakes at 180C for 18 minutes. Whisk 3 whites and 150g sugar over hot water, beat to stiff peaks, pipe tall and torch.","shop":["125g butter@Dairy","300g caster sugar@Pantry","5 eggs@Dairy","175g self-raising flour@Pantry","30g cocoa@Pantry","125ml full cream milk@Dairy"]}],"d":[{"n":"Gas station lager","note":"Ice-cold American lager straight from the can","how":"Chill eight 375ml cans of American lager for at least three hours, or in a bucket of ice and water for 30 minutes. Hand them out and drink straight from the can, no glasses.","shop":["8 375ml cans American lager@Bottle shop"]}],"shopping":["120g popcorn kernels@Pantry","1 bottle vegetable oil@Pantry","195g butter@Dairy","1 jar cheddar cheese powder@Pantry","1 jar smoked paprika@Pantry","4 slices rye bread@Bakery","150g smoked salmon@Seafood","100ml crème fraîche@Dairy","1 bunch dill@Produce","2 Lebanese cucumbers@Produce","150g feta@Deli","300g beef mince@Meat","2 onions@Produce","1 jar chilli powder@Pantry","1 jar ground cumin@Pantry","8 hot dog franks@Meat","8 hot dog buns@Bakery","1 bottle yellow mustard@Pantry","300g caster sugar@Pantry","5 eggs@Dairy","175g self-raising flour@Pantry","30g cocoa@Pantry","125ml full cream milk@Dairy","8 375ml cans American lager@Bottle shop"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Three Men and a Baby (1987)":{"poster":"assets/menu-posters/three-men-and-a-baby-1987.jpg","colour":"#263e61","servings":4,"tagline":"Three bachelors. One baby. Zero clue.","cue":"Serve dessert when the guys sing the baby to sleep.","menu":{"s":[{"n":"Bachelor pad cheese board","note":"Cheddar, brie and blue with crackers, grapes and fig paste.","how":"Take 150g aged cheddar, 150g brie and 120g blue cheese out of the fridge an hour before serving. Arrange on a board with 150g crackers, a bunch of grapes and 100g fig paste.","shop":["150g aged cheddar@Deli","150g brie@Deli","120g blue cheese@Deli","150g crackers@Pantry","500g grapes@Produce","100g fig paste@Deli"]},{"n":"Bagel chips and schmear","note":"Crisp bagel chips with chive and lemon cream cheese.","how":"Slice 3 day-old bagels into thin rounds, brush with 2 tbsp olive oil and bake at 180C for 12 minutes until crisp. Beat 250g cream cheese with 2 tbsp chopped chives and the zest of 1 lemon. Serve the chips around the schmear.","shop":["3 bagels@Bakery","2 tbsp olive oil@Pantry","250g cream cheese@Dairy","1 bunch chives@Produce","1 lemon@Produce"]}],"m":[{"n":"Peter's loft steak sandwich","note":"Sliced sirloin, slow onions and melted Swiss on sourdough with horseradish mayo.","how":"Cook 2 sliced brown onions in butter over low heat for 30 minutes. Sear 600g sirloin steak hard for 3 minutes a side, rest and slice thin. Mix 80g mayonnaise with 1 tbsp horseradish. Toast 8 slices sourdough, spread with the mayo, pile on steak and onions, lay 4 slices Swiss cheese on top and grill until melted.","shop":["2 brown onions@Produce","20g butter@Dairy","600g sirloin steak@Meat","80g mayonnaise@Pantry","1 tbsp horseradish@Pantry","8 slices sourdough@Bakery","4 slices Swiss cheese@Deli"]}],"w":[{"n":"Baby Mary's vanilla custard","note":"Smooth homemade vanilla custard, warm or chilled.","how":"Heat 500ml milk with a split vanilla bean until steaming. Whisk 4 egg yolks with 60g caster sugar and 2 tbsp cornflour, pour on the hot milk, then return to the pan and stir over low heat until thick. Serve warm, or chill with plastic pressed on the surface.","shop":["500ml full cream milk@Dairy","1 vanilla bean@Pantry","4 eggs@Dairy","60g caster sugar@Pantry","2 tbsp cornflour@Pantry"]}],"d":[{"n":"Warm milk or a cold beer","note":"Honey nutmeg milk for the baby schedule, cold lager for the dads.","how":"Warm 500ml full cream milk with 1 tbsp honey and a pinch of nutmeg for anyone keeping the baby's hours. For the three dads, chill 3 bottles of lager and serve ice cold.","shop":["500ml full cream milk@Dairy","1 tbsp honey@Pantry","1 pinch nutmeg@Pantry","3 bottles lager@Bottle shop"]}],"shopping":["150g aged cheddar@Deli","150g brie@Deli","120g blue cheese@Deli","150g crackers@Pantry","500g grapes@Produce","100g fig paste@Deli","3 bagels@Bakery","2 tbsp olive oil@Pantry","250g cream cheese@Dairy","1 bunch chives@Produce","1 lemon@Produce","2 brown onions@Produce","20g butter@Dairy","600g sirloin steak@Meat","80g mayonnaise@Pantry","1 tbsp horseradish@Pantry","8 slices sourdough@Bakery","4 slices Swiss cheese@Deli","1L full cream milk@Dairy","1 vanilla bean@Pantry","4 eggs@Dairy","60g caster sugar@Pantry","2 tbsp cornflour@Pantry","1 tbsp honey@Pantry","1 pinch nutmeg@Pantry","3 bottles lager@Bottle shop"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Trading Places (1983)":{"poster":"assets/menu-posters/trading-places-1983.jpg","colour":"#214d36","servings":4,"tagline":"One dollar bet. One very big swap.","cue":"Serve the mains during the New Year's Eve train party.","menu":{"s":[{"n":"Duke & Duke club canapés","note":"Almond-stuffed prunes wrapped in crisp streaky bacon.","how":"Push an almond into each of 20 pitted prunes. Wrap each in half a rasher of streaky bacon, using 10 rashers, and secure with a toothpick. Bake at 200C for 15 minutes until the bacon is crisp. Serve warm.","shop":["20 pitted prunes@Pantry","20 almonds@Pantry","10 rashers streaky bacon@Meat"]},{"n":"Frozen orange juice shots","note":"Icy orange juice slush with a splash of vodka.","how":"Blend 500ml orange juice with 2 cups ice and 80ml vodka until slushy. Pour into shot glasses and serve straight away, before the market closes. Leave out the vodka for anyone not drinking.","shop":["500ml orange juice@Drinks","80ml vodka@Bottle shop","500g ice@Frozen"]}],"m":[{"n":"Billy Ray's club dinner","note":"Slow-roasted rib roast with jus, horseradish cream and potatoes.","how":"Salt a 2kg standing rib roast the day before and leave uncovered in the fridge. Roast at 120C until 52C inside, about 2.5 hours, rest 30 minutes, then blast at 260C for 8 minutes for a crust. Simmer the pan juices with 300ml beef stock for jus. Serve with 150g horseradish cream and 1kg roast potatoes.","shop":["2kg standing rib roast@Meat","300ml beef stock@Pantry","150g horseradish cream@Pantry","1kg potatoes@Produce"]}],"w":[{"n":"Orange cake","note":"Orange butter cake soaked in a sticky orange glaze.","how":"Beat 200g butter, 200g caster sugar and the zest of 2 oranges, add 3 eggs and fold in 250g self-raising flour with 100ml orange juice. Bake in a lined tin at 170C for 45 minutes. Boil 100ml orange juice concentrate with 50g sugar for 3 minutes and brush over the warm cake.","shop":["200g butter@Dairy","250g caster sugar@Pantry","2 oranges@Produce","3 eggs@Dairy","250g self-raising flour@Pantry","100ml orange juice@Drinks","100ml orange juice concentrate@Frozen"]}],"d":[{"n":"Mimosa","note":"Fresh orange juice and chilled sparkling wine in flutes.","how":"Squeeze 4 oranges, about 300ml juice, and chill well. Fill four flutes halfway with the juice and gently top with chilled sparkling wine, about 300ml in total, pouring slowly so it does not foam over.","shop":["4 oranges@Produce","750ml sparkling wine@Bottle shop"]}],"shopping":["20 pitted prunes@Pantry","20 almonds@Pantry","10 rashers streaky bacon@Meat","600ml orange juice@Drinks","80ml vodka@Bottle shop","500g ice@Frozen","2kg standing rib roast@Meat","300ml beef stock@Pantry","150g horseradish cream@Pantry","1kg potatoes@Produce","200g butter@Dairy","250g caster sugar@Pantry","6 oranges@Produce","3 eggs@Dairy","250g self-raising flour@Pantry","100ml orange juice concentrate@Frozen","750ml sparkling wine@Bottle shop"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Tootsie (1982)":{"poster":"assets/menu-posters/tootsie-1982.jpg","colour":"#982b36","servings":4,"tagline":"He's not a she. But she can cook.","cue":"Serve the mains when Dorothy demands the script be changed.","menu":{"s":[{"n":"Soap studio green room sandwiches","note":"Egg and cress and cucumber sandwiches, crusts off, in triangles","how":"Boil 4 eggs for 10 minutes, cool, mash with 2 tbsp mayo and a handful of cress. Spread 150g cream cheese on bread and layer with thin cucumber. Use 12 slices soft white bread in total, cut off the crusts and cut into triangles.","shop":["4 eggs@Dairy","1 jar mayonnaise@Pantry","1 punnet cress@Produce","150g cream cheese@Dairy","1 Lebanese cucumber@Produce","12 slices white bread@Bakery"]},{"n":"Audition crackers","note":"Seeded crackers with whipped feta and roasted capsicum dip","how":"Roast 2 red capsicums at 220C for 30 minutes, peel and seed. Blitz with 200g feta, 150g Greek yoghurt and a pinch of chilli flakes until smooth. Spoon into a bowl, drizzle with oil and serve with seeded crackers.","shop":["2 red capsicums@Produce","200g feta@Deli","150g Greek yoghurt@Dairy","1 jar chilli flakes@Pantry","1 packet seeded crackers@Pantry"]}],"m":[{"n":"Les's farm roast chicken","note":"Lemon butter roast chicken with potatoes roasted in the fat","how":"Dry-brine a 1.8kg chicken overnight. Push 50g butter mixed with lemon zest and thyme under the skin. Roast at 220C for 20 minutes then 180C for 50 minutes, with 1kg halved potatoes in the tray. Rest 15 minutes before carving.","shop":["1.8kg whole chicken@Meat","50g butter@Dairy","2 lemons@Produce","1 bunch thyme@Produce","1kg potatoes@Produce"]}],"w":[{"n":"Strawberry shortcake","note":"Cream scones split and filled with strawberries and whipped cream","how":"Mix 300g self-raising flour with 200ml cream and 2 tbsp sugar to a soft dough. Pat out, cut 4 rounds and bake at 220C for 12 minutes. Toss 500g sliced strawberries with 2 tbsp sugar. Whip 200ml cream softly, split the scones and fill.","shop":["300g self-raising flour@Pantry","400ml thickened cream@Dairy","50g caster sugar@Pantry","500g strawberries@Produce"]}],"d":[{"n":"Iced tea","note":"Strong sweet black tea over ice with lemon and mint","how":"Steep 6 black tea bags in 1L just-boiled water for 5 minutes, remove and stir in 80g sugar while hot. Chill completely. Pour over ice in four tall glasses with lemon slices and a sprig of mint in each.","shop":["1 box black tea bags@Drinks","80g caster sugar@Pantry","2 lemons@Produce","1 bunch mint@Produce"]}],"shopping":["4 eggs@Dairy","1 jar mayonnaise@Pantry","1 punnet cress@Produce","150g cream cheese@Dairy","1 Lebanese cucumber@Produce","12 slices white bread@Bakery","2 red capsicums@Produce","200g feta@Deli","150g Greek yoghurt@Dairy","1 jar chilli flakes@Pantry","1 packet seeded crackers@Pantry","1.8kg whole chicken@Meat","50g butter@Dairy","4 lemons@Produce","1 bunch thyme@Produce","1kg potatoes@Produce","300g self-raising flour@Pantry","400ml thickened cream@Dairy","130g caster sugar@Pantry","500g strawberries@Produce","1 box black tea bags@Drinks","1 bunch mint@Produce"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Men in Black (1997)":{"poster":"assets/menu-posters/men-in-black-1997.jpg","colour":"#223d58","servings":4,"tagline":"Protecting Earth from the worst snacks in the universe.","cue":"Serve the drinks when Edgar starts demanding sugar water.","menu":{"s":[{"n":"Bug-eyed devilled eggs","note":"Devilled eggs with an olive slice eye staring up","how":"Boil 8 eggs for 10 minutes, cool and halve. Mash the yolks with 3 tbsp mayo, 1 tsp Dijon and a pinch of cayenne. Pipe back into the whites and press a black olive slice on each so they stare up at you.","shop":["8 eggs@Dairy","1 jar mayonnaise@Pantry","1 jar Dijon mustard@Pantry","1 jar black olives@Pantry"]},{"n":"Black bean dip","note":"Smoky black bean dip with feta, coriander and corn chips","how":"Blitz 2 drained tins black beans with 2 garlic cloves, juice of 2 limes, 1 tsp cumin and 1 chipotle in adobo until smooth. Spoon into a bowl and top with 80g crumbled feta and coriander. Serve with corn chips.","shop":["2 tins black beans@Pantry","2 garlic cloves@Produce","2 limes@Produce","1 jar ground cumin@Pantry","1 tin chipotle in adobo@Pantry","80g feta@Deli","1 bunch coriander@Produce","1 bag corn chips@Pantry"]}],"m":[{"n":"Black suit burgers","note":"Cheeseburgers on black buns with pickles and burger sauce","how":"Shape 800g beef mince into 4 patties and griddle to medium. Melt a slice of cheddar on each under a lid. Mix 100g mayo with chopped pickle and a little mustard for sauce. Serve on toasted charcoal buns with extra pickles.","shop":["800g beef mince@Meat","4 charcoal burger buns@Bakery","4 slices cheddar@Dairy","1 jar dill pickles@Pantry","1 jar mayonnaise@Pantry"]}],"w":[{"n":"Neuralyser cake pops","note":"Cake pops dipped in white chocolate and brushed silver","how":"Crumble a 500g butter cake and mix with 100g cream cheese icing until it holds together. Roll into 16 balls, push in sticks and chill an hour. Dip in 300g melted white chocolate, set, then brush with silver lustre dust.","shop":["1 butter cake@Bakery","100g cream cheese@Dairy","50g icing sugar@Pantry","300g white chocolate@Pantry","1 jar silver lustre dust@Pantry"]}],"d":[{"n":"Sugar water","note":"Very sweet homemade lemonade, the alien favourite","how":"Make a syrup of 150g caster sugar dissolved in 150ml hot water and cool. Stir with the juice of 4 lemons and 1L cold water. Serve over ice in four glasses with a lemon slice each. Taste and add more syrup if needed.","shop":["150g caster sugar@Pantry","5 lemons@Produce"]}],"shopping":["8 eggs@Dairy","1 jar mayonnaise@Pantry","1 jar Dijon mustard@Pantry","1 jar black olives@Pantry","2 tins black beans@Pantry","2 garlic cloves@Produce","2 limes@Produce","1 jar ground cumin@Pantry","1 tin chipotle in adobo@Pantry","80g feta@Deli","1 bunch coriander@Produce","1 bag corn chips@Pantry","800g beef mince@Meat","4 charcoal burger buns@Bakery","4 slices cheddar@Dairy","1 jar dill pickles@Pantry","1 butter cake@Bakery","100g cream cheese@Dairy","50g icing sugar@Pantry","300g white chocolate@Pantry","1 jar silver lustre dust@Pantry","150g caster sugar@Pantry","5 lemons@Produce"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Kate & Leopold (2001)":{"poster":"assets/menu-posters/kate-leopold-2001.jpg","colour":"#725630","servings":4,"tagline":"A duke from 1876 discovers modern margarine.","cue":"Serve dinner when Leopold sets up the rooftop dinner.","menu":{"s":[{"n":"Rooftop crostini","note":"Goat's cheese crostini with poached pear, honey and thyme","how":"Slice a baguette thin on the bias, brush with oil and toast at 200C for 8 minutes. Poach 2 sliced pears in simmering water with honey for 5 minutes. Spread toasts with 150g whipped goat's cheese, top with pear and drizzle with honey and thyme.","shop":["1 baguette@Bakery","150g goat's cheese@Deli","2 pears@Produce","1 jar honey@Pantry","1 bunch thyme@Produce"]},{"n":"Brooklyn Bridge pretzels","note":"Soft salted pretzels warmed through, with sharp grain mustard","how":"Brush 4 soft pretzels with 30g melted butter and sprinkle with coarse salt. Warm on a tray at 200C for 5 minutes until the crust is glossy. Serve warm on a board with a bowl of wholegrain mustard for dipping.","shop":["4 soft pretzels@Bakery","30g butter@Dairy","1 box rock salt@Pantry","1 jar wholegrain mustard@Pantry"]}],"m":[{"n":"Leopold's rooftop dinner","note":"Whole roast snapper with fennel, beurre blanc and new potatoes","how":"Score a 1.5kg snapper, stuff with lemon slices, sliced fennel and dill, then roast at 220C for 25 minutes. Boil 800g new potatoes. Reduce 1 shallot with 100ml white wine and 2 tbsp vinegar, then whisk in 150g cold butter cube by cube.","shop":["1.5kg whole snapper@Seafood","2 lemons@Produce","1 fennel bulb@Produce","1 bunch dill@Produce","800g new potatoes@Produce","1 shallot@Produce","100ml white wine@Bottle shop","1 bottle white wine vinegar@Pantry","150g butter@Dairy"]}],"w":[{"n":"Chocolate mousse","note":"Dark chocolate mousse set in glasses","how":"Melt 200g dark chocolate with 30g butter. Whisk in 4 yolks, then fold in 4 whites whipped to soft peaks with 40g sugar, then 150ml softly whipped cream. Spoon into four glasses and set in the fridge for 4 hours before serving.","shop":["200g dark chocolate@Pantry","30g butter@Dairy","4 eggs@Dairy","40g caster sugar@Pantry","150ml thickened cream@Dairy"]}],"d":[{"n":"Champagne","note":"Brut champagne in coupes, like it's 1876","how":"Chill a 750ml bottle of brut champagne to about 7C, around three hours in the fridge or 30 minutes in an ice bucket. Open gently and pour into four coupes, slowly, so the foam does not spill over the shallow rims.","shop":["750ml champagne@Bottle shop"]}],"shopping":["1 baguette@Bakery","150g goat's cheese@Deli","2 pears@Produce","1 jar honey@Pantry","1 bunch thyme@Produce","4 soft pretzels@Bakery","210g butter@Dairy","1 box rock salt@Pantry","1 jar wholegrain mustard@Pantry","1.5kg whole snapper@Seafood","2 lemons@Produce","1 fennel bulb@Produce","1 bunch dill@Produce","800g new potatoes@Produce","1 shallot@Produce","100ml white wine@Bottle shop","1 bottle white wine vinegar@Pantry","200g dark chocolate@Pantry","4 eggs@Dairy","40g caster sugar@Pantry","150ml thickened cream@Dairy","750ml champagne@Bottle shop"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Lethal Weapon (1987)":{"poster":"assets/menu-posters/lethal-weapon-1987.jpg","colour":"#9c2428","servings":4,"tagline":"Too old for this? Not for dessert.","cue":"Serve the mains at Roger's birthday dinner, when Riggs meets the family.","menu":{"s":[{"n":"Riggs' trailer snacks","note":"Saltines, sharp cheddar, folded salami and pickled jalapeños","how":"Cut 250g sharp cheddar into slabs and fold 150g sliced salami into quarters. Lay out on a chopping board with a sleeve of saltine crackers and a small bowl of pickled jalapeños. Eat it straight off the board on the couch.","shop":["250g sharp cheddar@Deli","150g salami@Deli","1 packet saltine crackers@Pantry","1 jar pickled jalapeños@Pantry"]},{"n":"Christmas tree lot hot dogs","note":"Griddled franks with mustard and fried onions, wrapped in foil","how":"Simmer 8 franks for 5 minutes, then griddle until blistered. Fry 2 sliced onions in oil until soft and golden. Steam 8 buns, fill with franks, onions and mustard, then wrap each in foil to keep warm until everyone is ready.","shop":["8 hot dog franks@Meat","8 hot dog buns@Bakery","2 brown onions@Produce","1 bottle yellow mustard@Pantry"]}],"m":[{"n":"Trish's stew, made properly","note":"Slow-braised beef stew in red wine over buttery mash","how":"Brown 1kg diced beef chuck in batches. Soften 1 onion, 2 carrots and 2 celery sticks, stir in 2 tbsp tomato paste, then add 250ml red wine, 500ml stock and thyme. Braise at 150C for 3 hours. Serve on 1kg potatoes mashed with butter.","shop":["1kg beef chuck@Meat","1 brown onion@Produce","2 carrots@Produce","2 celery sticks@Produce","1 tube tomato paste@Pantry","250ml red wine@Bottle shop","500ml beef stock@Pantry","1 bunch thyme@Produce","1kg potatoes@Produce","60g butter@Dairy"]}],"w":[{"n":"Roger's birthday cake","note":"Layered chocolate cake with buttercream and far too many candles","how":"Beat 200g butter with 250g sugar, add 4 eggs, then fold in 250g self-raising flour, 50g cocoa and 200ml milk. Bake in two tins at 170C for 35 minutes. Beat 200g butter, 300g icing sugar and 40g cocoa for buttercream. Fill, cover and add candles.","shop":["400g butter@Dairy","250g caster sugar@Pantry","4 eggs@Dairy","250g self-raising flour@Pantry","90g cocoa@Pantry","200ml full cream milk@Dairy","300g icing sugar@Pantry","1 box birthday candles@Pantry"]}],"d":[{"n":"Beer from Riggs' trailer fridge","note":"Cold lager in the bottle, drunk on the step","how":"Chill eight 375ml bottles of lager in the fridge for at least three hours, or in a bucket of ice and water for 30 minutes. Hand them out with the caps already off and drink straight from the bottle.","shop":["8 375ml bottles lager@Bottle shop"]}],"shopping":["250g sharp cheddar@Deli","150g salami@Deli","1 packet saltine crackers@Pantry","1 jar pickled jalapeños@Pantry","8 hot dog franks@Meat","8 hot dog buns@Bakery","2 brown onions@Produce","1 bottle yellow mustard@Pantry","1kg beef chuck@Meat","1 brown onion@Produce","2 carrots@Produce","2 celery sticks@Produce","1 tube tomato paste@Pantry","250ml red wine@Bottle shop","500ml beef stock@Pantry","1 bunch thyme@Produce","1kg potatoes@Produce","460g butter@Dairy","250g caster sugar@Pantry","4 eggs@Dairy","250g self-raising flour@Pantry","90g cocoa@Pantry","200ml full cream milk@Dairy","300g icing sugar@Pantry","1 box birthday candles@Pantry","8 375ml bottles lager@Bottle shop"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Lethal Weapon 2 (1989)":{"poster":"assets/menu-posters/lethal-weapon-2-1989.jpg","colour":"#a74025","servings":4,"tagline":"Diplomatic immunity doesn't cover dessert.","cue":"Serve the snacks when Leo Getz says okay, okay, okay.","menu":{"s":[{"n":"Toilet bomb devilled eggs","note":"Tangy devilled eggs with paprika, best eaten sitting down","how":"Boil 8 eggs for 10 minutes, cool and halve. Mash the yolks with 3 tbsp mayo, 1 tsp Dijon and a splash of pickle juice until smooth. Pipe back into the whites and dust with smoked paprika. Serve chilled.","shop":["8 eggs@Dairy","1 jar mayonnaise@Pantry","1 jar Dijon mustard@Pantry","1 jar smoked paprika@Pantry"]},{"n":"Consulate biltong","note":"Thin biltong with dried peaches and salted macadamias","how":"Roast 150g macadamias at 170C for 8 minutes and toss with salt while warm. Slice 250g biltong thinly across the grain. Pile on a board with 150g dried peaches and the macadamias in little bowls.","shop":["150g macadamias@Pantry","250g beef biltong@Deli","150g dried peaches@Pantry"]}],"m":[{"n":"Boerewors rolls","note":"Grilled spiced sausage coil in rolls with tomato and onion relish","how":"Simmer 2 sliced onions, 4 chopped tomatoes, 1 chilli and 1 tsp sugar for 20 minutes into a relish. Grill a 1kg coil of boerewors over coals or a hot grill for 15 minutes, turning once. Cut and serve in 4 long rolls with relish.","shop":["1kg boerewors@Meat","4 long rolls@Bakery","2 onions@Produce","4 tomatoes@Produce","1 red chilli@Produce"]}],"w":[{"n":"TV ad cupcakes","note":"Bright vanilla cupcakes with pastel buttercream and sprinkles","how":"Beat 125g butter with 150g sugar, add 2 eggs, then fold in 200g self-raising flour and 125ml milk. Bake 12 cupcakes at 180C for 18 minutes. Beat 150g butter with 300g icing sugar, tint in pastel colours, swirl on and add sprinkles.","shop":["275g butter@Dairy","150g caster sugar@Pantry","2 eggs@Dairy","200g self-raising flour@Pantry","125ml full cream milk@Dairy","300g icing sugar@Pantry","1 jar sprinkles@Pantry"]}],"d":[{"n":"Cold beer","note":"Ice-cold American lager, opened on the back deck","how":"Chill eight 355ml bottles of American lager in the fridge for at least three hours, or in a bucket of ice and water for 30 minutes. Crack them open on the back deck and drink straight from the bottle.","shop":["8 355ml bottles American lager@Bottle shop"]}],"shopping":["10 eggs@Dairy","1 jar mayonnaise@Pantry","1 jar Dijon mustard@Pantry","1 jar smoked paprika@Pantry","150g macadamias@Pantry","250g beef biltong@Deli","150g dried peaches@Pantry","1kg boerewors@Meat","4 long rolls@Bakery","2 onions@Produce","4 tomatoes@Produce","1 red chilli@Produce","275g butter@Dairy","150g caster sugar@Pantry","200g self-raising flour@Pantry","125ml full cream milk@Dairy","300g icing sugar@Pantry","1 jar sprinkles@Pantry","8 355ml bottles American lager@Bottle shop"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"48 Hrs. (1982)":{"poster":"assets/menu-posters/48-hrs-1982.jpg","colour":"#af3324","servings":4,"tagline":"Forty-eight hours. Eat fast.","cue":"Pour drinks when Reggie walks into Torchy's redneck bar.","menu":{"s":[{"n":"Torchy's bar peanuts","note":"Hot roasted peanuts with salt and cayenne","how":"Spread 400g peanuts in the shell on a tray and roast at 180C for 20 minutes. Toss straight away with 1 tsp fine salt and a pinch of cayenne. Tip into a tin bucket and put an empty bowl out for the shells.","shop":["400g peanuts in the shell@Pantry","1 box fine salt@Pantry","1 jar cayenne pepper@Pantry"]},{"n":"San Francisco sourdough","note":"Warm torn sourdough with roasted garlic butter","how":"Roast a garlic head wrapped in foil at 180C for 40 minutes. Squeeze into 125g soft salted butter and whip. Warm a sourdough round at 200C for 10 minutes, tear into chunks and serve with the butter.","shop":["1 garlic head@Produce","125g salted butter@Dairy","1 sourdough loaf@Bakery"]}],"m":[{"n":"San Francisco cioppino","note":"Seafood stew of crab, clams, mussels and prawns in tomato","how":"Soften 1 sliced fennel, 1 onion and 3 garlic cloves in oil. Add 1 tin tomatoes, 250ml white wine and 500ml fish stock, simmer 20 minutes. Add 1 crab, then 500g clams and mussels, then 300g prawns and 300g fish. Serve with sourdough.","shop":["1 fennel bulb@Produce","1 brown onion@Produce","3 garlic cloves@Produce","1 tin crushed tomatoes@Pantry","250ml white wine@Bottle shop","500ml fish stock@Pantry","1 blue swimmer crab@Seafood","250g clams@Seafood","250g mussels@Seafood","300g green prawns@Seafood","300g firm white fish@Seafood","1 sourdough loaf@Bakery"]}],"w":[{"n":"Jailhouse chocolate cake","note":"One-bowl chocolate cake with thick fudge icing","how":"Whisk 250g flour, 300g sugar, 60g cocoa and 1 tsp bicarb. Add 125ml oil, 250ml buttermilk, 2 eggs and 250ml hot coffee. Bake at 170C for 35 minutes. Ice with 250g icing sugar, 40g cocoa, 60g soft butter and a splash of hot water.","shop":["250g plain flour@Pantry","300g caster sugar@Pantry","100g cocoa@Pantry","125ml vegetable oil@Pantry","250ml buttermilk@Dairy","2 eggs@Dairy","1 jar instant coffee@Pantry","250g icing sugar@Pantry","60g butter@Dairy"]}],"d":[{"n":"Cold beer at Torchy's","note":"Ice-cold American lager in long neck bottles, straight from the fridge","how":"Chill eight 355ml long necks of American lager in the fridge for at least three hours. Open them at the table and drink straight from the bottle, the way it's done in a bar like Torchy's.","shop":["8 355ml bottles American lager@Bottle shop"]}],"shopping":["400g peanuts in the shell@Pantry","1 box fine salt@Pantry","1 jar cayenne pepper@Pantry","1 garlic head@Produce","125g salted butter@Dairy","2 sourdough loaf@Bakery","1 fennel bulb@Produce","1 brown onion@Produce","3 garlic cloves@Produce","1 tin crushed tomatoes@Pantry","250ml white wine@Bottle shop","500ml fish stock@Pantry","1 blue swimmer crab@Seafood","250g clams@Seafood","250g mussels@Seafood","300g green prawns@Seafood","300g firm white fish@Seafood","250g plain flour@Pantry","300g caster sugar@Pantry","100g cocoa@Pantry","125ml vegetable oil@Pantry","250ml buttermilk@Dairy","2 eggs@Dairy","1 jar instant coffee@Pantry","250g icing sugar@Pantry","60g butter@Dairy","8 355ml bottles American lager@Bottle shop"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Stakeout (1987)":{"poster":"assets/menu-posters/stakeout-1987.jpg","colour":"#223f4c","servings":4,"tagline":"Watch the girl. Eat the doughnuts.","cue":"Serve the snacks when Bill and Chris start their movie trivia game.","menu":{"s":[{"n":"Stakeout doughnuts","note":"Warm cake doughnuts shaken in cinnamon sugar","how":"Warm 8 cake doughnuts on a tray at 160C for 2 minutes. Drop them into a paper bag with 100g caster sugar and 2 tsp cinnamon, fold the top and shake until coated. Eat them out of the bag.","shop":["8 cake doughnuts@Bakery","100g caster sugar@Pantry","1 jar cinnamon@Pantry"]},{"n":"Surveillance snack mix","note":"Baked savoury mix of pretzels, peanuts and cereal","how":"Toss 150g pretzels, 150g peanuts, 150g cereal squares and 50g sunflower seeds with 60g melted butter, 2 tbsp Worcestershire and 1 tsp garlic powder. Bake at 130C for 45 minutes, stirring every 15 minutes. Cool before bagging up.","shop":["150g pretzels@Pantry","150g peanuts@Pantry","150g cereal squares@Pantry","50g sunflower seeds@Pantry","60g butter@Dairy","1 bottle Worcestershire sauce@Pantry","1 jar garlic powder@Pantry"]}],"m":[{"n":"Maria's home cooking","note":"Baked chicken enchiladas in red chilli sauce","how":"Soak 4 dried chillies in hot water, blitz with 1 tin tomatoes and garlic and simmer 10 minutes. Poach and shred 600g chicken thighs. Roll in 8 corn tortillas, cover with sauce and 150g cheddar and bake at 190C for 20 minutes. Serve with sour cream.","shop":["4 dried chillies@Pantry","1 tin crushed tomatoes@Pantry","2 garlic cloves@Produce","600g chicken thighs@Meat","8 corn tortillas@Bakery","150g cheddar@Dairy","200g sour cream@Dairy"]}],"w":[{"n":"Doughnut holes","note":"Little yeasted doughnut balls rolled in cinnamon sugar","how":"Mix 300g flour, 7g yeast, 2 tbsp sugar, 1 egg and 160ml warm milk into a soft dough and prove an hour. Roll into small balls and fry at 175C for 2 minutes. Roll in 100g caster sugar and 2 tsp cinnamon while warm.","shop":["300g plain flour@Pantry","7g dried yeast@Pantry","140g caster sugar@Pantry","1 egg@Dairy","160ml full cream milk@Dairy","1 jar cinnamon@Pantry","1L vegetable oil@Pantry"]}],"d":[{"n":"Thermos coffee","note":"Strong coffee with milk and sugar from a thermos","how":"Brew 60g ground coffee with 1L water, strong. Warm 200ml milk and stir it in with sugar to taste. Pour into a thermos that's been warmed with hot water. Pour into the thermos lid cups one at a time.","shop":["60g ground coffee@Pantry","200ml full cream milk@Dairy","1 bag caster sugar@Pantry"]}],"shopping":["8 cake doughnuts@Bakery","240g caster sugar@Pantry","1 jar cinnamon@Pantry","150g pretzels@Pantry","150g peanuts@Pantry","150g cereal squares@Pantry","50g sunflower seeds@Pantry","60g butter@Dairy","1 bottle Worcestershire sauce@Pantry","1 jar garlic powder@Pantry","4 dried chillies@Pantry","1 tin crushed tomatoes@Pantry","2 garlic cloves@Produce","600g chicken thighs@Meat","8 corn tortillas@Bakery","150g cheddar@Dairy","200g sour cream@Dairy","300g plain flour@Pantry","7g dried yeast@Pantry","1 egg@Dairy","360ml full cream milk@Dairy","1L vegetable oil@Pantry","60g ground coffee@Pantry"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Kindergarten Cop (1990)":{"poster":"assets/menu-posters/kindergarten-cop-1990.jpg","colour":"#2e643c","servings":4,"tagline":"It's not a tumour. It's lunch.","cue":"Serve the snacks when Kimble blows the whistle in class.","menu":{"s":[{"n":"Lunch box crackers and cheese","note":"Cheese cubes, crackers, apple and tomatoes packed in lunch boxes","how":"Cut 200g cheddar into small cubes. Slice 2 apples and toss in lemon juice so they don't brown. Pack each lunch box with cheese, a handful of crackers, apple slices and 250g cherry tomatoes shared between them.","shop":["200g cheddar@Dairy","2 apples@Produce","1 lemon@Produce","1 packet crackers@Pantry","250g cherry tomatoes@Produce"]},{"n":"Ferret-free fruit cups","note":"Bright fruit cups with orange juice and mint","how":"Dice 1 mango and a quarter of a pineapple, halve 250g strawberries and 200g grapes. Toss together with the juice of an orange. Spoon into four cups and top each with a mint leaf. Keep cold until serving.","shop":["1 mango@Produce","0.25 pineapple@Produce","250g strawberries@Produce","200g grapes@Produce","1 orange@Produce","1 bunch mint@Produce"]}],"m":[{"n":"Homemade fish fingers and chips","note":"Crumbed fish fingers with oven chips, tartare and peas","how":"Cut 600g firm white fish into fingers. Dip in flour, 2 beaten eggs and 150g panko and shallow-fry for 2 minutes a side. Cut 1kg potatoes into chips, toss in oil and roast at 220C for 35 minutes. Serve with tartare and 300g peas.","shop":["600g firm white fish@Seafood","1 bag plain flour@Pantry","2 eggs@Dairy","150g panko@Pantry","1kg potatoes@Produce","1 jar tartare sauce@Pantry","300g frozen peas@Frozen","500ml vegetable oil@Pantry"]}],"w":[{"n":"Kindergarten cupcakes","note":"Vanilla cupcakes in bright buttercream with sprinkles","how":"Beat 125g butter with 150g sugar, add 2 eggs, then fold in 200g self-raising flour and 125ml milk. Bake 12 cupcakes at 180C for 18 minutes. Beat 150g butter with 300g icing sugar, tint in primary colours, swirl on and add sprinkles.","shop":["275g butter@Dairy","150g caster sugar@Pantry","2 eggs@Dairy","200g self-raising flour@Pantry","125ml full cream milk@Dairy","300g icing sugar@Pantry","1 box food colouring@Pantry","1 jar sprinkles@Pantry"]}],"d":[{"n":"Chocolate milk","note":"Cold homemade chocolate milk, sweet and properly chocolatey","how":"Whisk 3 tbsp cocoa and 3 tbsp sugar into 150ml hot milk until smooth with no lumps. Top up with 850ml cold milk, stir well and chill. Pour into four glasses and give it another stir before drinking.","shop":["1 tin cocoa@Pantry","1 bag caster sugar@Pantry","1L full cream milk@Dairy"]}],"shopping":["200g cheddar@Dairy","2 apples@Produce","1 lemon@Produce","1 packet crackers@Pantry","250g cherry tomatoes@Produce","1 mango@Produce","0.25 pineapple@Produce","250g strawberries@Produce","200g grapes@Produce","1 orange@Produce","1 bunch mint@Produce","600g firm white fish@Seafood","1 bag plain flour@Pantry","4 eggs@Dairy","150g panko@Pantry","1kg potatoes@Produce","1 jar tartare sauce@Pantry","300g frozen peas@Frozen","500ml vegetable oil@Pantry","275g butter@Dairy","150g caster sugar@Pantry","200g self-raising flour@Pantry","1.12L full cream milk@Dairy","300g icing sugar@Pantry","1 box food colouring@Pantry","1 jar sprinkles@Pantry","1 tin cocoa@Pantry"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"The Godfather Part II (1974)":{"poster":"assets/menu-posters/the-godfather-part-ii-1974.jpg","colour":"#74190e","servings":4,"tagline":"The family business goes international.","cue":"Serve the mains when the story moves to Havana for New Year's Eve.","menu":{"s":[{"n":"Feast day arancini","note":"Saffron rice balls filled with beef ragù, peas and mozzarella.","how":"Cook 300g arborio rice in 900ml stock with a pinch of saffron until thick, stir in 40g parmesan and chill overnight on a tray. Brown 150g beef mince with 50g frozen peas and 2 tbsp passata. Wrap golf balls of rice around a spoon of filling and a cube of mozzarella. Roll in flour, 2 beaten eggs and 100g breadcrumbs, and fry at 175C until deep gold.","shop":["300g arborio rice@Pantry","900ml chicken stock@Pantry","1 pinch saffron@Pantry","40g parmesan@Dairy","150g beef mince@Meat","50g frozen peas@Frozen","100g mozzarella@Dairy","2 eggs@Dairy","100g breadcrumbs@Pantry"]},{"n":"Havana Cuban sliders","note":"Pressed slider rolls of ham, mojo pork, Swiss cheese and pickle.","how":"Split 8 slider rolls and smear the cut sides with 2 tbsp yellow mustard. Layer with 150g leg ham, 150g sliced roast pork, 8 slices Swiss cheese and sliced dill pickles. Brush the tops with 30g melted butter and press in a heavy pan over medium heat with a second pan on top, 3 minutes a side, until the cheese melts.","shop":["8 slider rolls@Bakery","2 tbsp yellow mustard@Pantry","150g leg ham@Deli","150g roast pork@Deli","8 slices Swiss cheese@Deli","4 dill pickles@Pantry","30g butter@Dairy"]}],"m":[{"n":"Vito's tenement baked ziti","note":"Baked ziti with sausage tomato sauce, seasoned ricotta and blistered mozzarella.","how":"Squeeze 500g Italian sausages from their skins and brown, add 700ml passata and simmer 30 minutes. Cook 500g ziti or penne 3 minutes short of done. Mix 400g ricotta with 50g grated parmesan, nutmeg and parsley. Layer pasta, sauce and ricotta in a baking dish, top with 200g torn mozzarella and bake at 200C for 25 minutes until blistered.","shop":["500g Italian sausages@Meat","700ml passata@Pantry","500g ziti or penne@Pantry","400g ricotta@Dairy","50g parmesan@Dairy","200g mozzarella@Dairy"]}],"w":[{"n":"Hyman Roth's birthday cake","note":"Vanilla slab cake iced pale green and cut like an island.","how":"Beat 200g soft butter with 200g caster sugar, add 4 eggs and fold in 250g self-raising flour with 100ml milk. Bake in a lined slab tin at 180C for 30 minutes and cool. Trim into a rough island shape. Beat 150g butter with 300g icing sugar and a few drops of green food colouring, spread thinly then again, pipe happy birthday across and slice at the table.","shop":["350g butter@Dairy","200g caster sugar@Pantry","4 eggs@Dairy","250g self-raising flour@Pantry","100ml full cream milk@Dairy","300g icing sugar@Pantry","1 bottle green food colouring@Pantry"]}],"d":[{"n":"Havana daiquiri","note":"White rum, fresh lime and sugar shaken hard and served ice cold.","how":"Make sugar syrup by dissolving 60g caster sugar in 60ml hot water and cooling. For each drink shake 60ml white rum, 25ml fresh lime juice and 15ml syrup hard with plenty of ice, then double strain into a chilled coupe. Makes four, with 240ml rum and about 4 limes.","shop":["240ml white rum@Bottle shop","4 limes@Produce","60g caster sugar@Pantry","1kg ice@Frozen"]}],"shopping":["300g arborio rice@Pantry","900ml chicken stock@Pantry","1 pinch saffron@Pantry","90g parmesan@Dairy","150g beef mince@Meat","50g frozen peas@Frozen","300g mozzarella@Dairy","6 eggs@Dairy","100g breadcrumbs@Pantry","8 slider rolls@Bakery","2 tbsp yellow mustard@Pantry","150g leg ham@Deli","150g roast pork@Deli","8 slices Swiss cheese@Deli","4 dill pickles@Pantry","380g butter@Dairy","500g Italian sausages@Meat","700ml passata@Pantry","500g ziti or penne@Pantry","400g ricotta@Dairy","260g caster sugar@Pantry","250g self-raising flour@Pantry","100ml full cream milk@Dairy","300g icing sugar@Pantry","1 bottle green food colouring@Pantry","240ml white rum@Bottle shop","4 limes@Produce","1kg ice@Frozen"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Casino (1995)":{"poster":"assets/menu-posters/casino-1995.jpg","colour":"#24402a","servings":4,"tagline":"Every muffin gets the same number of blueberries.","cue":"Bring out the muffins and count the blueberries before anyone takes one.","menu":{"s":[{"n":"Tangiers prawn cocktail","note":"Chilled prawns on iceberg with horseradish Marie Rose.","how":"Poach 500g peeled green prawns in salted water with lemon and a bay leaf for 2 minutes, then chill in iced water. Mix 120g mayonnaise with 2 tbsp tomato sauce, 1 tsp horseradish and a squeeze of lemon. Shred half an iceberg lettuce into four glasses, hang the prawns off the rims and spoon the sauce into the middle.","shop":["500g green prawns@Seafood","1 iceberg lettuce@Produce","120g mayonnaise@Pantry","2 tbsp tomato sauce@Pantry","1 tsp horseradish@Pantry","1 lemon@Produce"]},{"n":"Card table chips and onion dip","note":"Thick-cut chips with a deep caramelised onion and chive dip.","how":"Cook 2 thinly sliced brown onions in 2 tbsp oil over low heat for 40 minutes until deep brown, then cool. Mix with 200g sour cream, 100g cream cheese, 1/2 tsp garlic powder, 2 tbsp chopped chives and salt. Serve with two 175g bags of thick-cut potato chips.","shop":["2 brown onions@Produce","200g sour cream@Dairy","100g cream cheese@Dairy","1/2 tsp garlic powder@Pantry","1 bunch chives@Produce","350g thick-cut potato chips@Pantry"]}],"m":[{"n":"Tangiers rib eye","note":"Butter-basted rib eye with thyme and garlic, and creamed spinach.","how":"Salt 2 rib eye steaks, about 400g each, and leave uncovered on a rack in the fridge overnight. Sear in a smoking pan for 3 minutes a side, then add 50g butter, 4 sprigs thyme and 3 crushed garlic cloves and baste until 54C inside. Rest 8 minutes and slice. Wilt 500g spinach, squeeze dry and simmer with 150ml thickened cream and nutmeg.","shop":["800g rib eye steak@Meat","50g butter@Dairy","1 bunch thyme@Produce","3 garlic cloves@Produce","500g spinach@Produce","150ml thickened cream@Dairy"]}],"w":[{"n":"Equal-blueberry muffins","note":"Buttermilk muffins with exactly ten blueberries pressed into each.","how":"Whisk 300g plain flour, 150g caster sugar and 2 tsp baking powder. Mix 2 eggs, 250ml buttermilk and 90g melted butter, then fold into the dry mix until just combined. Spoon into 12 lined muffin cases and press exactly 10 blueberries into the top of each. Bake at 190C for 20 minutes.","shop":["300g plain flour@Pantry","150g caster sugar@Pantry","2 tsp baking powder@Pantry","2 eggs@Dairy","250ml buttermilk@Dairy","90g butter@Dairy","125g blueberries@Produce"]}],"d":[{"n":"Dry martini","note":"Gin stirred with a little vermouth, served in a frozen glass.","how":"Freeze four martini glasses for 30 minutes. For each drink stir 60ml gin with 10ml dry vermouth over plenty of ice for 30 seconds and strain into a frozen glass. Garnish with a green olive on a pick. Makes four with 240ml gin and 40ml vermouth.","shop":["240ml gin@Bottle shop","40ml dry vermouth@Bottle shop","4 green olives@Deli","1kg ice@Frozen"]}],"shopping":["500g green prawns@Seafood","1 iceberg lettuce@Produce","120g mayonnaise@Pantry","2 tbsp tomato sauce@Pantry","1 tsp horseradish@Pantry","1 lemon@Produce","2 brown onions@Produce","200g sour cream@Dairy","100g cream cheese@Dairy","1/2 tsp garlic powder@Pantry","1 bunch chives@Produce","350g thick-cut potato chips@Pantry","800g rib eye steak@Meat","140g butter@Dairy","1 bunch thyme@Produce","3 garlic cloves@Produce","500g spinach@Produce","150ml thickened cream@Dairy","300g plain flour@Pantry","150g caster sugar@Pantry","2 tsp baking powder@Pantry","2 eggs@Dairy","250ml buttermilk@Dairy","125g blueberries@Produce","240ml gin@Bottle shop","40ml dry vermouth@Bottle shop","4 green olives@Deli","1kg ice@Frozen"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Scarface (1983)":{"poster":"assets/menu-posters/scarface-1983.jpg","colour":"#a31b24","servings":4,"tagline":"The world is yours. So is the last croqueta.","cue":"Serve the mains when Tony first walks into the Babylon Club.","menu":{"s":[{"n":"Croquetas de jamón","note":"Creamy serrano ham croquettes with a crisp golden crumb.","how":"Melt 60g butter, stir in 70g plain flour for 2 minutes, then whisk in 500ml warm milk and cook 8 minutes until very thick. Stir in 100g finely chopped serrano ham and a pinch of nutmeg. Spread on a tray, cover and chill overnight. Roll into 16 logs, dip in 2 beaten eggs and 100g fine breadcrumbs, and fry at 180C until golden.","shop":["60g butter@Dairy","70g plain flour@Pantry","500ml full cream milk@Dairy","100g serrano ham@Deli","2 eggs@Dairy","100g breadcrumbs@Pantry","1L vegetable oil@Pantry"]},{"n":"Tostones","note":"Twice-fried smashed green plantain under garlic lime mojo.","how":"Peel 3 green plantains, cut into 3cm chunks and fry at 160C for 4 minutes until soft. Smash flat with a heavy glass and fry again at 190C until crisp. Mix 3 crushed garlic cloves, the juice of 2 limes and 60ml olive oil, spoon over and finish with flaky salt.","shop":["3 green plantains@Produce","3 garlic cloves@Produce","2 limes@Produce","60ml olive oil@Pantry","1L vegetable oil@Pantry"]}],"m":[{"n":"Ropa vieja","note":"Shredded flank steak in tomato sofrito with olives, rice and black beans.","how":"Simmer 1kg flank steak with 2 bay leaves and half an onion in water for 2 hours until tender, then shred, keeping 250ml broth. Fry 1 sliced onion, 2 sliced capsicums and 3 garlic cloves until soft, add 2 tsp cumin, 1 tsp oregano, 400g crushed tomatoes, 80g green olives, the beef and broth and simmer 20 minutes. Serve with 300g rice and 2 tins black beans.","shop":["1kg flank steak@Meat","2 brown onions@Produce","2 capsicums@Produce","3 garlic cloves@Produce","2 tsp ground cumin@Pantry","400g crushed tomatoes@Pantry","80g green olives@Deli","300g long grain rice@Pantry","800g black beans@Pantry"]}],"w":[{"n":"Guava pastelitos","note":"Flaky puff pastry parcels of guava paste and cream cheese.","how":"Cut 2 sheets puff pastry into 4 squares each. Put a 30g slice of guava paste and a teaspoon of cream cheese in the middle of 4 squares, using 120g guava and 100g cream cheese in total. Cover with the other squares, press the edges with a fork, brush with 1 beaten egg and sprinkle with sugar. Bake at 200C for 20 minutes until puffed.","shop":["2 sheets puff pastry@Frozen","120g guava paste@Pantry","100g cream cheese@Dairy","1 egg@Dairy","2 tbsp caster sugar@Pantry"]}],"d":[{"n":"Mojito","note":"White rum, lime and mint over crushed ice, topped with soda.","how":"Dissolve 60g caster sugar in 60ml hot water and cool. For each drink, gently muddle 8 mint leaves with 20ml syrup and 25ml lime juice in a tall glass, add 50ml white rum and fill with crushed ice. Top with soda water and stir. Makes four with 200ml rum and about 4 limes.","shop":["200ml white rum@Bottle shop","1 bunch mint@Produce","4 limes@Produce","60g caster sugar@Pantry","500ml soda water@Drinks","1kg crushed ice@Frozen"]}],"shopping":["60g butter@Dairy","70g plain flour@Pantry","500ml full cream milk@Dairy","100g serrano ham@Deli","2 eggs@Dairy","100g breadcrumbs@Pantry","2L vegetable oil@Pantry","3 green plantains@Produce","6 garlic cloves@Produce","6 limes@Produce","60ml olive oil@Pantry","1kg flank steak@Meat","2 brown onions@Produce","2 capsicums@Produce","2 tsp ground cumin@Pantry","400g crushed tomatoes@Pantry","80g green olives@Deli","300g long grain rice@Pantry","800g black beans@Pantry","2 sheets puff pastry@Frozen","120g guava paste@Pantry","100g cream cheese@Dairy","1 egg@Dairy","200ml white rum@Bottle shop","1 bunch mint@Produce","90g caster sugar@Pantry","500ml soda water@Drinks","1kg crushed ice@Frozen"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"The Freshman (1990)":{"poster":"assets/menu-posters/the-freshman-1990.jpg","colour":"#23402b","servings":4,"tagline":"Some lessons aren't taught at film school.","cue":"Serve the mains when the Gourmet Club menu gets read out.","menu":{"s":[{"n":"Little Italy antipasto","note":"Salami, mortadella and provolone with capsicum, artichokes and torn bread.","how":"Arrange 100g salami, 100g mortadella and 150g provolone on a board. Add 2 roasted red capsicums cut into strips and 200g marinated artichokes. Tear a loaf of seeded Italian bread at the table.","shop":["100g salami@Deli","100g mortadella@Deli","150g provolone@Deli","2 red capsicums@Produce","200g marinated artichokes@Deli","1 loaf Italian bread@Bakery"]},{"n":"Garlic knots","note":"Pizza dough knots baked golden and tossed in garlic butter and parmesan.","how":"Cut 500g pizza dough into 12 strips, tie each into a knot and prove 30 minutes. Bake at 230C for 12 minutes. Melt 50g butter with 3 crushed garlic cloves and chopped parsley and toss the hot knots through, then shower with 30g grated parmesan.","shop":["500g pizza dough@Bakery","50g butter@Dairy","3 garlic cloves@Produce","1 bunch parsley@Produce","30g parmesan@Dairy"]}],"m":[{"n":"Carmine's veal","note":"Seared veal in a marsala and mushroom sauce finished with butter.","how":"Dust 600g veal escalopes with seasoned flour and sear in 20g butter and a little oil for 1 minute a side, then set aside. Brown 250g sliced button mushrooms in the pan, add 150ml marsala and 150ml beef stock and reduce by half. Whisk in 40g cold butter, return the veal and warm through.","shop":["600g veal escalopes@Meat","2 tbsp plain flour@Pantry","60g butter@Dairy","250g button mushrooms@Produce","150ml marsala@Bottle shop","150ml beef stock@Pantry"]}],"w":[{"n":"Cannoli","note":"Vanilla ricotta cannoli with mini choc chips and pistachio ends.","how":"Drain 500g fresh ricotta for 2 hours, then beat with 80g icing sugar, 1 tsp vanilla extract and 50g mini choc chips. Pipe into 8 cannoli shells just before serving and dip the ends in 30g chopped pistachios.","shop":["500g fresh ricotta@Dairy","80g icing sugar@Pantry","1 tsp vanilla extract@Pantry","50g mini choc chips@Pantry","8 cannoli shells@Bakery","30g pistachios@Pantry"]}],"d":[{"n":"Chianti","note":"Chianti Classico opened early and poured into tumblers.","how":"Open one 750ml bottle of Chianti Classico half an hour ahead and keep it at about 16C. Pour into four tumblers, about 180ml each, and keep the bottle on the table for refills during the dinner.","shop":["750ml Chianti Classico@Bottle shop"]}],"shopping":["100g salami@Deli","100g mortadella@Deli","150g provolone@Deli","2 red capsicums@Produce","200g marinated artichokes@Deli","1 loaf Italian bread@Bakery","500g pizza dough@Bakery","110g butter@Dairy","3 garlic cloves@Produce","1 bunch parsley@Produce","30g parmesan@Dairy","600g veal escalopes@Meat","2 tbsp plain flour@Pantry","250g button mushrooms@Produce","150ml marsala@Bottle shop","150ml beef stock@Pantry","500g fresh ricotta@Dairy","80g icing sugar@Pantry","1 tsp vanilla extract@Pantry","50g mini choc chips@Pantry","8 cannoli shells@Bakery","30g pistachios@Pantry","750ml Chianti Classico@Bottle shop"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Road to Perdition (2002)":{"poster":"assets/menu-posters/road-to-perdition-2002.jpg","colour":"#273a47","servings":4,"tagline":"Every father wants better for his son.","cue":"Serve dessert at the diner stop on the road to Perdition.","menu":{"s":[{"n":"Diner pickles","note":"Quick dill pickles of cucumber and green tomato, served cold in a jar.","how":"Slice 3 Lebanese cucumbers and 2 green tomatoes and pack into a jar with 2 sliced garlic cloves and a few dill sprigs. Heat 250ml white vinegar, 250ml water, 1 tbsp sugar and 2 tsp salt until dissolved, pour over hot and seal. Chill overnight and serve cold.","shop":["3 Lebanese cucumbers@Produce","2 green tomatoes@Produce","2 garlic cloves@Produce","1 bunch dill@Produce","250ml white vinegar@Pantry","1 tbsp caster sugar@Pantry"]},{"n":"Devilled eggs","note":"Devilled eggs whipped with mayo, mustard and cayenne, dusted with paprika.","how":"Boil 8 eggs for 10 minutes, cool in iced water and peel. Halve them, whip the yolks with 3 tbsp mayonnaise, 1 tsp Dijon mustard and a pinch of cayenne until smooth, and pipe back into the whites. Dust with 1 tsp smoked paprika.","shop":["8 eggs@Dairy","3 tbsp mayonnaise@Pantry","1 tsp Dijon mustard@Pantry","1 pinch cayenne pepper@Pantry","1 tsp smoked paprika@Pantry"]}],"m":[{"n":"Wake pot roast","note":"Beef chuck braised slowly with vegetables, stock and a splash of whiskey.","how":"Season a 1.2kg beef chuck roast and brown all over in a heavy pot. Add 2 brown onions in wedges, 3 carrots in chunks, 500ml beef stock and 60ml Irish whiskey. Cover and braise at 160C for 3 hours, adding 800g halved potatoes for the last hour. Slice and serve with the juices.","shop":["1.2kg beef chuck roast@Meat","2 brown onions@Produce","3 carrots@Produce","500ml beef stock@Pantry","60ml Irish whiskey@Bottle shop","800g potatoes@Produce"]}],"w":[{"n":"Apple pie with cheddar","note":"Deep apple pie with sharp cheddar melted over the crust.","how":"Peel and slice 1kg Granny Smith apples, cook 5 minutes with 80g sugar and 1 tsp cinnamon, and cool. Line a deep pie dish with 1 sheet sweet shortcrust, fill, cover with a second sheet and cut slits. Bake at 190C for 45 minutes. Lay 120g sliced sharp cheddar on top for the last 5 minutes so it melts.","shop":["1kg Granny Smith apples@Produce","80g caster sugar@Pantry","1 tsp ground cinnamon@Pantry","2 sheets sweet shortcrust pastry@Frozen","120g sharp cheddar@Dairy"]}],"d":[{"n":"Black coffee","note":"Strong drip coffee poured black and refilled until the car's ready.","how":"Brew 1 litre strong drip coffee with 70g ground coffee. Pour black into four mugs and keep the pot warm for refills. Put 100ml cream on the table for anyone who wants it.","shop":["70g ground coffee@Pantry","100ml thickened cream@Dairy"]}],"shopping":["3 Lebanese cucumbers@Produce","2 green tomatoes@Produce","2 garlic cloves@Produce","1 bunch dill@Produce","250ml white vinegar@Pantry","8 eggs@Dairy","3 tbsp mayonnaise@Pantry","1 tsp Dijon mustard@Pantry","1 pinch cayenne pepper@Pantry","1 tsp smoked paprika@Pantry","1.2kg beef chuck roast@Meat","2 brown onions@Produce","3 carrots@Produce","500ml beef stock@Pantry","60ml Irish whiskey@Bottle shop","800g potatoes@Produce","1kg Granny Smith apples@Produce","95g caster sugar@Pantry","1 tsp ground cinnamon@Pantry","2 sheets sweet shortcrust pastry@Frozen","120g sharp cheddar@Dairy","70g ground coffee@Pantry","100ml thickened cream@Dairy"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Do the Right Thing (1989)":{"poster":"assets/menu-posters/do-the-right-thing-1989.jpg","colour":"#ad3020","servings":4,"tagline":"Hottest day of the year. Coldest drinks in the house.","cue":"Turn the fan on and pour the drinks when Mookie makes his first delivery.","menu":{"s":[{"n":"Sal's garlic knots","note":"Pizza dough knots tossed hot in garlic butter, parsley and parmesan.","how":"Cut 500g pizza dough into 12 strips, tie each into a knot and prove 30 minutes. Bake at 230C for 12 minutes until golden. Melt 50g butter with 3 crushed garlic cloves and chopped parsley, toss the hot knots through and shower with 30g grated parmesan.","shop":["500g pizza dough@Bakery","50g butter@Dairy","3 garlic cloves@Produce","1 bunch parsley@Produce","30g parmesan@Dairy"]},{"n":"Watermelon wedges","note":"Ice-cold watermelon with chilli, lime and salt at the table.","how":"Chill a quarter watermelon, about 2kg, for several hours. Cut into wedges. Mix 1 tsp sea salt flakes, 1/2 tsp chilli flakes and the zest of 1 lime in a little bowl and sprinkle over at the table, with lime wedges to squeeze.","shop":["2kg watermelon@Produce","1 tsp sea salt flakes@Pantry","1/2 tsp chilli flakes@Pantry","1 lime@Produce"]}],"m":[{"n":"Sal's Famous slice","note":"Big thin New York slices with mozzarella, pepperoni and oregano.","how":"Rest 2 balls of pizza dough, about 500g, at room temperature for an hour. Season 400g crushed tomatoes with salt and stretch the bases thin. Spread with sauce, top with 250g grated low-moisture mozzarella and 100g pepperoni and bake on a preheated tray at the oven's highest setting for 8 to 10 minutes. Sprinkle with oregano and cut big.","shop":["500g pizza dough@Bakery","400g crushed tomatoes@Pantry","250g low-moisture mozzarella@Dairy","100g pepperoni@Deli","1 tsp dried oregano@Pantry"]}],"w":[{"n":"Cherry shaved ice","note":"Crushed ice soaked with homemade cherry syrup.","how":"Simmer 300g cherries, pitted, with 150g caster sugar, 150ml water and the juice of 1 lemon for 10 minutes, then strain and cool the syrup. Shave or crush 1kg ice into four cups and pour the syrup over just before serving.","shop":["300g cherries@Produce","150g caster sugar@Pantry","1 lemon@Produce","1kg ice@Frozen"]}],"d":[{"n":"Ice cold beer","note":"American lager frozen cold, straight from the bottle.","how":"Put four 355ml bottles of American lager in the freezer for 25 minutes, no longer, so they are ice cold but not frozen. Serve straight from the bottle on a hot night.","shop":["4 bottles American lager@Bottle shop"]}],"shopping":["1kg pizza dough@Bakery","50g butter@Dairy","3 garlic cloves@Produce","1 bunch parsley@Produce","30g parmesan@Dairy","2kg watermelon@Produce","1 tsp sea salt flakes@Pantry","1/2 tsp chilli flakes@Pantry","1 lime@Produce","400g crushed tomatoes@Pantry","250g low-moisture mozzarella@Dairy","100g pepperoni@Deli","1 tsp dried oregano@Pantry","300g cherries@Produce","150g caster sugar@Pantry","1 lemon@Produce","1kg ice@Frozen","4 bottles American lager@Bottle shop"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Elf (2003)":{"poster":"assets/menu-posters/elf-2003.jpg","colour":"#23572c","servings":4,"tagline":"Four food groups. All of them sugar.","cue":"Pour coffee when Buddy finds the world's best cup of coffee.","menu":{"s":[{"n":"Maple syrup popcorn","note":"Crunchy popcorn clusters coated in maple syrup and butter.","how":"Pop 60g popping corn in 1 tbsp vegetable oil. Boil 200ml maple syrup with 40g butter to 120C. Pour over the popcorn, toss quickly and spread on a lined tray to set for 30 minutes. Break into clusters.","shop":["60g popping corn@Pantry","1 tbsp vegetable oil@Pantry","200ml maple syrup@Pantry","40g butter@Dairy"]},{"n":"Candy cane pretzel rods","note":"White chocolate pretzel rods coated in crushed candy canes.","how":"Melt 150g white chocolate in a bowl over barely simmering water. Dip 12 pretzel rods two-thirds into the chocolate, roll immediately in 60g crushed candy canes and set on baking paper for 30 minutes.","shop":["12 pretzel rods@Pantry","150g white chocolate@Pantry","60g candy canes@Pantry"]}],"m":[{"n":"New York street hot dogs","note":"Griddled franks in steamed buns with tomato onions and sauerkraut.","how":"Cook 2 sliced brown onions in 20g butter over medium-low heat for 20 minutes. Add 200g crushed tomatoes and simmer for 10 minutes. Simmer 4 large franks in water for 5 minutes, drain and griddle for 2 minutes a side. Warm 200g sauerkraut in a saucepan for 5 minutes and steam 4 buns for 1 minute. Assemble with 4 tbsp yellow mustard and the tomato onions.","shop":["2 brown onions@Produce","20g butter@Dairy","200g crushed tomatoes@Pantry","4 large hot dog franks@Meat","200g sauerkraut@Pantry","4 hot dog buns@Bakery","4 tbsp yellow mustard@Pantry"]}],"w":[{"n":"Snowball fight cupcakes","note":"Vanilla cupcakes domed with cream cheese frosting and shredded coconut.","how":"Heat the oven to 180C. Beat 80g soft butter with 80g caster sugar, add 1 egg and 1 tsp vanilla, then fold in 100g self-raising flour and 40ml milk. Divide between 4 large cupcake cases and bake for 18 minutes. Cool completely. Beat 100g cream cheese with 20g butter and 100g icing sugar, dome over the cakes and roll in 40g shredded coconut.","shop":["100g butter@Dairy","80g caster sugar@Pantry","1 egg@Dairy","1 tsp vanilla extract@Pantry","100g self-raising flour@Pantry","40ml full cream milk@Dairy","100g cream cheese@Dairy","100g icing sugar@Pantry","40g shredded coconut@Pantry"]}],"d":[{"n":"World's best cup of coffee","note":"Strong diner coffee with milk and sugar on the table.","how":"Brew 60g ground coffee with 1 litre hot water through a drip filter. Divide between 4 mugs and put 200ml milk and 40g caster sugar on the table.","shop":["60g ground coffee@Drinks","200ml full cream milk@Dairy","40g caster sugar@Pantry"]}],"shopping":["60g popping corn@Pantry","1 tbsp vegetable oil@Pantry","200ml maple syrup@Pantry","12 pretzel rods@Pantry","150g white chocolate@Pantry","60g candy canes@Pantry","2 brown onions@Produce","200g crushed tomatoes@Pantry","4 large hot dog franks@Meat","200g sauerkraut@Pantry","4 hot dog buns@Bakery","4 tbsp yellow mustard@Pantry","1 egg@Dairy","1 tsp vanilla extract@Pantry","100g self-raising flour@Pantry","100g cream cheese@Dairy","100g icing sugar@Pantry","40g shredded coconut@Pantry","60g ground coffee@Drinks","160g butter@Dairy","240ml full cream milk@Dairy","120g caster sugar@Pantry"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Midnight Cowboy (1969)":{"poster":"assets/menu-posters/midnight-cowboy-1969.jpg","colour":"#795237","servings":4,"tagline":"Big city. Small bank balance.","cue":"Serve the mains when Joe and Ratso plan their bus trip to Florida.","menu":{"s":[{"n":"Automat sandwiches","note":"Crustless ham and Swiss sandwiches spread with mustard butter.","how":"Mix 40g soft butter with 1 tbsp Dijon mustard. Spread over 8 slices white bread and fill with 160g leg ham and 100g Swiss cheese. Remove crusts, cut each sandwich into quarters and wrap in wax paper.","shop":["40g butter@Dairy","1 tbsp Dijon mustard@Pantry","8 slices white bread@Bakery","160g leg ham@Deli","100g Swiss cheese@Deli"]},{"n":"Coffee and doughnuts","note":"Warm cake doughnuts shaken in cinnamon sugar with diner coffee.","how":"Warm 4 plain cake doughnuts at 160C for 5 minutes. Mix 30g caster sugar with 1 tsp ground cinnamon and shake the hot doughnuts in it. Brew 30g ground coffee with 500ml hot water and serve in diner mugs.","shop":["4 plain cake doughnuts@Bakery","30g caster sugar@Pantry","1 tsp ground cinnamon@Pantry","30g ground coffee@Drinks"]}],"m":[{"n":"Condemned building franks and beans","note":"Browned franks and smoky beans with molasses, mustard and toast.","how":"Brown 400g sliced franks in 1 tbsp oil for 5 minutes. Add 1 diced brown onion and soften for 8 minutes. Add 800g baked beans, 1 tsp smoked paprika, 1 tbsp molasses and 1 tbsp yellow mustard. Simmer gently for 20 minutes, stirring. Toast 4 slices white bread and serve alongside.","shop":["400g hot dog franks@Meat","1 tbsp vegetable oil@Pantry","1 brown onion@Produce","800g baked beans@Pantry","1 tsp smoked paprika@Pantry","1 tbsp molasses@Pantry","1 tbsp yellow mustard@Pantry","4 slices white bread@Bakery"]}],"w":[{"n":"Florida orange cake","note":"Whole orange and almond cake baked until golden and fragrant.","how":"Boil 2 whole oranges in water for 1 hour, topping up the water as needed. Cool, remove seeds and blitz whole oranges. Mix with 6 eggs, 250g caster sugar, 250g almond meal and 1 tsp baking powder. Pour into a lined 22cm tin and bake at 180C for 1 hour. Cool before cutting into 4 generous portions, with leftovers.","shop":["2 oranges@Produce","6 eggs@Dairy","250g caster sugar@Pantry","250g almond meal@Pantry","1 tsp baking powder@Pantry"]}],"d":[{"n":"Cheap coffee","note":"Strong drip coffee with milk and two sugars in thick mugs.","how":"Brew 60g ground coffee with 1 litre hot water through a drip filter. Divide between 4 thick mugs and add 25ml milk and 2 tsp sugar to each.","shop":["60g ground coffee@Drinks","100ml full cream milk@Dairy","8 tsp caster sugar@Pantry"]}],"shopping":["40g butter@Dairy","1 tbsp Dijon mustard@Pantry","160g leg ham@Deli","100g Swiss cheese@Deli","4 plain cake doughnuts@Bakery","1 tsp ground cinnamon@Pantry","400g hot dog franks@Meat","1 tbsp vegetable oil@Pantry","1 brown onion@Produce","800g baked beans@Pantry","1 tsp smoked paprika@Pantry","1 tbsp molasses@Pantry","1 tbsp yellow mustard@Pantry","2 oranges@Produce","6 eggs@Dairy","250g almond meal@Pantry","1 tsp baking powder@Pantry","100ml full cream milk@Dairy","12 slices white bread@Bakery","90g ground coffee@Drinks","280g caster sugar plus 8 tsp@Pantry"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Dog Day Afternoon (1975)":{"poster":"assets/menu-posters/dog-day-afternoon-1975.jpg","colour":"#8c3027","servings":4,"tagline":"Pizza for the hostages.","cue":"Order the pizza when it gets delivered to the bank.","menu":{"s":[{"n":"Attica chips and onion dip","note":"Ridged chips with caramelised onion, sour cream and chive dip.","how":"Slice 2 brown onions and caramelise in 20g butter over low heat for 40 minutes. Cool for 20 minutes. Stir into 200g sour cream and 100g cream cheese with 10g chopped chives and 1/4 tsp salt. Serve with 150g ridged potato chips.","shop":["2 brown onions@Produce","20g butter@Dairy","200g sour cream@Dairy","100g cream cheese@Dairy","10g chives@Produce","1/4 tsp fine salt@Pantry","150g ridged potato chips@Pantry"]},{"n":"Bank vault pretzels and cheese","note":"Hard pretzels with sharp cheddar, beer, mustard and garlic dip.","how":"Blitz 150g grated sharp cheddar, 100g cream cheese, 50ml lager, 1 tbsp Dijon mustard and 1 crushed garlic clove until smooth. Refrigerate for 30 minutes and serve with 150g hard pretzels.","shop":["150g sharp cheddar@Dairy","100g cream cheese@Dairy","50ml lager@Bottle shop","1 tbsp Dijon mustard@Pantry","1 garlic clove@Produce","150g hard pretzels@Pantry"]}],"m":[{"n":"Hostage pizza","note":"Thin pizzas with crushed tomato, mozzarella, pepperoni and oregano.","how":"Mix 400g strong bread flour, 260ml water, 2g instant yeast and 8g fine salt. Knead for 10 minutes, cover and cold-ferment for 48 hours. Divide into 2 balls and bring to room temperature for 2 hours. Preheat a baking steel at the oven maximum, ideally 275C, for 45 minutes. Stretch into two thin 30cm pizzas. Top with 250g crushed tomatoes mixed with 1/4 tsp salt and 1 tsp oregano, 250g low-moisture mozzarella and 100g pepperoni. Bake each on the steel for 7 minutes until browned and cooked.","shop":["400g strong bread flour@Pantry","2g instant yeast@Pantry","8g fine salt@Pantry","250g crushed tomatoes@Pantry","1/4 tsp fine salt@Pantry","1 tsp dried oregano@Pantry","250g low-moisture mozzarella@Dairy","100g pepperoni@Deli"]}],"w":[{"n":"Italian ice","note":"Fresh lemon ice scraped into bright, refreshing frozen crystals.","how":"Simmer 200g caster sugar with 500ml water and the finely grated zest of 2 lemons for 3 minutes. Cool, add 250ml lemon juice from about 5 lemons and pour into a shallow tray. Freeze for 3 hours, scraping with a fork every 30 minutes. Divide between 4 bowls.","shop":["200g caster sugar@Pantry","5 lemons@Produce"]}],"d":[{"n":"Cold lager","note":"Cold lager cans served straight from an ice-filled esky.","how":"Nestle 4 cans of American lager in an esky with 2kg ice. Chill for 30 minutes and serve straight from the cans.","shop":["4 cans American lager@Bottle shop","2kg ice@Frozen"]}],"shopping":["2 brown onions@Produce","20g butter@Dairy","200g sour cream@Dairy","10g chives@Produce","150g ridged potato chips@Pantry","150g sharp cheddar@Dairy","50ml lager@Bottle shop","1 tbsp Dijon mustard@Pantry","1 garlic clove@Produce","150g hard pretzels@Pantry","400g strong bread flour@Pantry","2g instant yeast@Pantry","250g crushed tomatoes@Pantry","1 tsp dried oregano@Pantry","250g low-moisture mozzarella@Dairy","100g pepperoni@Deli","200g caster sugar@Pantry","5 lemons@Produce","4 cans American lager@Bottle shop","2kg ice@Frozen","200g cream cheese@Dairy","8g fine salt plus 1/2 tsp@Pantry"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"The Out-of-Towners (1970)":{"poster":"assets/menu-posters/the-out-of-towners-1970.jpg","colour":"#205455","servings":4,"tagline":"Every possible thing goes wrong.","cue":"Serve dessert when George finally gets to eat something.","menu":{"s":[{"n":"Handbag biscuits","note":"Buttery shortbread fingers baked golden and wrapped in a napkin.","how":"Rub 100g butter into 150g plain flour and 50g icing sugar. Press into a lined 15cm square tin, score into 8 fingers and bake at 160C for 25 minutes. Cool for 15 minutes, cut along the score lines and wrap in napkins.","shop":["100g butter@Dairy","150g plain flour@Pantry","50g icing sugar@Pantry"]},{"n":"Airline peanuts","note":"Warm dry-roasted peanuts tossed with salt and brown sugar.","how":"Toss 160g dry-roasted peanuts with 1/4 tsp fine salt and 2 tsp brown sugar. Spread on a tray and warm at 160C for 5 minutes. Divide between 4 small paper packets.","shop":["160g dry-roasted peanuts@Pantry","1/4 tsp fine salt@Pantry","2 tsp brown sugar@Pantry"]}],"m":[{"n":"Hotel rib eye breakfast","note":"Seared rib eye, fried eggs, crisp hash browns and buttered toast.","how":"Grate 600g potatoes and squeeze dry in a tea towel. Season with 1/2 tsp salt, shape into 4 hash browns and fry in 40g butter over medium heat for 6 minutes a side. Sear 4 rib eye steaks, 200g each, in a very hot pan with 1 tbsp oil for about 3 minutes a side to 54C, then rest for 8 minutes. Fry 8 eggs in 20g butter for 3 minutes. Toast 4 sourdough slices and spread with 20g butter. Serve one steak, two eggs, one hash brown and one toast per person.","shop":["600g potatoes@Produce","1/2 tsp fine salt@Pantry","80g butter@Dairy","800g rib eye steak@Meat","1 tbsp vegetable oil@Pantry","8 eggs@Dairy","4 slices sourdough@Bakery"]}],"w":[{"n":"Waldorf cheesecake","note":"Baked New York cheesecake chilled overnight and topped with strawberries.","how":"Crush 120g digestive biscuits and mix with 50g melted butter. Press into a lined 18cm springform tin. Beat 400g cream cheese with 100g caster sugar, then mix in 100g sour cream, 2 eggs and 1 tsp vanilla. Pour over the base. Wrap the tin in two layers of foil and stand in a roasting dish with hot water halfway up its sides. Bake at 150C for 70 minutes until the centre gently wobbles. Cool for 1 hour, refrigerate overnight and top with 200g sliced strawberries. Cut four generous portions, with leftovers.","shop":["120g digestive biscuits@Pantry","50g butter@Dairy","400g cream cheese@Dairy","100g caster sugar@Pantry","100g sour cream@Dairy","2 eggs@Dairy","1 tsp vanilla extract@Pantry","200g strawberries@Produce"]}],"d":[{"n":"Hotel bar martini","note":"Gin and dry vermouth stirred cold with an olive garnish.","how":"For each of 4 drinks stir 60ml gin and 10ml dry vermouth over ice for 30 seconds. Strain into a frozen martini glass and garnish with 1 green olive.","shop":["240ml gin@Bottle shop","40ml dry vermouth@Bottle shop","500g ice@Frozen","4 green olives@Pantry"]}],"shopping":["150g plain flour@Pantry","50g icing sugar@Pantry","160g dry-roasted peanuts@Pantry","2 tsp brown sugar@Pantry","600g potatoes@Produce","800g rib eye steak@Meat","1 tbsp vegetable oil@Pantry","4 slices sourdough@Bakery","120g digestive biscuits@Pantry","400g cream cheese@Dairy","100g caster sugar@Pantry","100g sour cream@Dairy","1 tsp vanilla extract@Pantry","200g strawberries@Produce","240ml gin@Bottle shop","40ml dry vermouth@Bottle shop","500g ice@Frozen","4 green olives@Pantry","230g butter@Dairy","3/4 tsp fine salt@Pantry","10 eggs@Dairy"]}}});
